import type { BankQuestion } from "@/lib/bank";

/** HR, Organisational Behaviour & Principles of Management (Management & Commerce): 643 questions. Append new ones at the end with the next id; never reuse or renumber an id. */
const questions: BankQuestion[] = [
  {"id":"mgmt-hr-ob-1","question":"Which of these is NOT one of the core functions of management in the POSDC framework?","options":["Planning","Marketing","Staffing","Controlling"],"answer":1,"explanation":"POSDC stands for planning, organising, staffing, directing and controlling. Marketing is a business function, not a management function.","difficulty":"easy","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-2","question":"A machine operator gets conflicting instructions from both the production manager and the quality manager every day. Which of Fayol's principles is being violated?","options":["Unity of direction","Scalar chain","Unity of command","Division of work"],"answer":2,"explanation":"Unity of command says each employee should receive orders from only one superior. Unity of direction concerns one plan and one head for each group of activities with the same objective.","difficulty":"easy","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-3","question":"A factory engineer times each worker's movements with a stopwatch to find the single best way of doing every task and then trains all workers in it. Which approach is this?","options":["Human relations approach","Contingency approach","Bureaucratic management","Scientific management"],"answer":3,"explanation":"Time-and-motion study to find the 'one best way' is the core of F. W. Taylor's scientific management.","difficulty":"easy","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-4","question":"Two supervisors at the same level in different departments need to coordinate urgently. With their managers' permission, they talk directly instead of routing every message up and down the hierarchy. Which Fayol concept allows this?","options":["Esprit de corps","Unity of command","Gang plank","Centralisation"],"answer":2,"explanation":"The gang plank is a direct horizontal link between people at the same level, used with superiors' consent to avoid delays in the scalar chain.","difficulty":"moderate","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-5","question":"A company has two separate marketing plans for the same product, each run by a different manager with different goals. Which of Fayol's principles is violated?","options":["Unity of command","Unity of direction","Equity","Order"],"answer":1,"explanation":"Unity of direction requires one head and one plan for a group of activities with the same objective. Here one objective has two plans and two heads.","difficulty":"moderate","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-6","question":"A group CEO spends most of her time thinking about how the firm's businesses fit together and where the industry will be in ten years. According to Katz, which skill matters most for her role?","options":["Conceptual skill","Human skill","Technical skill","Clerical skill"],"answer":0,"explanation":"Katz argued that conceptual skills — seeing the organisation as a whole — matter most at the top, technical skills at the bottom and human skills at every level.","difficulty":"moderate","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-7","question":"A plant head spends a week bargaining with the union over a new wage agreement. Which Mintzberg managerial role is she performing?","options":["Figurehead","Liaison","Monitor","Negotiator"],"answer":3,"explanation":"Negotiator is one of Mintzberg's decisional roles: representing the organisation in major negotiations. Figurehead and liaison are interpersonal roles; monitor is informational.","difficulty":"moderate","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-8","question":"After a leadership meeting, a manager briefs her team on new priorities and passes on relevant facts. Which Mintzberg role is this?","options":["Entrepreneur","Spokesperson","Disseminator","Resource allocator"],"answer":2,"explanation":"The disseminator role passes information received from outside or above to members of one's own unit. The spokesperson role transmits information to outsiders.","difficulty":"moderate","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-9","question":"In an organisation, every task is governed by written rules, positions form a clear hierarchy, decisions are impersonal and promotion depends on qualifications. This is closest to whose model?","options":["Mary Parker Follett's integration model","Elton Mayo's human relations model","Henri Fayol's administrative theory","Max Weber's bureaucracy"],"answer":3,"explanation":"Weber's ideal bureaucracy rests on rules, hierarchy, specialisation, impersonality, written records and merit-based careers.","difficulty":"moderate","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-10","question":"Taylor's functional foremanship put eight specialist foremen over each worker. Which of Fayol's principles does this most directly conflict with?","options":["Unity of command","Division of work","Discipline","Remuneration"],"answer":0,"explanation":"With several foremen giving instructions, the worker has multiple bosses, which conflicts with unity of command.","difficulty":"hard","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-11","question":"Under Taylor's differential piece-rate system, the standard is 10 units a day. Workers who meet the standard earn ₹50 per unit; those below it earn ₹40 per unit. Worker A makes 12 units and Worker B makes 9. How much more does A earn than B in a day?","options":["₹150","₹240","₹200","₹120"],"answer":1,"explanation":"A = 12 × 50 = ₹600; B = 9 × 40 = ₹360; difference = ₹240. The higher rate rewards those who reach the standard, which was Taylor's aim.","difficulty":"hard","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-12","question":"A new manager stops the previous head's habit of playing team members against each other and instead builds team spirit and open communication. Which Fayol principle is she applying?","options":["Order","Centralisation","Esprit de corps","Scalar chain"],"answer":2,"explanation":"Esprit de corps means 'union is strength': managers should promote harmony and unity, not divide and rule.","difficulty":"hard","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-13","question":"A bank transfers its branch managers every few months, and staff turnover and errors rise sharply. Which Fayol principle has been neglected?","options":["Stability of tenure of personnel","Unity of direction","Equity","Initiative"],"answer":0,"explanation":"Fayol held that employees need time to learn their jobs; unnecessary turnover is both the cause and effect of poor management.","difficulty":"hard","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-14","question":"Match each Fayol principle with its description.\nA. Putting the right person and material in the right place\nB. Kindliness and justice in dealing with employees\nC. Encouraging employees to propose and carry out plans\nD. Putting the organisation's goals ahead of personal interests\n1. Equity  2. Order  3. Subordination of individual interest to general interest  4. Initiative","options":["A-1, B-2, C-4, D-3","A-2, B-1, C-4, D-3","A-2, B-4, C-1, D-3","A-2, B-1, C-3, D-4"],"answer":1,"explanation":"Order = a place for everything and everyone; equity = kindliness and justice; initiative = freedom to think out and execute plans; and the general interest must prevail over individual interest.","difficulty":"very-hard","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-15","question":"A claims clerk refuses to process an urgent, valid insurance claim because the form was filled in blue ink instead of black, as the rulebook demands. Which weakness of bureaucracy does this show?","options":["Unity of command","Excessive decentralisation","Lack of specialisation","Goal displacement — following rules becomes an end in itself"],"answer":3,"explanation":"Rigid rule-following can replace the purpose the rules were meant to serve, a dysfunction often called goal displacement or 'red tape'.","difficulty":"hard","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-16","question":"In a set of factory experiments, output rose both when lighting was increased and when it was reduced, apparently because workers felt they were being noticed. These studies gave rise to which school of thought?","options":["Scientific management","Bureaucratic theory","Human relations movement","Quantitative management"],"answer":2,"explanation":"The Hawthorne studies, associated with Elton Mayo, showed that social factors and attention influence productivity, launching the human relations movement.","difficulty":"hard","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-17","question":"Which is the correct order of steps in the controlling process?","options":["Measure performance → set standards → take corrective action → compare","Set standards → measure performance → compare with standards → take corrective action","Compare with standards → set standards → measure performance → take corrective action","Set standards → take corrective action → measure performance → compare"],"answer":1,"explanation":"Controlling starts with standards, then measures actual performance, compares it with the standards and corrects significant deviations.","difficulty":"hard","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-18","question":"A plant manager tells supervisors: \"Don't send me every daily number. Report only when scrap goes above 3% or output falls 10% below plan.\" This is:","options":["Management by exception","Management by objectives","Feedforward control","Zero-based budgeting"],"answer":0,"explanation":"Management by exception reserves senior attention for significant deviations from plan, letting routine variances be handled lower down.","difficulty":"very-hard","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-19","question":"A food company tests every batch of incoming raw milk for quality before it enters the production line. This is an example of:","options":["Feedback control","Concurrent control","Bureaucratic control","Feedforward control"],"answer":3,"explanation":"Feedforward (preventive) control acts on inputs before the process starts. Concurrent control monitors during the process; feedback control examines results afterwards.","difficulty":"hard","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-20","question":"Assertion (A): Taylor's functional foremanship conflicts with Fayol's principle of unity of command.\nReason (R): Under functional foremanship, a worker takes instructions from several specialist foremen.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":0,"explanation":"Unity of command means one boss per worker. Several specialist foremen means several bosses, so R explains A.","difficulty":"very-hard","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-21","question":"Consider these statements comparing Fayol and Taylor:\nI. Fayol looked at management from the top level; Taylor focused on the shop floor.\nII. Fayol offered general principles of administration; Taylor stressed scientific study of tasks.\nIII. Both rejected the use of incentive pay.\nWhich are correct?","options":["I and II only","I, II and III","II and III only","I only"],"answer":0,"explanation":"I and II are correct. III is false: Taylor strongly favoured incentive pay through the differential piece-rate system.","difficulty":"very-hard","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-22","question":"A consultant tells a client: \"There is no single best way to organise. The right structure depends on your technology, environment and size.\" Which school of management does this reflect?","options":["Classical approach","Contingency approach","Scientific management","Bureaucratic approach"],"answer":1,"explanation":"The contingency (situational) approach holds that effective practice depends on the circumstances, rejecting universal 'one best way' prescriptions.","difficulty":"hard","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-23","question":"Taylor argued that managers and workers should stop fighting over how to divide the surplus and instead cooperate to increase it. He called this:","options":["Functional foremanship","Scientific selection of workers","Mental revolution","Management by exception"],"answer":2,"explanation":"Taylor's 'mental revolution' was a change of attitude on both sides — from conflict over shares to cooperation in enlarging the total surplus.","difficulty":"hard","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-24","question":"A company has 4,096 front-line workers. How many managers (at all levels above the workers) does it need with a uniform span of control of 8, compared with a span of 4?","options":["4 vs 6","512 vs 1,024","585 vs 1,024","585 vs 1,365"],"answer":3,"explanation":"Span 8: 512 + 64 + 8 + 1 = 585 managers in 4 levels. Span 4: 1,024 + 256 + 64 + 16 + 4 + 1 = 1,365 managers in 6 levels. Doubling the span saves 780 managers and two levels.","difficulty":"very-hard","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-25","question":"Match each plan with an example.\nA. Policy  B. Procedure  C. Rule  D. Budget\n1. The step-by-step method for claiming travel reimbursement\n2. A plan stated in numbers for a period\n3. \"We prefer to fill vacancies by promoting from within\"\n4. \"Smoking is not allowed on the factory floor\"","options":["A-3, B-1, C-4, D-2","A-4, B-1, C-3, D-2","A-3, B-2, C-4, D-1","A-1, B-3, C-4, D-2"],"answer":0,"explanation":"A policy guides thinking and leaves discretion; a procedure sets the sequence of steps; a rule says what must or must not be done, with no discretion; a budget is a plan in numbers.","difficulty":"very-hard","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-26","question":"A company draws up a one-time plan to build and commission a new plant within 18 months. This is best classified as a:","options":["Standing plan","Policy","Single-use plan","Rule"],"answer":2,"explanation":"Single-use plans (programmes, projects, budgets) are made for a specific, non-recurring purpose. Standing plans such as policies, procedures and rules are used repeatedly.","difficulty":"moderate","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-27","question":"What is the distinguishing feature of Management by Objectives (MBO)?","options":["Top management sets objectives and passes them down unchanged","Superior and subordinate jointly set specific objectives and later review performance against them","Employees choose their own goals without managerial input","Performance is judged only on personal traits"],"answer":1,"explanation":"MBO, popularised by Peter Drucker, relies on joint goal setting, periodic review and appraisal against agreed objectives.","difficulty":"hard","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-28","question":"Which of these goals best meets the SMART criteria?","options":["Improve customer satisfaction soon","Work harder on new accounts this year","Be the best sales team in the country","Raise repeat-purchase rate in the South zone from 30% to 36% by 31 March"],"answer":3,"explanation":"The second goal is specific, measurable, achievable, relevant and time-bound. The others lack a measure, a deadline or both.","difficulty":"moderate","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-29","question":"Consider these reasons why an MBO programme might fail:\nI. Objectives are imposed from above with no real participation.\nII. Focus on short-term measurable goals crowds out long-term ones.\nIII. MBO needs no periodic progress reviews.\nWhich are valid reasons for failure?","options":["I and II only","I, II and III","II and III only","III only"],"answer":0,"explanation":"I and II are well-known pitfalls. III is false as a statement about MBO: periodic review is an essential part of it, and skipping reviews is itself a cause of failure.","difficulty":"very-hard","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-30","question":"A mid-sized manufacturer groups its staff into production, finance, marketing and HR departments, each headed by a specialist. What structure is this?","options":["Divisional structure","Network structure","Matrix structure","Functional structure"],"answer":3,"explanation":"A functional structure groups jobs by specialist activity. It is efficient for a single product line but can create silos.","difficulty":"easy","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-31","question":"When a manager delegates a task to a subordinate, which of these does the manager still keep?","options":["The authority to do the task","Ultimate accountability for the result","The work itself","Nothing — everything is transferred"],"answer":1,"explanation":"Authority can be delegated, but the delegator remains ultimately accountable to their own superior for the outcome.","difficulty":"easy","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-32","question":"News of an upcoming reorganisation spreads through an office via informal chats long before any official announcement. This informal communication network is called the:","options":["Scalar chain","Formal channel","Gang plank","Grapevine"],"answer":3,"explanation":"The grapevine is the informal communication network. It is fast and often partly accurate, and managers can use it as well as fight rumours.","difficulty":"easy","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-33","question":"A company runs three unrelated businesses — paints, packaged foods and insurance — and each has its own production, marketing and finance teams under a business head. What structure is this?","options":["Functional","Matrix","Divisional","Line"],"answer":2,"explanation":"A divisional structure creates self-contained units by product, region or customer. It improves focus and accountability but duplicates functions.","difficulty":"moderate","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-34","question":"Engineers in an infrastructure firm report to their functional head for technical standards and to a project manager for day-to-day project work. What structure is this?","options":["Functional","Divisional","Network","Matrix"],"answer":3,"explanation":"A matrix structure combines functional and project (or product) lines, so employees have two bosses.","difficulty":"moderate","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-35","question":"A company widens the average span of control from 5 to 12 subordinates per manager. What is the most likely effect on its structure?","options":["It becomes taller with more levels","It becomes flatter with fewer levels","Its number of levels stays the same","It becomes more centralised"],"answer":1,"explanation":"A wider span means fewer managers are needed at each level, so the hierarchy becomes flatter.","difficulty":"moderate","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-36","question":"Which situation calls for a narrow span of control?","options":["Subordinates do routine, standardised work","Subordinates are highly skilled and experienced","Work is complex and novel and needs close guidance","Good information systems and clear procedures exist"],"answer":2,"explanation":"Complex, changing work and inexperienced staff need close supervision, so spans are narrower. The other three conditions allow wider spans.","difficulty":"moderate","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-37","question":"An HR specialist advises the production manager on how to handle a disciplinary case, but the production manager makes the final decision. The HR specialist is exercising:","options":["Staff authority","Line authority","Functional authority","Charismatic authority"],"answer":0,"explanation":"Staff authority is advisory: specialists recommend, while line managers in the chain of command decide.","difficulty":"moderate","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-38","question":"A purchase manager stops evaluating suppliers as soon as she finds one that meets the minimum requirements on price and quality, rather than searching for the best possible supplier. This is:","options":["Optimising","Groupthink","Escalation of commitment","Satisficing under bounded rationality"],"answer":3,"explanation":"Herbert Simon argued that limited time and information lead decision makers to 'satisfice' — accept the first acceptable option — rather than optimise.","difficulty":"moderate","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-39","question":"A highly cohesive top team rushes to approve an acquisition. Members who have doubts stay silent, and warning signs are dismissed. What is happening and what is a good remedy?","options":["Social loafing — assign individual tasks","Escalation of commitment — set a stop-loss rule","Groupthink — appoint a devil's advocate and invite outside views","Anchoring — use a different starting figure"],"answer":2,"explanation":"Groupthink is the pressure for agreement in cohesive groups that suppresses dissent. Devil's advocates, outside experts and leaders withholding their own view early help counter it.","difficulty":"hard","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-40","question":"A firm sends a forecasting questionnaire to experts who never meet. Their anonymous answers are summarised and sent back for several rounds until views converge. This is the:","options":["Nominal group technique","Delphi technique","Brainstorming","Devil's advocacy"],"answer":1,"explanation":"The Delphi technique uses anonymous, iterative rounds of expert input with controlled feedback, avoiding the influence of dominant personalities.","difficulty":"hard","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-41","question":"In a meeting, each member first writes down ideas silently, then the ideas are shared one by one without discussion, discussed briefly and finally ranked by private vote. This is the:","options":["Nominal group technique","Delphi technique","Brainstorming","Electronic meeting"],"answer":0,"explanation":"The nominal group technique keeps members together but structures the process so that everyone contributes independently before discussion and voting.","difficulty":"hard","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-42","question":"A store system automatically reorders a product whenever stock falls below 200 units. This is an example of a:","options":["Non-programmed decision","Decision under uncertainty","Strategic decision","Programmed decision"],"answer":3,"explanation":"Programmed decisions are routine and repetitive and can be handled by fixed rules. Non-programmed decisions are novel and unstructured.","difficulty":"hard","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-43","question":"A manager keeps pouring money into a failing software project, arguing that \"we have already spent ₹2 crore — we can't stop now.\" This is:","options":["Escalation of commitment (sunk-cost trap)","Anchoring bias","Availability bias","Confirmation bias"],"answer":0,"explanation":"Escalation of commitment is sticking with a losing course because of past investment. Sunk costs should be ignored; only future costs and benefits matter.","difficulty":"hard","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-44","question":"In a salary negotiation, the candidate opens with a high figure, and the final offer ends up much higher than the employer originally planned. Which bias most likely influenced the employer?","options":["Hindsight bias","Halo effect","Anchoring","Overconfidence"],"answer":2,"explanation":"Anchoring is relying too heavily on the first number offered; later adjustments stay close to that anchor.","difficulty":"hard","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-45","question":"Consider these statements about the matrix structure:\nI. Dual reporting can create role ambiguity and conflict.\nII. It allows specialist staff to be shared across projects.\nIII. It removes power struggles between functional and project managers.\nWhich are correct?","options":["I, II and III","I and II only","II and III only","I only"],"answer":1,"explanation":"I and II are correct. III is false: power struggles between the two lines of authority are a classic matrix problem.","difficulty":"hard","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-46","question":"A firm can launch a product itself (60% chance of ₹50 lakh profit, 40% chance of a ₹20 lakh loss) or license it for a guaranteed ₹18 lakh. Using expected monetary value, what should it do?","options":["License, because the launch EMV is ₹15 lakh","License, because ₹18 lakh is certain","Launch, because its EMV is ₹30 lakh","Launch, because its EMV is ₹22 lakh"],"answer":3,"explanation":"EMV of launching = 0.6 × 50 − 0.4 × 20 = 30 − 8 = ₹22 lakh, which beats ₹18 lakh. ₹30 lakh ignores the possible loss. A risk-averse firm might still license, but EMV favours launching.","difficulty":"hard","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-47","question":"For the same choice (launch: 60% chance of +₹50 lakh, 40% chance of −₹20 lakh; license: certain ₹18 lakh), what is the expected value of perfect information about whether the launch will succeed?","options":["₹4 lakh","₹15.2 lakh","₹37.2 lakh","₹7.2 lakh"],"answer":1,"explanation":"With perfect information the firm launches if success is coming (₹50 lakh) and licenses otherwise (₹18 lakh): 0.6 × 50 + 0.4 × 18 = ₹37.2 lakh. The best choice without information is worth ₹22 lakh, so EVPI = ₹15.2 lakh.","difficulty":"very-hard","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-48","question":"Assertion (A): A retail chain operating in very different regional markets often lets regional heads decide pricing and product range.\nReason (R): Decentralisation places decisions closer to the people with local market information.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":0,"explanation":"When markets differ, local knowledge matters more than uniformity, so decentralised decisions are faster and better informed — R explains A.","difficulty":"very-hard","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-49","question":"A sportswear company designs products and manages its brand in-house but outsources manufacturing, logistics and customer support to partner firms. This is best described as a:","options":["Functional structure","Tall structure","Network (virtual) structure","Matrix structure"],"answer":2,"explanation":"A network structure keeps a small core that coordinates independent partners performing other functions under contract.","difficulty":"very-hard","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-50","question":"According to Burns and Stalker, which type of structure suits a firm in a fast-changing, uncertain environment such as consumer technology?","options":["Organic: flexible roles, lateral communication, decentralised decisions","Mechanistic: rigid rules, narrow roles, vertical communication","Bureaucratic: strict hierarchy and written procedures","Functional: strict departmental boundaries"],"answer":0,"explanation":"Organic structures adapt quickly to change. Mechanistic structures work in stable, predictable environments.","difficulty":"very-hard","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-51","question":"Graicunas showed that the possible relationships between a manager and n subordinates equal n(2ⁿ⁻¹ + n − 1). How many relationships are there with 5 subordinates?","options":["25","100","44","20"],"answer":1,"explanation":"5 × (2⁴ + 5 − 1) = 5 × 20 = 100. The number grows far faster than the number of subordinates, which was Graicunas' argument for limiting the span.","difficulty":"very-hard","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-52","question":"Consider these statements about delegation:\nI. Authority delegated should match the responsibility assigned.\nII. Delegation reduces the delegator's own accountability.\nIII. Delegation helps develop subordinates for bigger roles.\nWhich are correct?","options":["I and III only","I, II and III","I and II only","II and III only"],"answer":0,"explanation":"I (parity of authority and responsibility) and III are correct. II is false: accountability cannot be delegated.","difficulty":"very-hard","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-53","question":"Match each structure with its defining feature.\nA. Functional  B. Divisional  C. Matrix  D. Network\n1. Employees report to two managers\n2. Grouping by specialist activity\n3. Self-contained units by product or region\n4. A small core firm coordinating outside partners","options":["A-2, B-3, C-4, D-1","A-3, B-2, C-1, D-4","A-2, B-1, C-3, D-4","A-2, B-3, C-1, D-4"],"answer":3,"explanation":"Functional = specialist grouping; divisional = self-contained units; matrix = dual reporting; network = coordinating outsourced partners.","difficulty":"very-hard","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-54","question":"Payoffs (₹ lakh) for three strategies under high and low demand are: S1 — 80 and 10; S2 — 60 and 30; S3 — 40 and 35. Which strategy does the minimax-regret criterion choose?","options":["S1","S2","S3","S1 and S3 tie"],"answer":1,"explanation":"Regret = best payoff in that state − payoff. High demand (best 80): S1 0, S2 20, S3 40. Low demand (best 35): S1 25, S2 5, S3 0. Maximum regrets: S1 25, S2 20, S3 40. The smallest maximum regret is S2.","difficulty":"very-hard","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-55","question":"Using the same payoffs (S1 — 80 high / 10 low; S2 — 60 / 30; S3 — 40 / 35), which strategy does a pessimistic decision maker using the maximin criterion choose?","options":["S1","S2","S3","Any of them"],"answer":2,"explanation":"Maximin picks the best of the worst outcomes: worst payoffs are 10, 30 and 35, so S3. An optimist (maximax) would choose S1.","difficulty":"hard","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-56","question":"A bank organises itself into separate retail banking, corporate banking and rural banking divisions, each serving a different type of client. This is departmentation by:","options":["Function","Product","Customer","Process"],"answer":2,"explanation":"Grouping activities around different client types is customer departmentation.","difficulty":"hard","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-57","question":"Which of these practices violates the basic rules of brainstorming?","options":["Encouraging wild ideas","Evaluating and criticising each idea as soon as it is proposed","Aiming for a large number of ideas","Building on other people's ideas"],"answer":1,"explanation":"Brainstorming separates idea generation from evaluation. Criticism during generation discourages people from contributing.","difficulty":"hard","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-58","question":"In a retail chain, every purchase above ₹5,000 at any store needs approval from head office. This indicates a high degree of:","options":["Centralisation","Decentralisation","Delegation","Departmentation"],"answer":0,"explanation":"Centralisation means decision-making authority is kept at the top of the organisation.","difficulty":"moderate","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-59","question":"After a round of layoffs, a team member says his biggest concern is whether his own job will still exist next year. In Maslow's hierarchy, which need is most active?","options":["Physiological","Esteem","Safety","Self-actualisation"],"answer":2,"explanation":"Job security and protection from threats belong to safety needs, the second level of Maslow's hierarchy.","difficulty":"easy","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-60","question":"A manager believes employees naturally dislike work, avoid responsibility and must be closely supervised and threatened with penalties. This matches:","options":["Maslow's self-actualisation","McGregor's Theory Y","Herzberg's motivators","McGregor's Theory X"],"answer":3,"explanation":"Theory X assumes people are lazy and need control; Theory Y assumes people can enjoy work, seek responsibility and exercise self-direction.","difficulty":"easy","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-61","question":"Which of these is a 'motivator' rather than a 'hygiene factor' in Herzberg's two-factor theory?","options":["Salary","Recognition for achievement","Company policy","Working conditions"],"answer":1,"explanation":"Motivators are intrinsic to the job: achievement, recognition, the work itself, responsibility and growth. Salary, policy and conditions are hygiene factors.","difficulty":"easy","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-62","question":"A production head pushes hard for output targets but shows little concern for his team's wellbeing. Where does he sit on the Blake–Mouton managerial grid?","options":["1,1 Impoverished","1,9 Country club","9,1 Authority-compliance","9,9 Team management"],"answer":2,"explanation":"The grid's first number is concern for production and the second is concern for people. 9,1 is high production, low people — authority-compliance (task) management.","difficulty":"moderate","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-63","question":"A team leader keeps everyone happy and avoids any pressure, even when deadlines slip badly. On the Blake–Mouton grid this is:","options":["9,1 Authority-compliance","5,5 Middle of the road","1,9 Country club","1,1 Impoverished"],"answer":2,"explanation":"1,9 country-club management shows high concern for people and low concern for production.","difficulty":"moderate","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-64","question":"A newly hired analyst lacks the skills for a task and feels anxious and unsure. According to Hersey and Blanchard, which leadership style fits best?","options":["Telling (S1)","Selling (S2)","Participating (S3)","Delegating (S4)"],"answer":0,"explanation":"A follower who is unable and unwilling or insecure (R1) needs telling: clear, specific instructions and close supervision.","difficulty":"moderate","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-65","question":"A senior engineer is highly skilled, confident and eager to own a project. Under Hersey–Blanchard's situational model, the manager should mainly use:","options":["Telling","Delegating","Participating","Selling"],"answer":1,"explanation":"An able and willing (R4) follower needs little direction or support, so delegating — handing over responsibility — fits.","difficulty":"moderate","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-66","question":"A sales executive prefers moderately difficult targets, wants frequent feedback on her performance and likes to take personal responsibility for results. Which need dominates, per McClelland?","options":["Need for security","Need for affiliation","Need for power","Need for achievement"],"answer":3,"explanation":"High-nAch people seek moderate-risk goals, quick feedback and personal responsibility for outcomes.","difficulty":"moderate","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-67","question":"A manager sets clear targets, rewards people who meet them and steps in only when performance goes off track. This style is best described as:","options":["Transformational leadership","Laissez-faire leadership","Transactional leadership","Servant leadership"],"answer":2,"explanation":"Transactional leadership relies on contingent rewards and management by exception. Transformational leadership inspires through vision and personal development.","difficulty":"moderate","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-68","question":"An experienced, skilled manager has lost confidence after a reorganisation changed her role. Under Hersey–Blanchard's model, which style should her boss use?","options":["Telling","Participating","Selling","Delegating"],"answer":1,"explanation":"She is able but insecure (R3), so she needs low direction and high support — participating, with shared decisions and encouragement.","difficulty":"hard","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-69","question":"A top performer is told that hitting next year's target will earn her a promotion to the Delhi office. She is confident she can hit the target and trusts the promise, but she has no wish to relocate. Her motivation to try is very low. In Vroom's terms, which factor is close to zero?","options":["Valence","Instrumentality","Expectancy","Equity"],"answer":0,"explanation":"Valence is the value placed on the reward. Because motivation = E × I × V, a near-zero valence makes motivation near zero even when expectancy and instrumentality are high.","difficulty":"hard","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-70","question":"An employee rates two assignments using Vroom's model. Assignment A: expectancy 0.9, instrumentality 0.6, valence 5. Assignment B: expectancy 0.5, instrumentality 0.9, valence 8. Which will she be more motivated to pursue?","options":["A, with a score of 2.7","They are equal","A, with a score of 4.5","B, with a score of 3.6"],"answer":3,"explanation":"A = 0.9 × 0.6 × 5 = 2.7; B = 0.5 × 0.9 × 8 = 3.6. B wins despite its lower expectancy because the reward is valued more highly.","difficulty":"hard","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-71","question":"An analyst discovers that a colleague doing the same work with similar experience earns 20% more. According to Adams' equity theory, which response is most likely?","options":["She will work harder to justify her lower pay","She will feel over-rewarded and guilty","She may reduce her effort, ask for a raise or start looking for another job","She will be unaffected because pay is a hygiene factor"],"answer":2,"explanation":"Perceived under-reward creates tension that people reduce by cutting inputs, seeking higher outcomes, changing the comparison or leaving.","difficulty":"hard","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-72","question":"Employee A earns ₹60,000 a month for 50 hours a week. His referent, B, earns ₹72,000 for 48 hours. To restore equity on a pay-per-hour basis without changing his hours, what should A earn?","options":["₹72,000","₹62,500","₹69,120","₹75,000"],"answer":3,"explanation":"B's ratio = 72,000 / 48 = ₹1,500 per hour. A's ratio is 60,000 / 50 = ₹1,200. At 50 hours, equity needs 50 × 1,500 = ₹75,000. Matching B's pay (₹72,000) ignores that A works longer.","difficulty":"very-hard","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-73","question":"A company raises salaries, improves the canteen and relaxes rigid policies. Complaints drop sharply, but employees show no extra enthusiasm or initiative. What best explains this according to Herzberg?","options":["The changes improved hygiene factors, which reduce dissatisfaction but do not create motivation","The changes improved motivators, which take time to work","Employees are Theory X types","The changes created inequity"],"answer":0,"explanation":"Hygiene factors prevent dissatisfaction; to motivate, the firm must enrich the job itself with responsibility, achievement, recognition and growth.","difficulty":"hard","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-74","question":"According to Locke's goal-setting theory, which instruction is most likely to raise a sales rep's performance?","options":["\"Do your best this quarter.\"","\"Increase client meetings from 40 to 50 a week; we'll review your numbers every Friday.\"","\"Try not to fall behind last year.\"","\"Make as many calls as you comfortably can.\""],"answer":1,"explanation":"Specific, challenging goals that the person accepts, combined with regular feedback, lead to higher performance than vague 'do your best' goals.","difficulty":"hard","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-75","question":"Consider these statements about Fiedler's contingency model:\nI. It treats a leader's style as relatively fixed.\nII. Task-oriented (low-LPC) leaders do best when situational control is either very high or very low.\nIII. It recommends that leaders simply change their style to suit each situation.\nWhich are correct?","options":["II and III only","I, II and III","I and II only","I only"],"answer":2,"explanation":"I and II are correct. Because Fiedler sees style as fixed, he suggests changing the situation or the leader, not the style — so III is false.","difficulty":"hard","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-76","question":"A new team faces vague, unstructured tasks and members are unsure what is expected. According to House's path–goal theory, which leader behaviour is likely to be most effective?","options":["Directive leadership — clarify goals, methods and schedules","Supportive leadership only","Laissez-faire leadership","Achievement-oriented leadership with stretch goals only"],"answer":0,"explanation":"Path–goal theory says directive behaviour helps when tasks are ambiguous; it is less useful (even resented) when tasks are already clear and routine.","difficulty":"hard","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-77","question":"A department head meets each team member regularly, understands their individual career goals and coaches them accordingly. Which component of transformational leadership is this?","options":["Idealised influence","Individualised consideration","Intellectual stimulation","Inspirational motivation"],"answer":1,"explanation":"Individualised consideration means attending to each follower's needs and acting as coach or mentor.","difficulty":"hard","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-78","question":"Match each transformational-leadership component with a behaviour.\nA. Idealised influence  B. Inspirational motivation  C. Intellectual stimulation  D. Individualised consideration\n1. Encourages the team to question assumptions and try new approaches\n2. Acts as a role model with high ethical standards\n3. Communicates an exciting vision and high expectations\n4. Coaches each person according to their needs","options":["A-2, B-3, C-4, D-1","A-3, B-2, C-1, D-4","A-2, B-1, C-3, D-4","A-2, B-3, C-1, D-4"],"answer":3,"explanation":"Idealised influence = role model; inspirational motivation = vision; intellectual stimulation = challenging assumptions; individualised consideration = coaching.","difficulty":"very-hard","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-79","question":"An employee repeatedly passed over for promotion stops seeking growth and instead becomes focused on pay rises and office friendships. Which theory explains this best?","options":["Maslow's strict hierarchy","Herzberg's two-factor theory","Alderfer's ERG theory (frustration–regression)","Adams' equity theory"],"answer":2,"explanation":"Alderfer's ERG theory adds frustration–regression: when growth needs are blocked, people regress to lower needs such as relatedness and existence.","difficulty":"very-hard","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-80","question":"Assertion (A): For an employee who is already fairly paid, a further pay rise may not increase motivation in Herzberg's view.\nReason (R): Herzberg classed pay as a hygiene factor, whose improvement removes dissatisfaction but does not create satisfaction.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":0,"explanation":"Once pay is adequate, more pay mainly prevents dissatisfaction; motivation comes from motivators. R explains A.","difficulty":"very-hard","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-81","question":"Consider these statements about McClelland's needs theory:\nI. People high in need for achievement prefer very high-risk goals.\nII. Effective senior managers often show a high need for institutional (socialised) power and relatively low need for affiliation.\nIII. People with a very high need for affiliation may avoid tough decisions that upset colleagues.\nWhich are correct?","options":["I only","I, II and III","I and II only","II and III only"],"answer":3,"explanation":"II and III are correct. High achievers prefer moderate risk where their effort makes the difference, so I is false.","difficulty":"very-hard","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-82","question":"Using Vroom's model (motivation = E × I × V, each on a 0–1 scale), which combination gives the highest motivation?","options":["E 0.9, I 0.9, V 0.2","E 0.6, I 0.6, V 0.6","E 1.0, I 0, V 1.0","E 0.5, I 0.8, V 0.7"],"answer":3,"explanation":"Products: 0.162, 0.216, 0 and 0.28. The last is highest. Because the terms multiply, a single weak factor drags the whole score down.","difficulty":"very-hard","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-83","question":"Match each employee's statement with the Vroom component that is weak.\nA. \"However hard I try, I can't hit that target with the leads I get.\"\nB. \"Even if I hit it, the bonus never actually gets paid.\"\nC. \"The reward is a gift voucher — I don't care about it.\"\n1. Instrumentality  2. Valence  3. Expectancy","options":["A-3, B-1, C-2","A-1, B-3, C-2","A-3, B-2, C-1","A-2, B-1, C-3"],"answer":0,"explanation":"Expectancy links effort to performance, instrumentality links performance to reward, and valence is how much the reward is valued.","difficulty":"very-hard","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-84","question":"In Hersey and Blanchard's model, which style combines high relationship behaviour with low task behaviour?","options":["Telling","Participating","Selling","Delegating"],"answer":1,"explanation":"Telling = high task, low relationship; selling = high task, high relationship; participating = low task, high relationship; delegating = low on both.","difficulty":"hard","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-85","question":"What is the main criticism of the trait approach to leadership?","options":["It ignores leaders' personal qualities","It focuses only on followers","No consistent set of traits reliably predicts leadership effectiveness across situations","It requires leaders to change their style frequently"],"answer":2,"explanation":"Research found that traits linked to leadership in one setting often did not hold in others, which led to behavioural and situational theories.","difficulty":"moderate","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-86","question":"The head of a research lab gives highly qualified scientists complete freedom to choose projects and methods, offering little direction or feedback. This is:","options":["Autocratic leadership","Laissez-faire (free-rein) leadership","Transactional leadership","Paternalistic leadership"],"answer":1,"explanation":"Laissez-faire leaders leave decisions to the group. It can work with expert, self-motivated teams but often fails with less experienced staff.","difficulty":"moderate","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-87","question":"A supervisor defines each team member's role, sets deadlines and specifies procedures. In the Ohio State studies, this behaviour is called:","options":["Initiating structure","Consideration","Employee orientation","Charisma"],"answer":0,"explanation":"The Ohio State studies identified two dimensions: initiating structure (organising tasks and roles) and consideration (trust, respect and concern for followers).","difficulty":"moderate","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-88","question":"A newly formed project team argues openly about who should lead, how work should be split and whose ideas matter most. In Tuckman's model, which stage is this?","options":["Forming","Performing","Norming","Storming"],"answer":3,"explanation":"Storming is marked by conflict over roles, leadership and direction. Forming is the polite, uncertain start; norming builds agreed rules and cohesion.","difficulty":"easy","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-89","question":"An employee is organised, dependable, careful and always meets deadlines. Which Big Five trait does this describe?","options":["Openness to experience","Extraversion","Conscientiousness","Agreeableness"],"answer":2,"explanation":"Conscientiousness covers being organised, responsible, persistent and achievement-oriented.","difficulty":"easy","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-90","question":"In Lewin's three-step model of change, what is the first step?","options":["Refreezing","Moving","Anchoring","Unfreezing"],"answer":3,"explanation":"Lewin's steps are unfreezing (preparing people to let go of the old way), moving (making the change) and refreezing (making it stick).","difficulty":"easy","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-91","question":"An interviewer is so impressed by a candidate's prestigious college that she also rates his teamwork and communication as excellent, without evidence. This is the:","options":["Contrast effect","Halo effect","Projection","Central tendency"],"answer":1,"explanation":"The halo effect is letting one positive characteristic shape the overall impression. The opposite (one negative trait colouring everything) is the horns effect.","difficulty":"moderate","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-92","question":"Faced with a dispute between two team members, a manager keeps postponing any discussion in the hope that it will fade away. Which Thomas–Kilmann conflict style is this?","options":["Accommodating","Avoiding","Compromising","Competing"],"answer":1,"explanation":"Avoiding is low on both assertiveness and cooperativeness: the issue is sidestepped or postponed.","difficulty":"moderate","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-93","question":"A manager gives in to a colleague's preference on a minor scheduling issue, mainly to preserve their good relationship. Which conflict style is this?","options":["Competing","Avoiding","Collaborating","Accommodating"],"answer":3,"explanation":"Accommodating is cooperative but unassertive — putting the other party's concerns first, often when the issue matters more to them or harmony is important.","difficulty":"moderate","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-94","question":"In a group assignment where only the final report is graded, some members contribute much less effort than when they work alone. This is known as:","options":["Groupthink","Group polarisation","Social loafing","Social facilitation"],"answer":2,"explanation":"Social loafing is reduced effort in groups when individual contributions cannot be identified. Making individual work visible and accountable reduces it.","difficulty":"moderate","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-95","question":"A visitor notices a company's open-plan office, casual dress and a wall of team photos. In Schein's model of culture, these are examples of:","options":["Artefacts","Espoused values","Basic underlying assumptions","Subcultures"],"answer":0,"explanation":"Artefacts are the visible, surface level of culture — structures, dress, rituals, layouts. Their deeper meaning lies in espoused values and basic assumptions.","difficulty":"moderate","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-96","question":"According to Kotter's eight-step model, what should a leader do first when launching a major change?","options":["Form a guiding coalition","Create a sense of urgency","Generate short-term wins","Anchor the change in the culture"],"answer":1,"explanation":"Kotter's model starts by establishing urgency — showing why change is needed now — before building a coalition and vision.","difficulty":"moderate","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-97","question":"An employee believes his career success depends mainly on luck and on who the boss likes, not on his own effort. He has:","options":["An external locus of control","An internal locus of control","High self-efficacy","High Machiavellianism"],"answer":0,"explanation":"People with an external locus of control attribute outcomes to outside forces such as luck or others; those with an internal locus credit their own actions.","difficulty":"moderate","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-98","question":"Ravi is late to every team meeting (high consistency), is also late for client calls and training (low distinctiveness), while his colleagues are rarely late (low consensus). According to Kelley's attribution theory, his manager will most likely attribute the lateness to:","options":["External causes such as traffic","Bad luck","The meeting schedule","Internal causes such as Ravi's own habits"],"answer":3,"explanation":"High consistency, low distinctiveness and low consensus together point to an internal (personal) cause.","difficulty":"hard","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-99","question":"On one particular day, almost everyone in the office arrives late (high consensus). Priya, who arrived late too, is usually punctual everywhere (low consistency) and is not generally late for other things (high distinctiveness). Her lateness is most likely to be attributed to:","options":["Internal causes","Her personality","External causes","Her lack of motivation"],"answer":2,"explanation":"High consensus, high distinctiveness and low consistency point to an external cause, such as a transport strike.","difficulty":"hard","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-100","question":"A sales head blames a rep's missed target on laziness, ignoring the fact that the rep's territory lost its largest customer to a plant closure. This illustrates the:","options":["Self-serving bias","Fundamental attribution error","Contrast effect","Similar-to-me error"],"answer":1,"explanation":"The fundamental attribution error is overestimating personal factors and underestimating situational factors when judging others' behaviour.","difficulty":"hard","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-101","question":"A manager credits his own strategy when sales rise but blames 'market conditions' when sales fall. This is:","options":["Fundamental attribution error","Halo effect","Self-serving bias","Stereotyping"],"answer":2,"explanation":"The self-serving bias attributes our own successes to internal factors and our failures to external ones.","difficulty":"hard","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-102","question":"Two department heads disagree on a new product's design. Both concerns are important, the issue is complex and there is time to work through it. Which conflict style is most appropriate?","options":["Competing","Compromising","Avoiding","Collaborating"],"answer":3,"explanation":"Collaborating — high assertiveness and high cooperativeness — seeks a solution that fully satisfies both sides. It needs time and trust, which are available here.","difficulty":"hard","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-103","question":"Two managers of equal power must agree on a shared budget before tomorrow's deadline. Both goals are moderately important, and each agrees to give up part of what they wanted. This is:","options":["Compromising","Collaborating","Accommodating","Competing"],"answer":0,"explanation":"Compromising finds a middle ground under time pressure or when power is balanced; each side gets part, not all, of what it wanted.","difficulty":"hard","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-104","question":"A plant manager immediately orders a production line shut down after a safety hazard is found, despite protests from the shift team about lost output. Which conflict style is appropriate here, and why?","options":["Accommodating — to keep the team happy","Competing — quick, decisive action is needed on a vital issue","Avoiding — to let tempers cool","Compromising — run the line at half speed"],"answer":1,"explanation":"Competing (assertive, uncooperative) suits emergencies and unpopular but vital decisions such as safety actions.","difficulty":"hard","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-105","question":"Before introducing new software, a manager lists forces pushing for it (faster reporting, client demands) and forces against it (fear of job loss, training time), and plans to strengthen the first and weaken the second. This tool is:","options":["SWOT analysis","PEST analysis","Johari window","Force-field analysis"],"answer":3,"explanation":"Lewin's force-field analysis compares driving and restraining forces; change happens when driving forces outweigh restraining ones. Reducing restraints often causes less tension than adding pressure.","difficulty":"hard","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-106","question":"A change team realises it lacks full information about shop-floor processes, and supervisors who could block the change hold considerable informal power. According to Kotter and Schlesinger, which approach to resistance fits best?","options":["Coercion","Manipulation and co-optation","Participation and involvement","Ignoring the resistance"],"answer":2,"explanation":"Participation works when initiators lack information and resisters have power: involving them improves the design and builds commitment, though it takes time.","difficulty":"very-hard","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-107","question":"Consider these statements about Kelley's attribution theory:\nI. High consensus points towards an external cause.\nII. High consistency points towards an internal cause.\nIII. High distinctiveness points towards an internal cause.\nWhich are correct?","options":["I and II only","I, II and III","II and III only","I only"],"answer":0,"explanation":"I and II are correct. High distinctiveness — the person behaves differently in other situations — points towards an external cause, so III is false.","difficulty":"very-hard","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-108","question":"Arrange these steps from Kotter's model in the correct order:\nP. Generate short-term wins\nQ. Form a powerful guiding coalition\nR. Anchor new approaches in the culture\nS. Establish a sense of urgency","options":["Q → S → P → R","S → Q → P → R","S → P → Q → R","S → Q → R → P"],"answer":1,"explanation":"Kotter's sequence: urgency, guiding coalition, vision and strategy, communicating the vision, empowering action, short-term wins, consolidating gains and finally anchoring change in the culture.","difficulty":"very-hard","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-109","question":"Which Big Five trait has been found to be the most consistent predictor of job performance across a wide range of occupations?","options":["Conscientiousness","Openness to experience","Extraversion","Agreeableness"],"answer":0,"explanation":"Conscientiousness relates to performance in almost all jobs. Extraversion predicts success mainly in sales and management roles.","difficulty":"hard","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-110","question":"A team leader receives harsh criticism from a client in a meeting, feels angry, but stays calm, thinks before responding and discusses the issue constructively. Which component of emotional intelligence (Goleman) is she showing?","options":["Self-awareness","Social skill","Empathy","Self-regulation"],"answer":3,"explanation":"Self-regulation is controlling disruptive impulses and moods and thinking before acting. Self-awareness is recognising one's emotions in the first place.","difficulty":"hard","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-111","question":"In the Johari window, which area contains things others know about a person but the person does not know about themselves, and what shrinks it?","options":["Hidden area — self-disclosure","Unknown area — self-discovery","Blind area — feedback from others","Open area — feedback from others"],"answer":2,"explanation":"The blind area is known to others but not to oneself. Seeking and accepting feedback reduces it; self-disclosure reduces the hidden area.","difficulty":"very-hard","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-112","question":"Assertion (A): A newly formed team that avoids openly discussing disagreements may slip back into conflict later.\nReason (R): Teams that do not work through storming-stage issues struggle to develop the shared norms needed for high performance.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":0,"explanation":"Unresolved conflict over roles and goals stays beneath the surface and resurfaces; agreed norms come from working through storming. R explains A.","difficulty":"very-hard","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-113","question":"Match each Thomas–Kilmann style with its position on assertiveness and cooperativeness.\nA. Competing  B. Accommodating  C. Avoiding  D. Collaborating\n1. High assertiveness, high cooperativeness\n2. Low assertiveness, low cooperativeness\n3. High assertiveness, low cooperativeness\n4. Low assertiveness, high cooperativeness","options":["A-1, B-4, C-2, D-3","A-4, B-3, C-2, D-1","A-3, B-2, C-4, D-1","A-3, B-4, C-2, D-1"],"answer":3,"explanation":"Competing = assertive and uncooperative; accommodating = cooperative and unassertive; avoiding = neither; collaborating = both. Compromising sits in the middle.","difficulty":"very-hard","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-114","question":"A young start-up prizes experimentation, risk-taking and launching new ideas quickly, with an external focus and flexible structure. In the competing values framework, which culture type is this?","options":["Clan","Market","Adhocracy","Hierarchy"],"answer":2,"explanation":"Adhocracy culture combines flexibility with an external focus and values innovation. Clan is flexible but internally focused; market is controlled and externally focused; hierarchy is controlled and internally focused.","difficulty":"very-hard","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-115","question":"Consider these statements about Hofstede's cultural dimensions:\nI. High uncertainty-avoidance cultures prefer clear rules and structured situations.\nII. Individualist cultures put loyalty to the group ahead of personal goals.\nIII. Long-term orientation values perseverance and thrift.\nWhich are correct?","options":["I, II and III","I and III only","I and II only","II and III only"],"answer":1,"explanation":"I and III are correct. II describes collectivism; individualist cultures emphasise personal goals and self-reliance.","difficulty":"very-hard","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-116","question":"A document lists the qualifications, experience, skills and personal qualities a person needs to do a job. This document is the:","options":["Job description","Job specification","Job evaluation","Job enrichment plan"],"answer":1,"explanation":"The job specification describes the person (qualifications, skills, traits). The job description describes the job (duties, tasks, responsibilities). Both come from job analysis.","difficulty":"easy","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-117","question":"Which of these is an internal source of recruitment?","options":["Campus placement","Placement agency","Newspaper advertisement","Internal job posting for current employees"],"answer":3,"explanation":"Internal job posting fills vacancies from existing staff. Campus drives, advertisements and agencies bring in outside candidates.","difficulty":"easy","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-118","question":"At the end of a workshop, participants fill in a form rating how useful and engaging they found the session. Which Kirkpatrick level is being measured?","options":["Level 3 — Behaviour","Level 2 — Learning","Level 1 — Reaction","Level 4 — Results"],"answer":2,"explanation":"Level 1 measures how participants felt about the training. It is the easiest to collect but says little about whether skills improved.","difficulty":"easy","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-119","question":"Three months after a coaching-skills programme, an HR team asks supervisors whether trainees are actually using the new techniques with their teams. Which Kirkpatrick level is this?","options":["Behaviour","Learning","Reaction","Results"],"answer":0,"explanation":"Level 3 checks whether learning has transferred into on-the-job behaviour. Level 2 tests knowledge or skill gained; level 4 measures business outcomes.","difficulty":"moderate","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-120","question":"Candidates' scores on a reasoning test taken at hiring are later found to correlate strongly with their performance ratings after a year. This shows that the test has good:","options":["Test–retest reliability","Predictive (criterion-related) validity","Face validity","Inter-rater reliability"],"answer":1,"explanation":"Predictive validity is the extent to which test scores forecast a later criterion such as job performance.","difficulty":"moderate","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-121","question":"A personality test given to the same group twice, a month apart, produces nearly identical scores. This indicates high:","options":["Test–retest reliability","Predictive validity","Content validity","Construct validity"],"answer":0,"explanation":"Reliability is consistency of measurement. Test–retest reliability checks whether the same people get similar scores on repeated testing.","difficulty":"moderate","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-122","question":"An appraisal form rates 'customer handling' on a 1–7 scale, with each point described by a specific example of behaviour, such as \"Listens fully and resolves the complaint on the first call\". This method is:","options":["Graphic rating scale","Paired comparison","Forced distribution","Behaviourally anchored rating scale (BARS)"],"answer":3,"explanation":"BARS anchors each scale point with concrete behavioural examples, reducing ambiguity compared with simple graphic scales.","difficulty":"moderate","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-123","question":"A manager's performance is reviewed using feedback from her boss, peers, direct reports and some internal customers, plus a self-assessment. This is:","options":["Management by objectives","Critical incident method","360-degree feedback","Ranking method"],"answer":2,"explanation":"360-degree feedback collects input from all around the employee, giving a broader picture than a single supervisor's rating.","difficulty":"moderate","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-124","question":"A supervisor rates almost every team member '3' on a five-point scale, avoiding both high and low ratings. This is the:","options":["Halo effect","Central tendency error","Leniency error","Recency error"],"answer":1,"explanation":"Central tendency error is clustering ratings in the middle, which hides real differences in performance.","difficulty":"moderate","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-125","question":"A sales manager gives a rep an outstanding annual rating mainly because the rep closed a big deal in the last month, though the first ten months were weak. This is the:","options":["Contrast error","Halo effect","Recency error","Strictness error"],"answer":2,"explanation":"The recency error lets recent events dominate the appraisal of the whole period. Keeping a record of critical incidents through the year reduces it.","difficulty":"hard","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-126","question":"A friendly manager rates everyone in her team 'exceeds expectations' to avoid disappointing anyone. This is the:","options":["Strictness error","Similar-to-me error","Central tendency error","Leniency error"],"answer":3,"explanation":"Leniency error is rating everyone higher than their performance deserves. It weakens the link between performance and rewards.","difficulty":"hard","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-127","question":"A company requires every manager to place 20% of the team in 'top', 70% in 'middle' and 10% in 'bottom' categories. What is the main criticism of this method?","options":["It may force managers to label someone a low performer even when the whole team performs well, hurting morale and collaboration","It allows managers to rate everyone highly","It takes too long to complete","It relies only on self-assessment"],"answer":0,"explanation":"Forced distribution counters leniency and central tendency, but in small or uniformly strong teams it creates artificial losers and can damage teamwork.","difficulty":"hard","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-128","question":"A training programme costs ₹12 lakh and produces measurable monetary benefits of ₹18 lakh. What is its ROI using the Phillips formula?","options":["150%","50%","66.7%","33.3%"],"answer":1,"explanation":"ROI = (benefits − costs) / costs × 100 = (18 − 12) / 12 × 100 = 50%. The benefit–cost ratio is 1.5, which is a different measure.","difficulty":"hard","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-129","question":"A company receives 1,250 applications and hires 50 people. What is its selection ratio?","options":["40%","25%","2.5%","4%"],"answer":3,"explanation":"Selection ratio = hires / applicants = 50 / 1,250 = 0.04, or 4%. A low ratio means the firm can be very selective.","difficulty":"moderate","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-130","question":"A firm needs 20 new hires. Historically 10% of applicants are shortlisted, 50% of those shortlisted attend the interview, 25% of interviewees receive offers and 80% of offers are accepted. How many applications must it attract?","options":["1,000","1,600","2,000","4,000"],"answer":2,"explanation":"Work backwards: offers = 20 / 0.8 = 25; interviewees = 25 / 0.25 = 100; shortlisted = 100 / 0.5 = 200; applicants = 200 / 0.10 = 2,000. This is the recruitment yield pyramid.","difficulty":"very-hard","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-131","question":"Why do structured interviews generally predict job performance better than unstructured interviews?","options":["Every candidate is asked the same job-related questions and scored against agreed criteria, reducing bias and inconsistency","They are shorter","They allow interviewers to follow their instincts","They focus on the candidate's personal background"],"answer":0,"explanation":"Standardised, job-related questions with scoring guides make comparisons fair and reduce first-impression and similar-to-me biases.","difficulty":"hard","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-132","question":"Management-trainee candidates spend two days on an in-basket exercise, a group discussion, a case presentation and a role-play, observed by several trained assessors. This selection method is:","options":["A realistic job preview","An assessment centre","A stress interview","A probation period"],"answer":1,"explanation":"Assessment centres use multiple exercises and multiple assessors to evaluate candidates on job-relevant competencies.","difficulty":"hard","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-133","question":"Match each Kirkpatrick level with the evidence an HR team might collect.\nA. Reaction  B. Learning  C. Behaviour  D. Results\n1. Fall in customer complaints in the trainees' branches\n2. Post-training quiz scores compared with pre-training scores\n3. End-of-session satisfaction ratings\n4. Supervisors observing trainees using the new process on the job","options":["A-3, B-2, C-4, D-1","A-2, B-3, C-4, D-1","A-3, B-4, C-2, D-1","A-3, B-2, C-1, D-4"],"answer":0,"explanation":"Reaction = satisfaction; learning = knowledge or skill gain (pre/post test); behaviour = on-the-job application; results = business outcomes.","difficulty":"very-hard","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-134","question":"A firm spends ₹10 lakh to train 40 sales reps. Afterwards each rep's monthly sales rise by ₹50,000 at a 20% gross margin, sustained for 6 months. HR estimates that 50% of the rise is due to the training. What is the training ROI?","options":["120%","140%","50%","20%"],"answer":3,"explanation":"Benefit = 40 × 50,000 × 0.20 × 6 × 0.5 = ₹12 lakh. ROI = (12 − 10) / 10 = 20%. Ignoring the 50% attribution gives ₹24 lakh and 140%.","difficulty":"very-hard","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-135","question":"A bank gives its loan officers authority to approve loans up to a limit, plan their own schedules and check their own work, instead of just processing files. This is:","options":["Job rotation","Job enlargement","Job enrichment","Job simplification"],"answer":2,"explanation":"Job enrichment adds vertical responsibility — planning, control and decision-making. Job enlargement adds more tasks at the same level; rotation moves people between jobs.","difficulty":"hard","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-136","question":"In Hackman and Oldham's model, Motivating Potential Score = [(skill variety + task identity + task significance) / 3] × autonomy × feedback. A job scores 5, 4 and 6 on the first three, 3 on autonomy and 4 on feedback. What is its MPS?","options":["180","60","22","20"],"answer":1,"explanation":"Average of the first three = (5 + 4 + 6) / 3 = 5. MPS = 5 × 3 × 4 = 60. Forgetting to divide by 3 gives 180. Because autonomy and feedback multiply, a zero on either makes MPS zero.","difficulty":"very-hard","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-137","question":"Assertion (A): An unstructured interview may have low validity even when the interviewer is experienced.\nReason (R): Unstructured interviews are inconsistent across candidates and prone to biases such as first impressions and similar-to-me effects.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":0,"explanation":"Experience does not remove the inconsistency and bias built into unstructured interviews, and those flaws are what lower validity. R explains A.","difficulty":"very-hard","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-138","question":"Consider these statements about appraisal methods:\nI. Forced distribution counters leniency and central tendency errors.\nII. BARS is quick and cheap to develop.\nIII. 360-degree feedback gives a broader view, but raters often need anonymity to be candid.\nWhich are correct?","options":["I only","I, II and III","II and III only","I and III only"],"answer":3,"explanation":"I and III are correct. BARS is time-consuming and costly to develop because behavioural anchors must be collected and validated for each job, so II is false.","difficulty":"very-hard","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-139","question":"Match each rating error with an example.\nA. Halo  B. Leniency  C. Central tendency  D. Similar-to-me\n1. Rating everyone 'average' to avoid difficult conversations\n2. Rating a candidate highly because he went to the same college as the rater\n3. Rating all team members 'excellent'\n4. Rating someone high on all criteria because she is very punctual","options":["A-4, B-1, C-3, D-2","A-3, B-4, C-1, D-2","A-4, B-3, C-1, D-2","A-2, B-3, C-1, D-4"],"answer":2,"explanation":"Halo = one trait colours all ratings; leniency = everyone rated high; central tendency = everyone rated in the middle; similar-to-me = favouring people like oneself.","difficulty":"very-hard","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-140","question":"A data-entry firm tests candidates by having them enter a sample of real forms within a time limit. Because the test samples the actual tasks of the job, it has high:","options":["Content validity","Predictive validity only","Test–retest reliability","Construct validity"],"answer":0,"explanation":"Content validity is the degree to which a test samples the knowledge and tasks actually required by the job. Work-sample tests are the classic example.","difficulty":"very-hard","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-141","question":"A call-centre firm with high first-month attrition starts showing candidates honest videos of difficult customer calls, night shifts and strict monitoring before they accept offers. What is this practice and its main purpose?","options":["Psychometric testing — to measure personality","An assessment centre — to test skills","Employer branding — to attract more applicants","A realistic job preview — to reduce early turnover by aligning expectations"],"answer":3,"explanation":"Realistic job previews present both positives and negatives, so candidates who would be unhappy self-select out and those who join have realistic expectations.","difficulty":"very-hard","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-142","question":"An HR team compares an individual employee's current skills with the skills her role requires, to decide whether she needs training. This stage of training needs analysis is:","options":["Person analysis","Task analysis","Organisational analysis","Cost–benefit analysis"],"answer":0,"explanation":"Needs analysis has three levels: organisational (where training is needed), task (what the job requires) and person (who needs training and in what).","difficulty":"hard","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-143","question":"On a new hire's first week, the company introduces her to colleagues, explains policies and culture and shows her how her role fits the business. This process is called:","options":["Placement","Job rotation","Induction (onboarding)","Socialisation into retirement"],"answer":2,"explanation":"Induction or onboarding helps new employees settle in, understand the organisation and become productive faster, reducing early turnover.","difficulty":"moderate","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-144","question":"A company with an average headcount of 300 had 30 employees leave during the year. What is its annual attrition rate?","options":["3%","10%","9.1%","30%"],"answer":1,"explanation":"Attrition rate = separations / average headcount × 100 = 30 / 300 × 100 = 10%.","difficulty":"easy","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-145","question":"A firm spent ₹12 lakh in total on recruitment last year and made 40 hires. What was its cost per hire?","options":["₹3,000","₹30,000","₹48,000","₹3,00,000"],"answer":1,"explanation":"Cost per hire = total recruiting cost / number of hires = 12,00,000 / 40 = ₹30,000.","difficulty":"easy","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-146","question":"Which of these is a form of variable pay?","options":["Basic salary","House rent allowance","Fixed monthly conveyance allowance","Sales commission"],"answer":3,"explanation":"Variable pay changes with performance or results — commissions, bonuses, incentives. Basic pay and fixed allowances do not vary with output.","difficulty":"easy","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-147","question":"A firm started the year with 480 employees and ended with 520. During the year 60 employees left. Using average headcount, what is the attrition rate?","options":["11.5%","12.5%","12%","10%"],"answer":2,"explanation":"Average headcount = (480 + 520) / 2 = 500. Attrition = 60 / 500 = 12%. Dividing by the opening figure gives 12.5%; by the closing figure, 11.5%.","difficulty":"moderate","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-148","question":"A unit has 200 employees and 25 working days in a month. In that month 400 person-days were lost to unplanned absence. What is the absenteeism rate?","options":["2%","8%","16%","4%"],"answer":1,"explanation":"Absenteeism = person-days lost / (employees × working days) × 100 = 400 / (200 × 25) × 100 = 8%.","difficulty":"moderate","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-149","question":"An employee earns ₹54,000 a month. The midpoint of her pay range is ₹60,000. What is her compa-ratio?","options":["0.54","1.11","0.90","1.00"],"answer":2,"explanation":"Compa-ratio = actual pay / range midpoint = 54,000 / 60,000 = 0.90. Below 1.0 means she is paid below the midpoint of her grade.","difficulty":"moderate","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-150","question":"To decide pay grades, a company scores each job on factors such as skill, effort, responsibility and working conditions, and adds up the points. Which job-evaluation method is this?","options":["Ranking method","Job classification","Market pricing","Point (factor) method"],"answer":3,"explanation":"The point method assigns points to compensable factors and totals them, giving a quantitative measure of each job's relative worth.","difficulty":"moderate","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-151","question":"An HR team buys salary-survey data to check whether its pay for data analysts matches what other employers in the city pay. Which pay goal does this address?","options":["External competitiveness","Internal equity","Individual equity","Procedural justice"],"answer":0,"explanation":"External competitiveness compares pay with the market. Internal equity is about fair pay relationships between jobs within the firm.","difficulty":"moderate","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-152","question":"A firm records 15 separations in one quarter against an average headcount of 250. If this rate continued, what would the annualised attrition rate be (simple, not compounded)?","options":["6%","24%","15%","12%"],"answer":1,"explanation":"Quarterly attrition = 15 / 250 = 6%. Annualised = 6% × 4 = 24%.","difficulty":"hard","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-153","question":"In a year a firm spends ₹6 lakh on agency fees and ₹2 lakh on job ads (external costs), plus ₹4 lakh of recruiter salaries, ₹1 lakh of referral bonuses and ₹1 lakh of managers' interview time (internal costs). It makes 35 hires. What is its cost per hire?","options":["₹22,857","₹34,286","₹28,571","₹40,000"],"answer":3,"explanation":"Total cost = 8 + 6 = ₹14 lakh. Cost per hire = 14,00,000 / 35 = ₹40,000. Counting only external costs gives ₹22,857, understating the true cost.","difficulty":"hard","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-154","question":"A firm with an average headcount of 400 had 40 separations: 28 resignations, 8 terminations and 4 retirements. What is its voluntary attrition rate?","options":["10%","9%","7%","8%"],"answer":2,"explanation":"Voluntary attrition counts only employee-initiated exits: 28 / 400 = 7%. Total attrition is 10%; terminations and retirements are usually tracked separately.","difficulty":"hard","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-155","question":"The Bradford factor scores absence as S² × D, where S is the number of separate spells and D the total days absent. Employee A had six one-day absences; Employee B had a single six-day absence. What are their scores?","options":["A = 216, B = 6","A = 36, B = 36","A = 6, B = 216","A = 72, B = 12"],"answer":0,"explanation":"A: 6² × 6 = 216. B: 1² × 6 = 6. Both missed six days, but the Bradford factor flags frequent short absences as more disruptive.","difficulty":"very-hard","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-156","question":"A company hired 80 people last year; 20 of them left within twelve months of joining. What is its first-year (new-hire) retention rate?","options":["25%","75%","80%","20%"],"answer":1,"explanation":"New-hire retention = hires still employed after a year / total hires = 60 / 80 = 75%. The first-year attrition rate is 25%.","difficulty":"hard","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-157","question":"A company earns ₹240 crore in revenue with 1,600 employees. What is its revenue per employee?","options":["₹15 lakh","₹1.5 lakh","₹150 lakh","₹6.7 lakh"],"answer":0,"explanation":"240 crore / 1,600 = ₹15 lakh per employee. Revenue per employee is a broad productivity measure, best compared across firms in the same industry.","difficulty":"hard","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-158","question":"A recruiting team made 45 offers last quarter and 36 were accepted. What is the offer-acceptance rate?","options":["36%","125%","20%","80%"],"answer":3,"explanation":"Offer-acceptance rate = offers accepted / offers made = 36 / 45 = 80%. A low rate can signal uncompetitive pay or a poor candidate experience.","difficulty":"moderate","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-159","question":"A firm loses 60 employees a year. Replacing each one costs about 50% of the average annual salary of ₹8 lakh. If a retention programme cuts attrition by one-third, roughly how much does it save each year?","options":["₹1.6 crore","₹2.4 crore","₹0.8 crore","₹4.8 crore"],"answer":2,"explanation":"Annual replacement cost = 60 × 0.5 × 8 lakh = ₹2.4 crore. Cutting attrition by a third saves 20 × ₹4 lakh = ₹0.8 crore, before counting the programme's own cost.","difficulty":"very-hard","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-160","question":"Two employees received the same top performance rating. One has a compa-ratio of 0.85 and the other 1.15. Under a typical merit matrix, how should their percentage increases compare?","options":["Both get the same percentage","The employee at 0.85 gets a larger percentage increase","The employee at 1.15 gets a larger percentage increase","Neither gets an increase because ratings are equal"],"answer":1,"explanation":"Merit matrices give larger increases to strong performers who are low in their range, moving them towards the midpoint, and smaller increases to those already high in the range.","difficulty":"very-hard","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-161","question":"A firm has raised starting salaries sharply to attract new graduates, and now some new hires earn almost as much as staff with five years' experience. This problem is called:","options":["Red-circling","Broadbanding","Pay compression","Pay secrecy"],"answer":2,"explanation":"Pay compression occurs when the pay gap between new and experienced employees narrows, which can demotivate long-serving staff.","difficulty":"hard","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-162","question":"A company replaces its 18 narrow pay grades with five wide pay bands, giving managers more flexibility to reward growth without promotions. This is:","options":["Job enlargement","Pay compression","Red-circling","Broadbanding"],"answer":3,"explanation":"Broadbanding collapses many grades into a few wide bands, supporting flatter structures and lateral career moves.","difficulty":"hard","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-163","question":"An offer has a basic salary of ₹40,000 a month, HRA at 40% of basic, employer PF contribution at 12% of basic, a special allowance of ₹10,000 a month and an annual bonus of ₹60,000. What is the annual cost to company (CTC)?","options":["₹9,09,600","₹8,49,600","₹8,52,000","₹9,60,000"],"answer":0,"explanation":"Monthly = 40,000 + 16,000 + 4,800 + 10,000 = ₹70,800; × 12 = ₹8,49,600; + ₹60,000 bonus = ₹9,09,600. Leaving out the bonus gives ₹8,49,600.","difficulty":"very-hard","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-164","question":"Under the standard formula of 15 days' wages for every completed year of service, with a month treated as 26 working days, what gratuity is due to an employee with 10 years of service whose last drawn basic plus DA is ₹52,000 a month?","options":["₹2,60,000","₹3,00,000","₹2,51,613","₹5,20,000"],"answer":1,"explanation":"Gratuity = last drawn (basic + DA) × 15 / 26 × years = 52,000 × 15 / 26 × 10 = ₹3,00,000. Using 30 days a month gives ₹2,60,000.","difficulty":"very-hard","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-165","question":"A plant has 500 employees, 250 working days a year and an absenteeism rate of 4%. If each day of absence costs ₹2,000 in lost output and cover, what is the annual cost of absenteeism?","options":["₹10 lakh","₹25 lakh","₹40 lakh","₹1 crore"],"answer":3,"explanation":"Days lost = 500 × 250 × 0.04 = 5,000. Cost = 5,000 × ₹2,000 = ₹1 crore.","difficulty":"very-hard","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-166","question":"Assertion (A): For a fast-growing company, calculating attrition on the opening headcount tends to overstate the attrition rate compared with using average headcount.\nReason (R): Average headcount better reflects the number of employees who were exposed to the risk of leaving during the period.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":0,"explanation":"In a growing firm the opening headcount is smaller than the average, so the same separations divided by a smaller base give a higher rate. Average headcount captures everyone who could have left, which is why it is preferred.","difficulty":"very-hard","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-167","question":"Consider these statements about recruitment metrics:\nI. Cost per hire should include internal costs such as recruiter salaries.\nII. A falling time-to-fill always means better hiring quality.\nIII. Quality of hire can be judged from new hires' performance and retention.\nWhich are correct?","options":["II and III only","I, II and III","I and III only","I only"],"answer":2,"explanation":"I and III are correct. Faster hiring can come at the cost of poorer selection, so II is false.","difficulty":"very-hard","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-168","question":"Under a plant-wide scheme, employees receive a share of the savings whenever labour costs per unit fall below a historical baseline. This type of plan is called:","options":["Gainsharing (e.g. Scanlon-type plan)","Piece-rate pay","Seniority pay","Stock options"],"answer":0,"explanation":"Gainsharing plans share productivity or cost-saving gains with groups of employees, encouraging teamwork and suggestions.","difficulty":"hard","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-169","question":"A start-up grants employees stock options that vest over four years. What is the main HR objective of this?","options":["To reduce statutory deductions","To meet minimum-wage requirements","To replace basic salary entirely","To align employees' interests with long-term company value and encourage retention"],"answer":3,"explanation":"Vesting over several years rewards staying, and ownership links employees' rewards to company performance.","difficulty":"hard","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-170","question":"A company lets each employee choose from a menu of benefits — extra health cover, meal cards, childcare support or additional leave — within a fixed budget. This is a:","options":["Defined-benefit pension plan","Cafeteria (flexible) benefits plan","Gainsharing plan","Piece-rate plan"],"answer":1,"explanation":"Cafeteria plans let employees tailor benefits to their own needs, increasing the value they perceive for the same cost.","difficulty":"moderate","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-171","question":"A warehouse needs 180 workers present every day. Average absenteeism is 10%. How many workers should be on the rolls?","options":["198","190","200","180"],"answer":2,"explanation":"On-roll staff × 0.90 = 180, so on-roll staff = 180 / 0.9 = 200. Adding 10% to 180 (198) undershoots because the 10% applies to the larger on-roll number.","difficulty":"hard","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-172","question":"India consolidated many central labour laws into four labour codes. Which of these is NOT one of them?","options":["Code on Wages","Industrial Relations Code","Code on Social Security","Code on Employee Stock Ownership"],"answer":3,"explanation":"The four codes are the Code on Wages, the Industrial Relations Code, the Code on Social Security, and the Occupational Safety, Health and Working Conditions Code.","difficulty":"easy","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-173","question":"Under India's law on prevention of sexual harassment at the workplace (POSH), an employer with 10 or more employees must set up a body to hear complaints. What is it called?","options":["Works Committee","Internal Committee","Grievance Redressal Board","Labour Court"],"answer":1,"explanation":"The POSH Act requires an Internal Committee (earlier called the Internal Complaints Committee) at every workplace with 10 or more employees.","difficulty":"easy","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-174","question":"A factory pays women packers less than men doing the same packing work, citing 'tradition'. Which principle in India's wage law does this violate?","options":["Payment of bonus","Equal remuneration for the same work or work of a similar nature, regardless of gender","Minimum notice before a strike","Standing orders"],"answer":1,"explanation":"The Code on Wages prohibits discrimination on the basis of gender in wages for the same work or work of a similar nature.","difficulty":"moderate","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-175","question":"Union representatives and management meet over several weeks to negotiate wages, working hours and leave for all workers, and then sign a settlement. This process is called:","options":["Collective bargaining","Grievance handling","Domestic enquiry","Job evaluation"],"answer":0,"explanation":"Collective bargaining is negotiation between employers and workers' representatives to agree terms and conditions of employment.","difficulty":"moderate","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-176","question":"A purchase manager learns that a vendor bidding for a large contract is owned by her brother. What is the most appropriate ethical action?","options":["Evaluate the bid herself but be extra strict","Tell her brother the competitors' prices so the process is fair","Quietly reject the vendor without explanation","Disclose the relationship and step away from the decision"],"answer":3,"explanation":"A conflict of interest should be disclosed and the person should recuse from the decision. Rejecting silently or acting on it secretly both fail transparency.","difficulty":"moderate","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-177","question":"An employee wants to report that a senior manager is falsifying expense claims, but fears retaliation. Which policy is meant to protect her?","options":["Dress code","Leave policy","Whistle-blower (vigil mechanism) policy","Travel policy"],"answer":2,"explanation":"A whistle-blower or vigil mechanism gives employees a confidential channel to report wrongdoing and protects them from retaliation.","difficulty":"hard","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-178","question":"An employee's total monthly remuneration is ₹1,00,000, of which basic pay plus DA is ₹30,000 and allowances excluded from 'wages' make up ₹70,000. Under the Code on Wages rule that excluded components above 50% of total remuneration are added back, what is the 'wage' for statutory purposes?","options":["₹30,000","₹50,000","₹70,000","₹35,000"],"answer":1,"explanation":"Excluded components may be at most 50% (₹50,000). The excess of ₹20,000 is added back: 30,000 + 20,000 = ₹50,000. This tends to raise the base for PF and gratuity.","difficulty":"very-hard","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-179","question":"Consider these statements about fixed-term employment under India's new labour codes:\nI. Fixed-term employees are entitled to the same wages and benefits as permanent employees doing the same or similar work.\nII. Fixed-term employees can become eligible for gratuity on a pro-rata basis without completing five years.\nIII. Fixed-term employees are excluded from all statutory benefits.\nWhich are correct?","options":["II and III only","I, II and III","I and II only","I only"],"answer":2,"explanation":"I and II are correct. The codes give fixed-term employees parity with permanent staff doing similar work and pro-rata gratuity without the five-year condition, so III is false.","difficulty":"very-hard","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-180","question":"What change did the Industrial Relations Code make to the rules on strikes?","options":["It banned strikes in all private establishments","It required notice only in establishments with more than 300 workers","It removed the need for any notice before a strike","It extended the requirement of advance notice before a strike to all industrial establishments, not just public utility services"],"answer":3,"explanation":"Earlier, strike notice was mainly required in public utility services. The IR Code applies the advance-notice requirement to all industrial establishments.","difficulty":"very-hard","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-181","question":"Under the Industrial Relations Code, prior government permission for lay-off, retrenchment or closure is required in industrial establishments employing at least how many workers?","options":["50","100","300","1,000"],"answer":2,"explanation":"The IR Code raised the threshold for prior permission from 100 workers (under the earlier law) to 300 workers, with a provision allowing governments to change it.","difficulty":"hard","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-182","question":"Which new category of workers was explicitly brought under the social-security framework by India's Code on Social Security?","options":["Gig and platform workers","Civil servants","Armed forces personnel","Company directors"],"answer":0,"explanation":"The Code on Social Security recognises gig workers and platform workers and provides for social-security schemes for them, partly funded by aggregator contributions.","difficulty":"hard","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-183","question":"Faced with a choice between closing a loss-making unit (300 jobs lost, company saved) and keeping it open (whole company at risk), a manager chooses the option that produces the greatest overall good for the most people. Which ethical approach is she using?","options":["Virtue approach","Rights approach","Justice approach","Utilitarian approach"],"answer":3,"explanation":"The utilitarian approach judges actions by their consequences — the greatest net benefit for the greatest number.","difficulty":"hard","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-184","question":"During a tender, a bidding vendor sends an expensive watch to the evaluation manager's home. Under a typical gifts policy, what should the manager do?","options":["Decline or return it and report it as the policy requires","Keep it, since it was sent to his home","Keep it but give the vendor a lower score to compensate","Share it with the team"],"answer":0,"explanation":"Gifts of significant value from parties seeking business create a conflict of interest, especially during a tender. They should be declined or returned and declared.","difficulty":"hard","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-185","question":"A supervisor hints to a junior employee that her promotion depends on accepting his personal advances. Which form of sexual harassment is this?","options":["Hostile work environment harassment","Third-party harassment","Quid pro quo harassment","Constructive dismissal"],"answer":2,"explanation":"Quid pro quo ('this for that') harassment makes job benefits conditional on sexual favours. Hostile-environment harassment is unwelcome conduct that creates an intimidating workplace.","difficulty":"hard","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-186","question":"Bonuses this year are lower than expected, but employees accept them without much complaint because the criteria were announced in advance, applied consistently and staff could question the results. Which form of organisational justice explains this?","options":["Distributive justice","Procedural justice","Interactional justice","Retributive justice"],"answer":1,"explanation":"Procedural justice is the perceived fairness of the process used to decide outcomes. Fair processes make unfavourable outcomes easier to accept.","difficulty":"hard","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-187","question":"An analyst regularly stays back to help new joiners learn the systems and volunteers to organise team events, though neither is part of her job or rewarded formally. This is an example of:","options":["Presenteeism","Social loafing","Role conflict","Organisational citizenship behaviour"],"answer":3,"explanation":"Organisational citizenship behaviour is discretionary behaviour beyond formal role requirements that helps the organisation function.","difficulty":"hard","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-188","question":"A firm has 100 junior and 40 senior analysts. Each year 70% of juniors stay junior, 10% are promoted to senior and 20% leave; 85% of seniors stay and 15% leave. Before any external hiring, how many senior analysts will there be next year?","options":["34","44","40","50"],"answer":1,"explanation":"Seniors next year = 40 × 0.85 + 100 × 0.10 = 34 + 10 = 44. This transition-matrix method is Markov analysis, used in HR supply forecasting.","difficulty":"very-hard","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-189","question":"A company has 500 employees and expects to need 520 next year. Annual attrition is expected to be 12%. How many people must it hire during the year?","options":["20","60","80","82"],"answer":2,"explanation":"Staff remaining = 500 × 0.88 = 440. Hires needed = 520 − 440 = 80. Planning only for growth (20) ignores replacement demand.","difficulty":"very-hard","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-190","question":"A high performer was told at joining that she would lead a team within two years. Three years later there is no sign of it, and her commitment and discretionary effort have dropped sharply. What best explains this?","options":["A breach of the psychological contract","Social loafing","The halo effect","Job enlargement"],"answer":0,"explanation":"The psychological contract is the unwritten set of mutual expectations between employer and employee. When the employee sees it as broken, trust, commitment and effort fall.","difficulty":"very-hard","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-191","question":"Assertion (A): Bringing many central labour laws together into four codes was meant to reduce compliance complexity for employers.\nReason (R): The older laws were numerous and overlapping, with different definitions of terms such as 'wages' and 'employee'.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":0,"explanation":"Simplification and uniform definitions were central aims of the codes, because the many overlapping laws with inconsistent definitions made compliance difficult. R explains A.","difficulty":"very-hard","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-192","question":"Consider these statements about the Internal Committee under India's POSH law:\nI. It is to be headed by a senior woman employee.\nII. It includes an external member from an NGO or someone familiar with issues of sexual harassment.\nIII. It can hear complaints only from permanent employees.\nWhich are correct?","options":["I, II and III","I and II only","II and III only","I only"],"answer":1,"explanation":"I and II are correct. The law protects any woman at the workplace — including contract staff, trainees, interns and visitors — so III is false.","difficulty":"very-hard","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-193","question":"Match each ethical approach with its core question.\nA. Utilitarian  B. Rights  C. Justice  D. Virtue\n1. Are benefits and burdens distributed fairly?\n2. Does the action respect people's entitlements, such as privacy and free consent?\n3. Which action produces the greatest net good?\n4. What would a person of good character do?","options":["A-3, B-2, C-1, D-4","A-2, B-3, C-1, D-4","A-3, B-1, C-2, D-4","A-3, B-2, C-4, D-1"],"answer":0,"explanation":"Utilitarian = consequences; rights = entitlements; justice = fair distribution; virtue = character.","difficulty":"very-hard","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-194","question":"A manager announcing layoffs meets each affected employee privately, explains the reasons honestly and treats them with dignity and respect. Which dimension of organisational justice is she addressing most directly?","options":["Distributive justice","Procedural justice","Restorative justice","Interactional justice"],"answer":3,"explanation":"Interactional justice is about the quality of interpersonal treatment — respect, dignity and honest explanations — when decisions are communicated.","difficulty":"very-hard","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-195","question":"McGregor's 'hot-stove rule' says discipline should be immediate, give advance warning, be consistent and be impersonal. A supervisor ignores lateness by his favourites but punishes others for it. Which element is he violating most clearly?","options":["Immediacy","Advance warning","Consistency and impersonality","Proportionality to output"],"answer":2,"explanation":"Like a hot stove that burns everyone who touches it, discipline should apply the same way to everyone. Favouritism breaks both consistency and impersonality.","difficulty":"very-hard","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-196","question":"In a progressive discipline system, which sequence is usually followed for a repeated, non-serious offence?","options":["Termination → suspension → written warning → oral warning","Oral warning → written warning → suspension → termination","Written warning → oral warning → termination → suspension","Suspension → oral warning → written warning → termination"],"answer":1,"explanation":"Progressive discipline increases penalties step by step, giving the employee chances to correct behaviour before dismissal. Serious misconduct may skip steps.","difficulty":"hard","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-197","question":"A company plans to employ 600 workers next year and keeps a ratio of one supervisor to every 12 workers. It has 40 supervisors and expects none to leave. How many more supervisors does it need?","options":["12","50","10","8"],"answer":2,"explanation":"Required supervisors = 600 / 12 = 50. Additional needed = 50 − 40 = 10. This is the ratio-trend method of HR demand forecasting.","difficulty":"hard","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-198","question":"In a domestic enquiry into alleged misconduct, the manager who filed the complaint is also appointed as the enquiry officer. Which principle of natural justice is violated?","options":["The right to be heard","The right to appeal","Punishment must be proportionate","No one should be a judge in their own cause"],"answer":3,"explanation":"Natural justice requires an unbiased decision-maker (nemo judex in causa sua) and a fair hearing. A complainant judging his own complaint fails the first principle.","difficulty":"very-hard","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-199","question":"Assertion (A): A well-written code of ethics, on its own, may not prevent misconduct in an organisation.\nReason (R): Employee behaviour is shaped heavily by incentives, leaders' example and consistent enforcement, not only by written rules.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":0,"explanation":"Codes work only when leaders model them, incentives do not reward violations and breaches are enforced. R explains why a code alone is not enough.","difficulty":"very-hard","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-200","question":"What is the main purpose of an exit interview?","options":["To understand why employees leave and identify patterns the organisation can fix","To persuade the employee to withdraw the resignation at any cost","To recover company property only","To calculate the employee's final settlement"],"answer":0,"explanation":"Exit interviews gather honest feedback on reasons for leaving — manager, pay, growth, culture — so HR can spot and fix retention problems.","difficulty":"moderate","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-201","question":"Before salary talks with her preferred employer, a candidate secures a written offer of ₹18 lakh from another firm. In negotiation terms, this other offer is her:","options":["BATNA","ZOPA","Opening anchor","Concession"],"answer":0,"explanation":"BATNA is the best alternative to a negotiated agreement — what she gets if the current talks fail. It sets her walk-away point and gives her bargaining strength.","difficulty":"easy","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-202","question":"A team leader can recommend which team members receive the annual bonus, and her team works hard partly for that reason. Which base of power is she mainly using?","options":["Coercive power","Reward power","Referent power","Expert power"],"answer":1,"explanation":"Reward power comes from controlling things others value, such as bonuses, promotions or good assignments. Coercive power rests on punishment; referent power on being liked or admired.","difficulty":"easy","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-203","question":"A unit has 96 machine operators and the company's norm is one supervisor for every 12 operators. How many supervisors does it need?","options":["12","9","8","6"],"answer":2,"explanation":"Supervisors = operators / span = 96 / 12 = 8.","difficulty":"easy","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-204","question":"A candidate will not accept less than ₹14 lakh. The employer is authorised to pay up to ₹16.5 lakh but has not revealed this. What is the zone of possible agreement (ZOPA)?","options":["₹16.5 lakh to ₹18 lakh","There is no ZOPA","Anything below ₹14 lakh","₹14 lakh to ₹16.5 lakh"],"answer":3,"explanation":"The ZOPA lies between the two reservation points — the seller's minimum (₹14 lakh) and the buyer's maximum (₹16.5 lakh). Any deal inside it beats both sides' walk-away positions; where it lands depends on bargaining.","difficulty":"moderate","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-205","question":"In the iceberg model of competencies, which elements lie below the surface and are the hardest to develop through training?","options":["Motives, traits and self-concept","Knowledge and skills","Educational qualifications","Job titles and grades"],"answer":0,"explanation":"Knowledge and skills are visible and fairly easy to train. Deeper characteristics — motives, traits and self-image — are hidden and hard to change, so firms often select for them instead of training them.","difficulty":"moderate","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-206","question":"A manager with only two direct reports is included in a 360° feedback programme with a separate 'direct reports' section in her report. What is the main problem with that section?","options":["Direct reports never observe their manager's behaviour","The raters cannot stay anonymous, so their ratings may be softened","360° feedback should exclude subordinates entirely","Two raters make the self-rating invalid"],"answer":1,"explanation":"With so few raters she can easily guess who said what, so subordinates tend to inflate scores to protect themselves. Programmes usually require a minimum number of raters before showing a group separately.","difficulty":"moderate","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-207","question":"An engagement survey reports that 78% of respondents are engaged, but only 30% of employees responded. What is the main caution in reading this result?","options":["The score is certainly too low","Response rates have no effect on interpretation","Non-response bias — the 70% who did not respond may feel very differently","The result proves engagement is above the industry average"],"answer":2,"explanation":"With a low response rate, those who answer may not represent the workforce; disengaged staff are often less likely to respond. The 78% may therefore overstate engagement.","difficulty":"moderate","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-208","question":"After news of a large fraud at another company's branch, a bank manager sharply overestimates the chance of fraud in his own branch, although nothing in his data has changed. Which bias is this?","options":["Anchoring","Confirmation bias","Escalation of commitment","Availability heuristic"],"answer":3,"explanation":"The availability heuristic judges how likely something is by how easily examples come to mind. Vivid, recent news makes an event seem more common than it is.","difficulty":"moderate","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-209","question":"A sales rep's annual target is ₹40 lakh. She earns 1% commission on sales up to target and 2% on sales above target. She sells ₹50 lakh. What is her commission?","options":["₹60,000","₹1,00,000","₹50,000","₹80,000"],"answer":0,"explanation":"1% × ₹40 lakh = ₹40,000, plus 2% × ₹10 lakh = ₹20,000, giving ₹60,000. The higher rate above target is an accelerator meant to reward over-achievement.","difficulty":"moderate","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-210","question":"A pay grade has a midpoint of ₹50,000 a month and a range spread of 50%, measured as (maximum − minimum) / minimum. What are its minimum and maximum?","options":["₹37,500 and ₹62,500","₹40,000 and ₹60,000","₹45,000 and ₹55,000","₹25,000 and ₹75,000"],"answer":1,"explanation":"Midpoint = (min + max) / 2 and max = 1.5 × min, so midpoint = 1.25 × min. Min = 50,000 / 1.25 = ₹40,000 and max = ₹60,000. Check: (60,000 − 40,000) / 40,000 = 50%.","difficulty":"hard","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-211","question":"A company has 10,000 front-line operators. With a uniform span of control of 10 at every level, it needs 1,111 managers in four layers. If the span is widened to 100 at every level, how many managerial positions disappear?","options":["1,000","1,110","1,010","990"],"answer":2,"explanation":"At span 100: 10,000 / 100 = 100 managers, plus 1 above them = 101 managers in two layers. Reduction = 1,111 − 101 = 1,010 positions.","difficulty":"hard","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-212","question":"A firm has 200 Level-1 and 50 Level-2 staff. Each year, 75% of Level-1 staff stay, 15% are promoted to Level 2 and 10% leave; 85% of Level-2 staff stay and 15% leave. Using these transition rates, how many Level-2 staff will there be next year before any external hiring into Level 2?","options":["80","42.5","62.5","72.5"],"answer":3,"explanation":"Level 2 next year = stayers 0.85 × 50 = 42.5, plus promotions 0.15 × 200 = 30, giving 72.5. 42.5 forgets the promotion inflow.","difficulty":"hard","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-213","question":"Under a forced distribution, 20% of employees are rated 'top' and get a 12% raise, 70% are 'middle' and get 7%, and 10% are 'bottom' and get nothing. What average raise must the merit budget fund, assuming similar salaries across categories?","options":["7.3%","6.3%","7%","19%"],"answer":0,"explanation":"Weighted average = 0.20 × 12 + 0.70 × 7 + 0.10 × 0 = 2.4 + 4.9 = 7.3%. With very different salary levels, the weights would have to be payroll shares, not headcount shares.","difficulty":"hard","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-214","question":"Consider these statements about assessment centres:\nI. Using several exercises and several assessors reduces the bias of any single rater.\nII. Each competency is usually observed in more than one exercise.\nIII. They mainly measure intelligence through written tests.\nIV. Assessors need training and should rate against behavioural anchors.\nWhich are correct?","options":["I and III only","I, II and IV only","II, III and IV only","I, II, III and IV"],"answer":1,"explanation":"Assessment centres rely on simulations — in-baskets, group exercises, role-plays — observed by trained assessors against behavioural anchors, with each competency seen several times. They are not mainly written intelligence tests.","difficulty":"hard","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-215","question":"Two department heads fight over a shared ₹20 lakh budget. Talking it through, they find that one needs the money for training in the first quarter and the other for equipment in the last quarter. Which approach creates the most value?","options":["Distributive bargaining — split the budget 50:50","Avoidance — postpone the decision to next year","Integrative bargaining — sequence the spending to meet both needs","Escalate so the CEO picks one department"],"answer":2,"explanation":"Integrative negotiation looks for interests behind positions and trades on differences — here, timing — so both sides gain. Splitting the money treats it as a fixed pie and leaves both short.","difficulty":"hard","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-216","question":"An HR plan approves 60 new hires at an average annual cost of ₹12 lakh each, with joining dates spread evenly through the year. Roughly what salary cost should this year's budget carry for these hires?","options":["₹7.2 crore","₹1.8 crore","₹6 crore","₹3.6 crore"],"answer":3,"explanation":"If hires join evenly, each is on the payroll for about half the year on average. Cost ≈ 60 × ₹12 lakh × 0.5 = ₹360 lakh = ₹3.6 crore. ₹7.2 crore is the full-year run rate that carries into next year.","difficulty":"hard","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-217","question":"A mid-level analyst is the only person who understands the company's old billing system, and senior managers regularly accept her views on systems changes. What best explains her influence?","options":["Her expertise is scarce and hard to replace, so others depend on her","Legitimate power from her formal position","Coercive power over senior managers","Referent power from personal charisma"],"answer":0,"explanation":"Power comes from others' dependence on you, which grows when what you control is important, scarce and non-substitutable. Her know-how gives her expert power well above her formal rank.","difficulty":"hard","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-218","question":"A rep's annual target is ₹60 lakh. No incentive is paid below 80% of target. Between 80% and 100% of target she earns 1.5% on sales above the 80% threshold; above target she earns 3% on the excess. Total incentive is capped at ₹1.2 lakh. She sells ₹75 lakh. What is her incentive?","options":["₹1,12,500","₹63,000","₹54,000","₹1,20,000"],"answer":1,"explanation":"Threshold = ₹48 lakh. Band 1: 1.5% × (60 − 48) lakh = ₹18,000. Band 2: 3% × (75 − 60) lakh = ₹45,000. Total ₹63,000, which is below the cap. ₹1,12,500 wrongly applies 1.5% to all sales.","difficulty":"very-hard","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-219","question":"Each year a junior analyst has a 70% chance of staying junior, a 10% chance of being promoted and a 20% chance of leaving. If these probabilities stay constant, what is the probability that a current junior is eventually promoted rather than leaving?","options":["10%","30%","33.3%","25%"],"answer":2,"explanation":"Each year the junior either stays (and the process repeats) or exits by promotion or departure. So the eventual outcome splits in the ratio 10 : 20, and P(promoted) = 0.10 / 0.30 = 1/3.","difficulty":"very-hard","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-220","question":"A supplier's cost is ₹80 a unit and another buyer will pay it ₹95. The buyer has an alternative quote of ₹110 a unit, but switching to that supplier would add ₹5 a unit in requalification costs. What is the zone of possible agreement (per unit)?","options":["₹80 to ₹110","₹95 to ₹110","₹80 to ₹115","₹95 to ₹115"],"answer":3,"explanation":"The supplier will not go below its BATNA of ₹95 — its cost of ₹80 is not the walk-away point. The buyer's alternative really costs ₹110 + ₹5 = ₹115, so it will pay up to ₹115 rather than switch. The ZOPA is ₹95–₹115.","difficulty":"very-hard","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-221","question":"An engagement survey shows Team A at 80% favourable with 10 respondents and Team B at 65% favourable with 200 respondents; the company benchmark is 70%.\nI. Team A's score is less reliable because of its small sample.\nII. Team B is 5 points below the benchmark.\nIII. The gap proves that Team A's manager causes higher engagement.\nIV. Results should be shown only for groups above a minimum size, to protect anonymity.\nWhich are correct?","options":["I, II and IV only","I, II and III only","II and IV only","I, II, III and IV"],"answer":0,"explanation":"With 10 people, one or two answers move the score a lot (I). 65 vs 70 is a 5-point gap (II). A survey gap shows association, not cause — team size, work type and other factors differ (III is false). Minimum reporting sizes protect anonymity (IV).","difficulty":"very-hard","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-222","question":"Assertion (A): In 360° feedback used for development, peer ratings are usually collected anonymously.\nReason (R): Anonymity is unnecessary because peers have no reason to inflate or deflate their ratings.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":2,"explanation":"A is true. R is false: peers may soften ratings to protect relationships or harden them out of rivalry, which is exactly why anonymity is used to get honest feedback.","difficulty":"very-hard","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-223","question":"Match each decision bias with an example.\nA. Confirmation bias  B. Framing effect  C. Hindsight bias  D. Overconfidence\n1. Backing a restructuring plan described as 'saves 200 of 600 jobs' but rejecting the same plan described as '400 of 600 jobs lost'\n2. After a failed launch, a director says 'I always knew it would flop'\n3. A recruiter looks only for evidence that supports her favourite candidate\n4. A manager's '90% certain' project-completion ranges turn out right only half the time","options":["A-1, B-3, C-2, D-4","A-3, B-1, C-2, D-4","A-3, B-1, C-4, D-2","A-3, B-2, C-1, D-4"],"answer":1,"explanation":"Seeking supporting evidence is confirmation bias; reacting differently to equivalent descriptions is framing; 'I knew it all along' is hindsight bias; ranges that are too narrow show overconfidence.","difficulty":"very-hard","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-224","question":"A plant's gainsharing plan sets a baseline labour cost of 25% of the value of production and shares 50% of any savings equally among its 200 employees. This month production is worth ₹80 lakh and actual labour cost is ₹18 lakh. How much does each employee receive?","options":["₹1,000","₹750","₹250","₹500"],"answer":3,"explanation":"Allowed labour cost = 25% × ₹80 lakh = ₹20 lakh. Savings = ₹2 lakh; the employees' half = ₹1 lakh; shared among 200 = ₹500 each. ₹1,000 forgets that only half the savings are shared.","difficulty":"very-hard","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-225","question":"An HR team lists the key behaviours, skills and attributes needed for each role in its sales function and then assesses every salesperson against them to find gaps. This exercise is called:","options":["Competency mapping","Job evaluation","Job enrichment","Exit analysis"],"answer":0,"explanation":"Competency mapping identifies what a role needs and compares people against it, feeding selection, training and succession. Job evaluation sets the relative worth of jobs for pay.","difficulty":"easy","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-226","question":"Before a promotion decision, an employee deliberately withholds key client information from a rival colleague so that she performs badly in a presentation. This is an example of:","options":["Organisational citizenship behaviour","Illegitimate political behaviour","Social loafing","Job crafting"],"answer":1,"explanation":"Political behaviour is influence outside one's formal role aimed at personal advantage. Sabotaging a colleague is the illegitimate, harmful end of it, as opposed to legitimate tactics such as coalition-building.","difficulty":"easy","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-227","question":"A company decides to link 360° feedback scores directly to annual bonuses. What is the most likely problem?","options":["Managers will stop setting goals","Self-ratings will no longer be collected","Raters may trade favourable ratings or punish rivals, distorting the feedback","Feedback will become fully objective"],"answer":2,"explanation":"Once ratings affect pay, peers have incentives to collude, reciprocate or settle scores. Many firms therefore keep 360° feedback mainly for development.","difficulty":"moderate","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-228","question":"A manager with a team of five strong performers is told to place them on a 20% / 70% / 10% distribution. What is the main statistical problem?","options":["The distribution will always rate everyone as average","Five people are too many for any rating system","The distribution removes the need for performance data","Small groups need not follow a normal distribution, so one good performer is forced into the bottom"],"answer":3,"explanation":"Forced distributions assume performance follows a bell curve, which may hold roughly in large populations but not in a small, selected team. Applying quotas here mislabels good performers.","difficulty":"moderate","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-229","question":"After a job is re-evaluated into a lower grade, a long-serving employee's salary is now above the maximum of the new range. The company freezes his pay until the range catches up. His salary is called a:","options":["Red-circle rate","Green-circle rate","Compa-ratio","Broadband rate"],"answer":0,"explanation":"A red-circle rate is pay above the range maximum; such employees typically get lump sums instead of base increases. A green-circle rate is pay below the range minimum, which is usually raised quickly.","difficulty":"moderate","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-230","question":"A manager notices that a normally cheerful team member has gone quiet in meetings and has been snapping at colleagues. She checks in privately and listens to what is going on. Which element of emotional intelligence is she showing?","options":["Self-regulation","Empathy","Self-awareness","Achievement motivation"],"answer":1,"explanation":"Empathy is sensing and understanding others' feelings and responding to them. Self-awareness and self-regulation concern one's own emotions.","difficulty":"moderate","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-231","question":"Which of these is NOT a principle of interest-based (principled) negotiation?","options":["Separate the people from the problem","Focus on interests, not positions","Stick firmly to your position and concede slowly","Insist on objective criteria"],"answer":2,"explanation":"Principled negotiation separates people from the problem, focuses on interests, invents options for mutual gain and uses objective criteria. Positional haggling is what it aims to replace.","difficulty":"moderate","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-232","question":"A company of 1,200 employees has 15 people in its HR function. What is its HR-to-employee ratio per 100 employees?","options":["0.8","12.5","80","1.25"],"answer":3,"explanation":"HR staff per 100 employees = 15 / 1,200 × 100 = 1.25. 80 is the number of employees per HR person.","difficulty":"moderate","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-233","question":"A senior grade has 40 people; each year 80% stay and 20% leave. 8% of the 150 juniors are promoted into it each year. The plan needs 50 seniors next year. How many seniors must be hired from outside?","options":["6","10","18","0"],"answer":0,"explanation":"Internal supply = stayers 0.8 × 40 = 32, plus promotions 0.08 × 150 = 12, giving 44. Gap = 50 − 44 = 6 external hires.","difficulty":"hard","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-234","question":"Consider these statements about forced ranking (bell-curve) systems:\nI. In a strong team, good performers may be pushed into the bottom category.\nII. They reduce the leniency of managers who rate everyone highly.\nIII. They generally strengthen teamwork in roles where work is highly interdependent.\nIV. Calibration meetings without rigid quotas are one alternative.\nWhich are correct?","options":["I and III only","I, II and IV only","II, III and IV only","I, II, III and IV"],"answer":1,"explanation":"Forced quotas curb leniency but can mislabel strong teams and set colleagues against each other, which hurts collaboration (III is false). Calibration compares ratings across managers without fixed percentages.","difficulty":"hard","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-235","question":"A pay structure sets grade 1's midpoint at ₹30,000 a month, and each higher grade's midpoint is 15% above the one below. What is grade 4's midpoint?","options":["₹43,500","About ₹52,500","About ₹45,600","About ₹39,700"],"answer":2,"explanation":"Grade 4 is three steps above grade 1: 30,000 × 1.15³ ≈ ₹45,626. Adding 15% three times on the base (₹43,500) ignores the compounding.","difficulty":"hard","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-236","question":"A five-year employee earns ₹9 lakh a year. Market pressure has pushed new-hire pay for the same role to ₹8.6 lakh. The firm wants experienced staff to earn at least 15% more than new hires. What raise does this employee need?","options":["15%","About 4.4%","6%","About 9.9%"],"answer":3,"explanation":"Target pay = 8.6 × 1.15 = ₹9.89 lakh. Raise = 9.89 / 9 − 1 ≈ 9.9%. This fixes pay compression — the shrinking gap between experienced and new staff.","difficulty":"hard","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-237","question":"A bonus pool equals 8% of profit above ₹2 crore and is shared in proportion to salary. Profit is ₹3.5 crore and total payroll is ₹2 crore. How much does an employee earning ₹10 lakh receive?","options":["₹60,000","₹1,40,000","₹40,000","₹1,00,000"],"answer":0,"explanation":"Pool = 8% × (3.5 − 2) crore = ₹12 lakh. Her share = 10 / 200 = 5% of the pool = ₹60,000. ₹1,40,000 takes 8% of all profit, ignoring the threshold.","difficulty":"hard","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-238","question":"A firm's annual payroll is ₹50 crore. It grants a 6% merit increase from 1 October, in a financial year that runs from April to March. Roughly how much extra salary cost falls in the current financial year?","options":["₹3 crore","₹1.5 crore","₹0.75 crore","₹2.25 crore"],"answer":1,"explanation":"The full-year cost is 6% × ₹50 crore = ₹3 crore, but only six months (October–March) fall in this year: ₹1.5 crore. The full ₹3 crore lands in next year's budget.","difficulty":"hard","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-239","question":"A firm changes its voluntary savings plan from opt-in to automatic enrolment with an easy opt-out. Participation rises from 40% to 90%, though the plan's terms are unchanged. Which tendency does this change rely on?","options":["Framing effect","Overconfidence","Status quo (default) bias","Self-serving bias"],"answer":2,"explanation":"People tend to stay with whatever option is already set. Making enrolment the default turns that inertia into participation without changing the choice set.","difficulty":"hard","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-240","question":"A manager tells a peer: \"If you back my proposal at the review meeting, I'll lend you two of my analysts for your project next month.\" Which influence tactic is this?","options":["Ingratiation","Coalition tactics","Rational persuasion","Exchange"],"answer":3,"explanation":"Exchange offers a benefit or favour in return for support. Ingratiation uses flattery; coalition tactics enlist others' support; rational persuasion relies on logic and evidence.","difficulty":"hard","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-241","question":"In an employee survey, 120 people answer 'How likely are you to recommend this company as a place to work?' on a 0–10 scale: 48 score 9–10, 42 score 7–8 and 30 score 0–6. What is the employee Net Promoter Score (eNPS)?","options":["+15","+40","+18","-10"],"answer":0,"explanation":"Promoters = 48 / 120 = 40%; detractors = 30 / 120 = 25%. eNPS = 40 − 25 = +15. Passives count in the base but not in the difference.","difficulty":"hard","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-242","question":"An organisation has a CEO and four levels of managers below her. Every manager supervises exactly six people at the next level down, and the lowest managers each supervise six front-line staff. What share of total headcount is managerial?","options":["20%","About 16.7%","25%","About 14.3%"],"answer":1,"explanation":"Managers = 1 + 6 + 36 + 216 + 1,296 = 1,555; front-line = 6⁵ = 7,776. Share = 1,555 / 9,331 ≈ 16.7%. With a uniform span s, the managerial share tends towards 1/s.","difficulty":"very-hard","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-243","question":"A grade receives 30 promotions a year from the grade below and does not hire from outside. Each year 15% of its members leave or are promoted out. If these flows stay constant, what headcount will the grade settle at?","options":["255","35","200","176"],"answer":2,"explanation":"In steady state, inflow equals outflow: 30 = 0.15 × N, so N = 200. A grade's size is set by the ratio of its inflow to its exit rate.","difficulty":"very-hard","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-244","question":"A manager's target bonus is 15% of her ₹20 lakh salary. The payout equals the target bonus × individual performance factor × company performance factor. Her individual factor is 1.2 and the company factor is 0.8. What is her bonus?","options":["₹3.6 lakh","₹2.4 lakh","₹3 lakh","₹2.88 lakh"],"answer":3,"explanation":"Target = ₹3 lakh. Payout = 3 × 1.2 × 0.8 = ₹2.88 lakh. An additive 50:50 formula would give ₹3 lakh; multiplying means a weak company year cuts everyone's payout.","difficulty":"very-hard","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-245","question":"Assertion (A): Emotional intelligence can be developed through feedback and coaching.\nReason (R): Emotional intelligence concerns recognising and managing emotions in oneself and others.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":1,"explanation":"Both are true. R defines emotional intelligence but does not explain why it can be developed — that rests on evidence that these skills improve with practice, feedback and coaching.","difficulty":"very-hard","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-246","question":"A star salesperson is found to have exaggerated a client's needs to inflate an order. The client has not complained, and the regional head suggests a quiet verbal warning because the rep is key to this year's target.\nI. A utilitarian analysis should weigh long-term damage to trust, not just this quarter's revenue.\nII. Treating the star more leniently than others would breach the justice view of ethics.\nIII. Since the client has not complained, there is no ethical issue.\nIV. Applying the code consistently matters for its credibility.\nWhich are correct?","options":["I, II and IV only","I, II and III only","II and IV only","I, II, III and IV"],"answer":0,"explanation":"Misleading a client is wrong whether or not it is discovered (III is false). Consequences include lost trust and copycat behaviour; uneven treatment breaches fairness; and a code enforced only against weak performers loses its authority.","difficulty":"very-hard","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-247","question":"Match each power base with an example.\nA. Legitimate  B. Expert  C. Referent  D. Coercive\n1. A supervisor can put staff on unpopular night shifts as punishment\n2. Staff follow a colleague because they admire her and want to be like her\n3. A newly appointed department head approves leave requests\n4. Colleagues defer to an accountant's knowledge of tax rules","options":["A-4, B-3, C-2, D-1","A-3, B-2, C-4, D-1","A-3, B-4, C-2, D-1","A-3, B-4, C-1, D-2"],"answer":2,"explanation":"Legitimate power comes from the position, expert power from knowledge, referent power from admiration, and coercive power from the ability to punish.","difficulty":"very-hard","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-248","question":"In wage talks, the union scores each 1% of wage rise as 10 points and each extra leave day as 8 points. Each 1% costs management ₹50 lakh and each leave day ₹15 lakh. Which package gives the union at least 45 points at the lowest cost to management?","options":["4% wage rise + no extra leave","3% wage rise + 2 leave days","5% wage rise + no extra leave","2% wage rise + 4 leave days"],"answer":3,"explanation":"Scores and costs: 2% + 4 days = 52 points for ₹1.6 crore; 3% + 2 days = 46 for ₹1.8 crore; 5% = 50 for ₹2.5 crore; 4% = 40, below the bar. Leave days are cheap for management but valued by the union — trading on such differences is the core of integrative bargaining.","difficulty":"very-hard","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-249","question":"Candidates are scored 1–5 on customer focus (weight 0.40), analytical ability (0.35) and teamwork (0.25). Anyone scoring below 4 on customer focus is screened out. Scores: P — 4, 3, 5; Q — 5, 3, 3; R — 3, 5, 4; S — 4, 4, 3. Who is selected?","options":["P","Q","R","S"],"answer":0,"explanation":"Weighted totals: P 3.90, Q 3.80, R 3.95, S 3.75. R has the highest total but fails the customer-focus cut-off, so P is selected. A knock-out rule on a critical competency can override a compensatory total.","difficulty":"very-hard","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-250","question":"At an assessment centre, six candidates are given a business problem and told to reach a group decision in 30 minutes. Nobody is appointed chair, and assessors watch who takes initiative, listens and builds consensus. Which exercise is this?","options":["In-basket exercise","Leaderless group discussion","Structured interview","Reference check"],"answer":1,"explanation":"In a leaderless group discussion, no one is given a role, so assessors can see who emerges to lead, persuade and work with others.","difficulty":"easy","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-251","question":"An engagement survey is sent to 600 employees and 450 complete it. What is the response rate?","options":["45%","25%","75%","133%"],"answer":2,"explanation":"Response rate = responses / employees surveyed = 450 / 600 = 75%. A high rate makes the results more representative.","difficulty":"easy","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-252","question":"A hiring manager favours a candidate mainly because he went to the same college and has the same confident manner as the team's past star performers. Which bias is at work?","options":["Availability heuristic","Anchoring","Sunk-cost fallacy","Representativeness heuristic"],"answer":3,"explanation":"Representativeness judges likelihood by how closely something matches a stereotype or prototype. It ignores base rates and actual evidence of the candidate's ability.","difficulty":"moderate","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-253","question":"Selling a business, an owner hopes for ₹50 lakh but has privately decided she will not accept less than ₹42 lakh. ₹42 lakh is her:","options":["Reservation point","Target point","BATNA","Opening anchor"],"answer":0,"explanation":"The reservation point is the least favourable deal one will accept; ₹50 lakh is her target. Her BATNA is whatever she would do if no deal happens, which shapes where she sets the reservation point.","difficulty":"moderate","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-254","question":"In which situation is political behaviour in an organisation most likely to increase?","options":["Resources are plentiful and goals are clear","Resources are being cut and performance criteria are vague","Promotions follow transparent, objective rules","Roles are clearly defined and well understood"],"answer":1,"explanation":"Politics grows when there is competition for scarce resources and ambiguity about how decisions are made or performance is judged. Clear goals and transparent rules leave less room for it.","difficulty":"moderate","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-255","question":"A company moves from 15 narrow pay grades to four broad bands. What is the main risk it must manage?","options":["Employees will have less room for pay growth","Lateral moves will become harder","Pay costs may creep up because managers have wide discretion and fewer checkpoints","The structure will become more hierarchical"],"answer":2,"explanation":"Broad bands give flexibility and encourage lateral moves, but without guidance such as market reference points within the band, pay decisions can become inconsistent and costly. Fewer promotion steps can also disappoint people who value visible progression.","difficulty":"moderate","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-256","question":"A department has 30 full-time staff working 40 hours a week and 20 part-timers working 20 hours a week. What is its headcount in full-time equivalents (FTE)?","options":["50","30","45","40"],"answer":3,"explanation":"Each part-timer is 20 / 40 = 0.5 FTE, so 20 × 0.5 = 10. Total = 30 + 10 = 40 FTE, though the headcount is 50.","difficulty":"moderate","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-257","question":"In a 360° review of a manager, which rater group is best placed to judge how well she delegates and coaches?","options":["Her direct reports","Her boss","External customers","Peers in other departments"],"answer":0,"explanation":"Delegation and coaching are experienced most directly by the people she manages. Each rater group should be asked about behaviour it can actually observe.","difficulty":"moderate","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-258","question":"Each year 60% of juniors stay junior, 20% are promoted and 20% leave. Of 100 people who are juniors today, how many will still be juniors two years from now?","options":["60","36","20","40"],"answer":1,"explanation":"To still be junior after two years, a person must stay in both years: 100 × 0.6 × 0.6 = 36.","difficulty":"hard","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-259","question":"A factory pays ₹12 per unit with a guaranteed minimum of ₹600 a day. Worker A makes 45 units and Worker B makes 70 units in a day. What is the total wage for the two?","options":["₹1,380","₹1,200","₹1,440","₹1,500"],"answer":2,"explanation":"A earns 45 × 12 = ₹540, which is topped up to the ₹600 guarantee. B earns 70 × 12 = ₹840. Total = ₹1,440; ₹1,380 ignores the guarantee.","difficulty":"hard","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-260","question":"Ten sales roles stay vacant for an average of 60 working days each. Each filled role brings in about ₹1,500 of contribution per working day. What is the approximate contribution lost to these vacancies?","options":["₹90,000","₹18 lakh","₹4.5 lakh","₹9 lakh"],"answer":3,"explanation":"Lost contribution = 10 roles × 60 days × ₹1,500 = ₹9,00,000. Cost of vacancy is a strong argument for investing in faster hiring.","difficulty":"hard","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-261","question":"A company has 3,125 front-line staff. With a span of 5 at every level it needs 781 managers in five layers. If it widens the span to 25 at every level, what changes?","options":["2 layers and 650 managerial positions disappear","2 layers and 625 positions disappear","3 layers and 650 positions disappear","1 layer and 500 positions disappear"],"answer":0,"explanation":"At span 25: 3,125 / 25 = 125 managers, 125 / 25 = 5 above them, and 1 at the top — 131 managers in three layers. That removes 2 layers and 781 − 131 = 650 positions.","difficulty":"hard","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-262","question":"An engagement driver analysis gives each item's favourable score and its correlation with overall engagement: A — 85%, 0.2; B — 55%, 0.7; C — 60%, 0.3; D — 90%, 0.6. Which item should be the top priority?","options":["A","B","C","D"],"answer":1,"explanation":"Priorities combine low scores with strong links to engagement. B scores lowest and has the highest correlation. D matters a lot but already scores well; A and C have weaker links.","difficulty":"hard","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-263","question":"Consider these statements about emotional intelligence:\nI. It includes perceiving and understanding emotions in others.\nII. A high IQ guarantees a high level of emotional intelligence.\nIII. Self-regulation helps a leader avoid impulsive reactions under pressure.\nIV. It is entirely fixed at birth.\nWhich are correct?","options":["I, II and III only","II and IV only","I and III only","I, III and IV only"],"answer":2,"explanation":"Emotional intelligence covers recognising and managing one's own and others' emotions. It is distinct from IQ (II is false) and can be developed (IV is false).","difficulty":"hard","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-264","question":"A buyer has researched the market well and has a good idea of the seller's likely range. What is generally the best opening move?","options":["Always wait for the other side to open first","Open with her own reservation price to signal honesty","Begin by revealing the weaknesses of her BATNA","Make the first offer, at an ambitious but defensible figure"],"answer":3,"explanation":"With good information, opening first lets her set the anchor that later offers move around. The figure should be bold but justifiable. Revealing a reservation price or a weak BATNA gives away bargaining room.","difficulty":"hard","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-265","question":"An employee files a confidential harassment complaint. The CEO, who is close to the accused manager, asks the HR head privately for the complainant's name. What should the HR head do?","options":["Decline, follow the confidential complaints procedure and offer to brief the CEO on process, not identity","Share the name since the CEO is the most senior person","Drop the complaint to avoid conflict with the CEO","Tell the accused manager first so he can respond"],"answer":0,"explanation":"Confidentiality protects complainants from retaliation and keeps the process credible. The CEO's closeness to the accused is a conflict of interest, so the HR head should use the formal procedure and, if needed, independent oversight.","difficulty":"hard","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-266","question":"A firm has 100 juniors and 40 seniors. Each year 70% of juniors stay, 10% are promoted and 20% leave; 80% of seniors stay and 20% leave. 25 new juniors are hired at the end of each year, and no seniors are hired from outside. How many seniors will there be after two years?","options":["42","43.1","44","33.6"],"answer":1,"explanation":"Year 1: seniors = 0.8 × 40 + 0.1 × 100 = 42; juniors = 0.7 × 100 + 25 = 95. Year 2: seniors = 0.8 × 42 + 0.1 × 95 = 33.6 + 9.5 = 43.1.","difficulty":"very-hard","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-267","question":"Plan X pays a rep ₹4 lakh a year fixed plus 2% of sales. Plan Y pays ₹2 lakh fixed plus a commission chosen so that both plans pay the same at ₹80 lakh of sales. What commission rate must Plan Y use?","options":["4%","2.5%","4.5%","5%"],"answer":2,"explanation":"Plan X at ₹80 lakh = 4 + 1.6 = ₹5.6 lakh. Plan Y needs 2 + r × 80 = 5.6, so r = 3.6 / 80 = 4.5%. Above ₹80 lakh Plan Y pays more and below it pays less, so it suits confident, high-performing reps.","difficulty":"very-hard","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-268","question":"A pay range runs from ₹40,000 to ₹60,000 a month and an employee earns ₹55,000. What are her range penetration and compa-ratio?","options":["Range penetration 110%, compa-ratio 0.75","Range penetration 91.7%, compa-ratio 1.10","Range penetration 75%, compa-ratio 0.92","Range penetration 75%, compa-ratio 1.10"],"answer":3,"explanation":"Range penetration = (55,000 − 40,000) / (60,000 − 40,000) = 75%. Compa-ratio = 55,000 / midpoint 50,000 = 1.10. 91.7% is salary / maximum, which is not a standard measure.","difficulty":"very-hard","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-269","question":"Assertion (A): Managers tend to stick with a failing project longer when they personally approved it in the first place.\nReason (R): People continue failing courses of action partly to justify their earlier choices and protect their self-image.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":0,"explanation":"Both are true, and R explains A. Personal responsibility for the original decision raises the need for self-justification, which drives escalation of commitment. Handing the review to someone new is one remedy.","difficulty":"very-hard","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-270","question":"Match each negotiation concept with its meaning.\nA. BATNA  B. Reservation point  C. ZOPA  D. Anchor\n1. The overlap between both sides' walk-away points\n2. The least favourable deal a party will still accept\n3. The best course of action if no agreement is reached\n4. An early number that pulls later offers towards it","options":["A-2, B-3, C-1, D-4","A-3, B-2, C-1, D-4","A-3, B-1, C-2, D-4","A-3, B-2, C-4, D-1"],"answer":1,"explanation":"The BATNA is the fallback, and it sets the reservation point. The ZOPA is where the two reservation points overlap. An anchor is a first figure that draws the bargaining towards it.","difficulty":"very-hard","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-271","question":"At an assessment centre, two assessors score a candidate (1–5) on three exercises weighted 0.5, 0.2 and 0.3. Exercise 1: 4 and 3; Exercise 2: 5 and 5; Exercise 3: 2 and 4. Averaging the two assessors first, what is the candidate's weighted overall rating?","options":["3.83","4.1","3.65","3.5"],"answer":2,"explanation":"Assessor averages: 3.5, 5 and 3. Weighted = 0.5 × 3.5 + 0.2 × 5 + 0.3 × 3 = 1.75 + 1.0 + 0.9 = 3.65. 3.83 is the unweighted mean. The 2-point gap on Exercise 3 is a cue for the assessors to discuss and agree a score.","difficulty":"very-hard","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-272","question":"Consider these ways of improving decisions:\nI. A pre-mortem, imagining the project has failed and asking why, can reduce overconfidence.\nII. Appointing a devil's advocate can reduce the risk of groupthink.\nIII. Anchoring has no effect when the anchor is obviously random.\nIV. Agreeing review points and exit criteria in advance can limit escalation of commitment.\nWhich are correct?","options":["I, II and III only","II and III only","I, II, III and IV","I, II and IV only"],"answer":3,"explanation":"Pre-mortems surface risks, devil's advocates legitimise dissent, and pre-set exit criteria stop sunk costs from driving continuation. III is false: experiments show that even clearly random numbers bias later estimates.","difficulty":"very-hard","source":"HR analyst · Consulting · MBA placement pattern"},
  {"id":"mgmt-hr-ob-273","question":"Consider these statements about Robert Katz's three managerial skills:\nI. Technical skill matters most for first-line supervisors.\nII. Human skill is important at every level of management.\nIII. Conceptual skill matters least for top management.\nWhich are correct?","options":["I and II only","I, II and III","II and III only","I only"],"answer":0,"explanation":"Katz held that technical skill dominates at the bottom, conceptual skill rises in importance towards the top, and human skill is needed throughout. Statement III reverses the pattern for conceptual skill.","difficulty":"hard","source":"HR MT · Consulting · MBA placement"},
  {"id":"mgmt-hr-ob-274","question":"Two hospitals reach the same patient-satisfaction score: one by investing heavily in diagnostic technology, the other by retraining its nurses in patient communication. Which open-systems concept does this illustrate?","options":["Synergy","Negative entropy","Equifinality","Homeostasis"],"answer":2,"explanation":"Equifinality means an open system can reach the same end state from different starting points and by different paths. Synergy is about the whole exceeding the sum of its parts, which is not the point here.","difficulty":"moderate","source":"HR MT · MBA placement"},
  {"id":"mgmt-hr-ob-275","question":"In a large hospital, senior doctors have wide autonomy over their work, coordination relies on the skills they acquired during long professional training, and the operating core is the most powerful part of the organisation. Which of Mintzberg's configurations is this?","options":["Machine bureaucracy","Professional bureaucracy","Simple structure","Adhocracy"],"answer":1,"explanation":"A professional bureaucracy coordinates through standardisation of skills and gives power to the operating core of trained professionals. A machine bureaucracy standardises work processes and gives power to the technostructure.","difficulty":"hard","source":"Consulting · MBA placement"},
  {"id":"mgmt-hr-ob-276","question":"A quick-service restaurant chain gives every cook a detailed manual specifying how long to fry, how much sauce to add and the exact order of assembly. Which of Mintzberg's coordinating mechanisms is this?","options":["Mutual adjustment","Standardisation of outputs","Standardisation of skills","Standardisation of work processes"],"answer":3,"explanation":"Specifying the steps of the work itself is standardisation of work processes. Standardising outputs would fix only the result (for example, a burger meeting a spec) and leave the method open.","difficulty":"hard","source":"Consulting · FMCG MT"},
  {"id":"mgmt-hr-ob-277","question":"In Joan Woodward's study of manufacturing firms, what did she find about successful firms using large-batch and mass-production technology?","options":["They had organic structures with narrow first-line spans of control","They had mechanistic structures with the widest first-line spans of control","They had organic structures with the widest first-line spans of control","They had mechanistic structures with the narrowest first-line spans of control"],"answer":1,"explanation":"Woodward found that successful mass-production firms were mechanistic and had the widest spans of control at supervisor level, while successful unit and process producers were more organic. Process technology had the narrowest first-line spans.","difficulty":"very-hard","source":"Consulting · MBA placement"},
  {"id":"mgmt-hr-ob-278","question":"A firm's R&D, production and sales departments differ sharply in goals, time horizons and formality, and the firm operates in an uncertain, fast-changing industry. According to Lawrence and Lorsch, what combination marked the high performers in such industries?","options":["Low differentiation and high integration","High differentiation and low integration","High differentiation and high integration","Low differentiation and low integration"],"answer":2,"explanation":"In uncertain environments departments must be highly differentiated to cope with their own sub-environments, so high performers also invested heavily in integrating devices to hold them together. Differentiation without integration produced conflict and poor results.","difficulty":"hard","source":"Consulting · MBA placement"},
  {"id":"mgmt-hr-ob-279","question":"In a company, 10% of applicants turn out to be high performers. A screening test flags 90% of future high performers and also wrongly flags 20% of the others. If a candidate is flagged, what is the probability that she will be a high performer?","options":["90%","45%","50%","About 33%"],"answer":3,"explanation":"P(flag) = 0.1 × 0.9 + 0.9 × 0.2 = 0.27, so P(high | flag) = 0.09 / 0.27 = 1/3. Answering 90% is base-rate neglect: it confuses the test's hit rate with the chance a flagged person is good.","difficulty":"very-hard","source":"HR analyst · Consulting · MBA placement"},
  {"id":"mgmt-hr-ob-280","question":"In a university, decisions seem to emerge whenever problems, ready-made solutions, the people who happen to attend a meeting and a choice opportunity happen to coincide, rather than through orderly analysis. Which model of decision making describes this?","options":["Garbage can model","Rational model","Incremental (muddling through) model","Satisficing model"],"answer":0,"explanation":"The garbage can model of Cohen, March and Olsen describes 'organised anarchies' where problems, solutions, participants and choice opportunities flow independently and decisions occur when they meet.","difficulty":"hard","source":"Consulting · MBA placement"},
  {"id":"mgmt-hr-ob-281","question":"A manager must make a decision where quality matters, she lacks key information that her team has, the team shares the organisation's goals, and the team's acceptance is critical and unlikely if she decides alone. Which style does the Vroom–Yetton model prefer?","options":["AI: decide alone with available information","AII: get the facts from the team, then decide alone","CI: consult team members one by one, then decide","GII: share the problem with the group and reach a consensus decision"],"answer":3,"explanation":"When acceptance is critical, unlikely under an autocratic decision, and subordinates share the organisation's goals, the acceptance-priority rule favours GII, where the group shares the decision as equals. The A and C styles keep the final call with the manager and risk rejection.","difficulty":"very-hard","source":"Consulting · MBA placement"},
  {"id":"mgmt-hr-ob-282","question":"A manager fully trusts her subordinates, decisions are made by groups at every level, communication flows up, down and sideways, and goals are set participatively. Which of Rensis Likert's management systems is this?","options":["System 1: exploitive-authoritative","System 2: benevolent-authoritative","System 3: consultative","System 4: participative group"],"answer":3,"explanation":"Likert's System 4 combines complete trust, group decision making throughout and free multi-directional communication. In System 3, the manager consults but still takes the main decisions.","difficulty":"moderate","source":"HR MT · MBA placement"},
  {"id":"mgmt-hr-ob-283","question":"In Likert's model, a manager belongs both to the team she leads and to the team of peers led by her own boss, carrying information and influence between the two. What did Likert call this role?","options":["Gatekeeper","Linking pin","Boundary spanner","Liaison officer"],"answer":1,"explanation":"Likert's 'linking pin' connects overlapping work groups up the hierarchy. A boundary spanner links the organisation with its external environment, not one internal level with another.","difficulty":"hard","source":"HR MT · MBA placement"},
  {"id":"mgmt-hr-ob-284","question":"In the Hawthorne Bank Wiring Room study, workers who produced more than the group's informal output norm were called 'rate-busters' and were pressured to slow down, even though a group incentive scheme was in place. What does this mainly show?","options":["Financial incentives always override social pressure","Better lighting raises productivity","Close supervision raises output","Informal group norms can restrict output despite financial incentives"],"answer":3,"explanation":"The study showed that informal groups set their own production norms and enforce them socially, sometimes against management's incentives. This challenged the scientific-management view that pay alone drives output.","difficulty":"hard","source":"HR MT · MBA placement"},
  {"id":"mgmt-hr-ob-285","question":"Which three elements of the McKinsey 7S framework are usually classed as the 'hard' elements?","options":["Strategy, structure and systems","Strategy, structure and staff","Structure, systems and skills","Strategy, shared values and systems"],"answer":0,"explanation":"Strategy, structure and systems are the hard elements that management can define directly. Shared values, style, staff and skills are the soft elements, with shared values at the centre.","difficulty":"moderate","source":"Consulting · MBA placement"},
  {"id":"mgmt-hr-ob-286","question":"A growing company had earlier given regional heads wide decision-making freedom. Now each region behaves like an independent fiefdom and top management feels it has lost oversight. In Greiner's growth model, which crisis is this and how is it typically resolved?","options":["Crisis of control, resolved by coordination through formal planning and review systems","Crisis of autonomy, resolved by delegation to regional heads","Crisis of red tape, resolved by collaboration and team-based working","Crisis of leadership, resolved by strong central direction"],"answer":0,"explanation":"Growth through delegation ends in a crisis of control, which Greiner says is resolved by a coordination phase with formal systems, central planning and product groups. The crisis of autonomy comes earlier and is solved by delegation itself.","difficulty":"very-hard","source":"Consulting · MBA placement"},
  {"id":"mgmt-hr-ob-287","question":"A fast-growing start-up's founder still approves every decision; as headcount crosses 150, decisions pile up and talented managers complain they cannot act. In Greiner's model, the founder faces a crisis that is resolved by moving into which phase?","options":["Delegation","Coordination","Direction under professional management","Collaboration"],"answer":2,"explanation":"Growth through creativity ends in a crisis of leadership, which Greiner says is resolved by growth through direction: professional management and a clearer functional structure. Delegation comes only after the later crisis of autonomy.","difficulty":"very-hard","source":"Consulting · MBA placement"},
  {"id":"mgmt-hr-ob-288","question":"In a strong (project-heavy) matrix organisation, which of these is generally true?","options":["Functional managers control project budgets and priorities","Project managers have more authority than functional managers over the project's work","Project managers act only as expediters with no real authority","Staff report only to project managers and have no functional home"],"answer":1,"explanation":"In a strong matrix the balance of power tilts to project managers, who control budgets and priorities, while functional managers mainly supply people and technical standards. An expediter role belongs to a weak matrix; no functional home describes a pure project structure.","difficulty":"hard","source":"Consulting · MBA placement"},
  {"id":"mgmt-hr-ob-289","question":"The HR head can require all departments to follow a standard interview procedure and a fixed set of offer approvals, even though the line managers involved do not report to her. What kind of authority is this?","options":["Line authority","Advisory staff authority","Functional authority","Charismatic authority"],"answer":2,"explanation":"Functional authority is the right of a staff specialist to set binding rules within her specialty for people in other departments. Pure staff authority would only allow her to advise.","difficulty":"hard","source":"HR MT · MBA placement"},
  {"id":"mgmt-hr-ob-290","question":"In a family business, the eldest son becomes managing director when his father retires, simply because that is how leadership has always passed in the family. Which of Weber's types of authority does this rest on?","options":["Rational-legal authority","Traditional authority","Charismatic authority","Expert authority"],"answer":1,"explanation":"Weber's traditional authority rests on custom and inherited status. Rational-legal authority would rest on formal rules and position earned through competence; charismatic authority on personal magnetism.","difficulty":"moderate","source":"HR MT · MBA placement"},
  {"id":"mgmt-hr-ob-291","question":"A regional head pushes a local discount scheme that lifts her own region's volume and bonus but lowers the company's overall margin. Which of Fayol's principles is she violating?","options":["Initiative","Centralisation","Subordination of individual interest to general interest","Remuneration"],"answer":2,"explanation":"Fayol held that the interest of the organisation must prevail over that of an individual or a sub-group. Initiative is encouraged by Fayol, but only within the firm's interest.","difficulty":"moderate","source":"HR MT · MBA placement"},
  {"id":"mgmt-hr-ob-292","question":"Analysing a bricklayer's work into basic hand motions such as search, grasp, transport and release, and then removing the unnecessary ones, is associated with:","options":["Henry Gantt","Frank and Lillian Gilbreth","Harrington Emerson","Max Weber"],"answer":1,"explanation":"The Gilbreths pioneered motion study and named the basic motions 'therbligs'. Gantt is known for the Gantt chart and the task-and-bonus plan.","difficulty":"moderate","source":"HR MT · MBA placement"},
  {"id":"mgmt-hr-ob-293","question":"A job has a standard time of 10 hours, a worker completes it in 8 hours, and the time rate is ₹100 an hour. Under the Rowan premium plan, what are her total earnings for the job?","options":["₹900","₹1,000","₹960","₹1,040"],"answer":2,"explanation":"Rowan bonus = (time saved / standard time) × time taken × rate = (2/10) × 8 × 100 = ₹160, so earnings = 800 + 160 = ₹960. ₹900 is the Halsey plan at 50% of time saved.","difficulty":"hard","source":"HR MT · MBA placement"},
  {"id":"mgmt-hr-ob-294","question":"A job has a standard time of 12 hours. Apart from finishing exactly on standard, at what actual time taken do the Halsey plan (50% sharing) and the Rowan plan pay the same bonus?","options":["4 hours","8 hours","9 hours","6 hours"],"answer":3,"explanation":"Halsey bonus = 0.5(S − T)R and Rowan bonus = (S − T)/S × T × R; they are equal when T/S = 0.5, that is T = 6 hours. Faster than that Halsey pays more; slower, Rowan pays more.","difficulty":"very-hard","source":"HR MT · MBA placement"},
  {"id":"mgmt-hr-ob-295","question":"Assertion (A): Under the Rowan premium plan, a very fast worker can never earn more than double her time wages for the hours worked.\nReason (R): Under the Rowan plan, the bonus as a share of time wages equals the proportion of standard time saved, which is always less than 100%.","options":["Both A and R are true and R explains A","Both A and R are true but R does not explain A","A is true but R is false","A is false but R is true"],"answer":0,"explanation":"Rowan bonus / time wages = (S − T)/S, the fraction of time saved, which stays below 1. So earnings per hour worked stay below twice the time rate; R is exactly why A holds.","difficulty":"very-hard","source":"HR MT · MBA placement"},
  {"id":"mgmt-hr-ob-296","question":"A planning team assumes that tax rates will stay unchanged and that the monsoon will be normal for the next three years, and builds its sales plan on these assumptions. These assumptions are called:","options":["Planning premises","Policies","Objectives","Procedures"],"answer":0,"explanation":"Planning premises are the assumptions about the future environment on which plans rest. Policies are guides to decision making, and objectives are the ends the plan aims at.","difficulty":"moderate","source":"HR MT · MBA placement"},
  {"id":"mgmt-hr-ob-297","question":"Consider these statements about mechanistic and organic structures (Burns and Stalker):\nI. Mechanistic structures rely on clear hierarchy and precisely defined tasks.\nII. Organic structures use lateral communication and continual redefinition of tasks.\nIII. A firm in a stable market will always perform worse with a mechanistic structure.\nWhich are correct?","options":["I, II and III","I only","I and II only","II and III only"],"answer":2,"explanation":"I and II describe the two forms correctly. III is wrong: Burns and Stalker argued mechanistic structures suit stable environments, and organic ones suit changing environments.","difficulty":"hard","source":"Consulting · MBA placement"},
  {"id":"mgmt-hr-ob-298","question":"Match each Mintzberg configuration with its key coordinating mechanism.\nA. Simple structure  B. Machine bureaucracy  C. Divisionalised form  D. Adhocracy\n1. Mutual adjustment  2. Direct supervision  3. Standardisation of outputs  4. Standardisation of work processes","options":["A-2, B-4, C-3, D-1","A-2, B-3, C-4, D-1","A-1, B-4, C-3, D-2","A-4, B-2, C-1, D-3"],"answer":0,"explanation":"A simple structure runs on the owner's direct supervision, a machine bureaucracy standardises work processes, divisions are controlled through output targets, and an adhocracy coordinates through mutual adjustment among experts.","difficulty":"hard","source":"Consulting · MBA placement"},
  {"id":"mgmt-hr-ob-299","question":"A company draws up targets and leaves each plant manager free to choose how to meet them, but checks results monthly against output and cost figures. Which statement is the best reading?","options":["It is a highly centralised firm that controls inputs","It controls through standardisation of outputs while decentralising methods","It relies on mutual adjustment, with no formal control","It is a pure matrix structure"],"answer":1,"explanation":"Fixing results while leaving methods open is control through standardisation of outputs, typical of divisionalised firms. Decision rights over methods are decentralised; the firm still controls tightly on results.","difficulty":"hard","source":"Consulting · MBA placement"},
  {"id":"mgmt-hr-ob-300","question":"Consider these statements comparing Alderfer's ERG theory with Maslow's hierarchy:\nI. ERG allows more than one need level to motivate a person at the same time.\nII. ERG adds a frustration–regression path, so a blocked higher need can intensify a lower one.\nIII. ERG holds that a lower need must be fully satisfied before a higher one becomes active.\nWhich are correct?","options":["I and II only","II and III only","I, II and III","I only"],"answer":0,"explanation":"ERG drops Maslow's rigid step-by-step progression, allows several needs to operate together and adds frustration–regression. Statement III describes Maslow's strict prepotency, not ERG.","difficulty":"hard","source":"HR MT · MBA placement"},
  {"id":"mgmt-hr-ob-301","question":"In the Porter–Lawler model of motivation, which sequence best describes the causal chain?","options":["Satisfaction → effort → performance → rewards","Effort → satisfaction → performance → rewards","Effort → performance → rewards → satisfaction, if the rewards are seen as fair","Rewards → satisfaction → effort → performance"],"answer":2,"explanation":"Porter and Lawler reversed the human-relations idea that a satisfied worker performs better: effort produces performance, performance earns rewards, and satisfaction follows when the rewards are perceived as equitable.","difficulty":"hard","source":"HR MT · MBA placement"},
  {"id":"mgmt-hr-ob-302","question":"An engineer works long hours and is highly skilled, yet her appraisal is poor because she spent the year polishing features her manager considered low priority. In the Porter–Lawler model, which factor broke the link between effort and performance?","options":["Abilities and traits","Perceived equity of rewards","Valence of rewards","Role perceptions"],"answer":3,"explanation":"Porter–Lawler says effort turns into performance only with adequate abilities and accurate role perceptions. Her skill and effort were fine; she misread what the role required.","difficulty":"hard","source":"HR MT · Consulting"},
  {"id":"mgmt-hr-ob-303","question":"Field sales reps earn a commission on each sale, and a sale comes after an unpredictable number of calls — sometimes the 3rd, sometimes the 15th. Which reinforcement schedule are they on, and what is its main property?","options":["Fixed ratio; produces a pause after each reward","Variable interval; produces slow, steady responding","Variable ratio; produces high, steady responding that resists extinction","Fixed interval; produces a spurt just before each reward"],"answer":2,"explanation":"Reward after an unpredictable number of responses is a variable-ratio schedule, which yields the highest and most persistent response rate. Fixed schedules produce post-reward pauses.","difficulty":"hard","source":"HR MT · MBA placement"},
  {"id":"mgmt-hr-ob-304","question":"Employees paid a fixed salary on the last day of each month are observed to relax just after payday and work hardest just before month-end reviews. Which reinforcement schedule produces this pattern?","options":["Fixed interval","Variable ratio","Variable interval","Continuous"],"answer":0,"explanation":"A fixed-interval schedule rewards after a set time, producing a 'scalloped' pattern: low effort after the reward and a spurt as the next one nears.","difficulty":"moderate","source":"HR MT · MBA placement"},
  {"id":"mgmt-hr-ob-305","question":"A manager has been sending an employee daily reminder emails about late reports. She stops the reminders as soon as the employee starts submitting on time, and on-time submission keeps rising. Which reinforcement principle is at work?","options":["Positive reinforcement","Punishment","Extinction","Negative reinforcement"],"answer":3,"explanation":"Removing an unpleasant stimulus (the nagging) when the desired behaviour occurs strengthens that behaviour: negative reinforcement. It is often confused with punishment, which weakens a behaviour.","difficulty":"very-hard","source":"HR MT · MBA placement"},
  {"id":"mgmt-hr-ob-306","question":"A team member used to crack jokes in meetings and got laughs. The manager now asks everyone to ignore the jokes completely, and over a few weeks the joking fades away. This is:","options":["Negative reinforcement","Extinction","Punishment","Shaping"],"answer":1,"explanation":"Withholding the reinforcer (laughter) that had been maintaining a behaviour makes the behaviour die out, which is extinction. Nothing unpleasant was added, so it is not punishment.","difficulty":"moderate","source":"HR MT · MBA placement"},
  {"id":"mgmt-hr-ob-307","question":"Volunteers who happily tutored children every weekend are offered ₹200 an hour, with close monitoring of hours logged. Months later the payment is withdrawn and many stop tutoring altogether. Which theory best explains this?","options":["Herzberg's hygiene theory","Cognitive evaluation theory","Equity theory","Reinforcement theory"],"answer":1,"explanation":"Cognitive evaluation theory says extrinsic rewards perceived as controlling can crowd out intrinsic motivation, shifting the reason for the activity from enjoyment to pay. When pay goes, so does the motivation.","difficulty":"hard","source":"HR MT · Consulting"},
  {"id":"mgmt-hr-ob-308","question":"Self-determination theory says people are most intrinsically motivated when three basic psychological needs are met. Which are they?","options":["Achievement, power and affiliation","Existence, relatedness and growth","Autonomy, competence and relatedness","Security, esteem and self-actualisation"],"answer":2,"explanation":"Deci and Ryan's self-determination theory names autonomy, competence and relatedness. Achievement, power and affiliation are McClelland's needs; existence, relatedness and growth are Alderfer's.","difficulty":"moderate","source":"HR MT · MBA placement"},
  {"id":"mgmt-hr-ob-309","question":"An employee's expectancy of hitting a target is 0.8. Hitting it leads to a bonus (instrumentality 0.9, valence +0.6) and also to a transfer to another city (instrumentality 0.5, valence −0.8). Using Vroom's model, motivational force = E × Σ(I × V). What is it?","options":["0.432","0.112","0.752","0.14"],"answer":1,"explanation":"Σ(I × V) = 0.9 × 0.6 + 0.5 × (−0.8) = 0.54 − 0.40 = 0.14, so force = 0.8 × 0.14 = 0.112. Treating the unwanted transfer as positive gives 0.752; ignoring it gives 0.432.","difficulty":"very-hard","source":"HR analyst · MBA placement"},
  {"id":"mgmt-hr-ob-310","question":"An employee's expectancy of reaching a target is 0.6 and the reward for reaching it has a valence of 0.8. If the company wants her motivational force (E × I × V) to be at least 0.36, what minimum instrumentality must it create?","options":["0.6","0.48","0.75","0.9"],"answer":2,"explanation":"0.6 × I × 0.8 ≥ 0.36 gives I ≥ 0.36 / 0.48 = 0.75. The 0.48 is E × V, not the required instrumentality.","difficulty":"hard","source":"HR analyst · MBA placement"},
  {"id":"mgmt-hr-ob-311","question":"Workers paid on a piece rate come to believe they are overpaid for each unit. According to Adams' equity theory, how are they most likely to respond?","options":["Produce more units of lower quality","Produce fewer units of higher quality","Ask for a cut in their piece rate","Produce more units of higher quality"],"answer":1,"explanation":"Under a piece rate, producing more would only widen the overpayment, so they raise their inputs per unit instead: fewer but better-quality units. Hourly-paid overpaid workers, by contrast, tend to produce more.","difficulty":"very-hard","source":"HR MT · Consulting"},
  {"id":"mgmt-hr-ob-312","question":"Asha earns ₹80,000 a month with 6 years of experience. Her colleague Vikram earns ₹1,00,000 with 10 years. If both see experience as the only relevant input, what does equity theory predict?","options":["Asha feels under-rewarded relative to Vikram","Both feel equitably treated","Vikram feels over-rewarded relative to Asha","Vikram feels under-rewarded relative to Asha"],"answer":3,"explanation":"Pay per year of experience is about ₹13,333 for Asha and ₹10,000 for Vikram. Vikram's ratio is lower, so he is the one likely to feel under-rewarded, even though he earns more in absolute terms.","difficulty":"hard","source":"HR MT · MBA placement"},
  {"id":"mgmt-hr-ob-313","question":"A new analyst is learning a complex financial-modelling task that is entirely unfamiliar to her. According to later research on goal setting, which goal is most likely to help her performance in the first few weeks?","options":["A learning goal, such as mastering five specific modelling techniques","A very difficult, specific output target for models completed","A 'do your best' goal","No goal at all until she is confident"],"answer":0,"explanation":"For complex, novel tasks, hard performance goals can push people into rushing rather than learning strategies, so specific learning goals work better. Once the skill is acquired, difficult performance goals help.","difficulty":"very-hard","source":"HR MT · Consulting"},
  {"id":"mgmt-hr-ob-314","question":"Which is a standard criticism of Herzberg's two-factor theory?","options":["It ignores pay completely","It was based only on animal experiments","It does not distinguish between satisfaction and dissatisfaction","Its critical-incident method invites self-serving answers, crediting oneself for good times and the environment for bad ones"],"answer":3,"explanation":"Herzberg asked people to recall very good and very bad job events; respondents tend to attribute success to themselves (motivators) and failure to context (hygiene). This bias may have produced the two factors.","difficulty":"hard","source":"HR MT · MBA placement"},
  {"id":"mgmt-hr-ob-315","question":"A well-paid, widely respected senior architect leaves her firm to design low-cost housing because she feels it is what she is truly meant to do. In Maslow's hierarchy, which need drives her move?","options":["Esteem","Social","Self-actualisation","Safety"],"answer":2,"explanation":"She already has pay and respect; she is seeking to realise her full potential, which is self-actualisation. Esteem is about recognition and status, which she already enjoys.","difficulty":"moderate","source":"HR MT · MBA placement"},
  {"id":"mgmt-hr-ob-316","question":"McClelland's research on effective senior managers in large organisations found that they usually combine:","options":["High need for achievement and high need for affiliation","High need for power (institutional, used for the organisation) and low need for affiliation","High need for affiliation and low need for power","High need for achievement and low need for power"],"answer":1,"explanation":"McClelland found that the best large-organisation managers have a high, socialised need for power and relatively low affiliation needs. High achievers often make strong individual contributors but may not delegate well.","difficulty":"very-hard","source":"HR MT · Consulting"},
  {"id":"mgmt-hr-ob-317","question":"A job scores skill variety 6, task identity 5, task significance 4, autonomy 2 and feedback 6 (each on a 1–7 scale), where MPS = [(SV + TI + TS)/3] × autonomy × feedback. Which single change raises its MPS the most?","options":["Raising task identity by 2 points","Raising feedback by 1 point","Raising task significance by 3 points","Raising autonomy by 1 point"],"answer":3,"explanation":"Base MPS = 5 × 2 × 6 = 60. Autonomy +1 gives 5 × 3 × 6 = 90; feedback +1 gives 70; task significance +3 gives 6 × 2 × 6 = 72; task identity +2 gives about 68. Autonomy and feedback multiply the score, so a low autonomy rating is the biggest lever.","difficulty":"very-hard","source":"HR analyst · MBA placement"},
  {"id":"mgmt-hr-ob-318","question":"Match each core job dimension with the critical psychological state it mainly creates in Hackman and Oldham's model.\nA. Skill variety  B. Autonomy  C. Feedback\n1. Knowledge of the actual results of work  2. Experienced responsibility for outcomes  3. Experienced meaningfulness of work","options":["A-3, B-1, C-2","A-3, B-2, C-1","A-2, B-3, C-1","A-1, B-2, C-3"],"answer":1,"explanation":"Skill variety, task identity and task significance create meaningfulness; autonomy creates felt responsibility; feedback creates knowledge of results.","difficulty":"hard","source":"HR MT · MBA placement"},
  {"id":"mgmt-hr-ob-319","question":"A company enriches all jobs in a back-office unit. Some employees thrive, but others become anxious and less satisfied. In the job characteristics model, which moderator best explains the difference?","options":["Growth-need strength","Locus of control","Task significance","Distributive justice"],"answer":0,"explanation":"Hackman and Oldham noted that people with high growth-need strength respond well to enriched jobs, while those with low growth-need strength may find them stressful.","difficulty":"hard","source":"HR MT · MBA placement"},
  {"id":"mgmt-hr-ob-320","question":"A data-entry clerk is now also asked to file documents and answer the department's phones, but gets no extra say in planning or checking her work. This is:","options":["Job enrichment","Job rotation","Job sharing","Job enlargement"],"answer":3,"explanation":"Adding more tasks at the same level of skill and responsibility is job enlargement (horizontal loading). Enrichment would add planning, control and decision authority (vertical loading).","difficulty":"moderate","source":"HR MT · MBA placement"},
  {"id":"mgmt-hr-ob-321","question":"Which set of practices best describes William Ouchi's Theory Z organisation?","options":["Short-term contracts, individual decisions and rapid promotion","Strict hierarchy, close supervision and piece-rate pay","Lifetime employment, collective decision making with individual responsibility, and slow evaluation and promotion","Specialised career paths, explicit formal controls and individual responsibility"],"answer":2,"explanation":"Ouchi blended Japanese practices (long-term employment, consensus decisions, slow promotion, non-specialised careers) with the American emphasis on individual responsibility.","difficulty":"hard","source":"HR MT · MBA placement"},
  {"id":"mgmt-hr-ob-322","question":"Consider these statements linking Herzberg and Maslow:\nI. Herzberg's hygiene factors broadly correspond to Maslow's lower-order needs.\nII. Herzberg's motivators broadly correspond to esteem and self-actualisation needs.\nIII. In Herzberg's view, the opposite of satisfaction is dissatisfaction.\nWhich are correct?","options":["I and II only","I, II and III","II and III only","I and III only"],"answer":0,"explanation":"Hygiene factors (pay, security, relations) map onto lower needs and motivators (achievement, recognition, growth) onto higher ones. Herzberg said the opposite of satisfaction is 'no satisfaction', not dissatisfaction.","difficulty":"hard","source":"HR MT · MBA placement"},
  {"id":"mgmt-hr-ob-323","question":"Some employees stay content even when they are somewhat under-rewarded compared with their peers, while others feel cheated unless they are over-rewarded. The concept that captures these differences is:","options":["Equity sensitivity, with 'benevolents' tolerating under-reward","Locus of control","Organisational commitment","Procedural justice"],"answer":0,"explanation":"Equity sensitivity classifies people as benevolents (comfortable when under-rewarded), equity sensitives, and entitleds (who prefer being over-rewarded). It refines Adams' theory, which assumes everyone wants exact equity.","difficulty":"very-hard","source":"HR MT · Consulting"},
  {"id":"mgmt-hr-ob-324","question":"A manager says: \"My people don't care about the extra bonus I announced. They know they can't reach the target with the tools they have.\" Which Vroom component should she fix first, and how?","options":["Valence, by offering a bigger bonus","Instrumentality, by putting the bonus formula in writing","Expectancy, by giving better tools, training or a realistic target","Valence, by letting employees choose the reward"],"answer":2,"explanation":"Employees doubt that effort will produce the performance, so expectancy is near zero; because force is multiplicative, a bigger or written bonus cannot help until expectancy is restored.","difficulty":"hard","source":"HR MT · MBA placement"},
  {"id":"mgmt-hr-ob-325","question":"Assertion (A): Linking a large bonus to a single easily measured metric, such as calls handled per hour, can lower overall performance in a customer-service team.\nReason (R): People tend to direct effort towards what is measured and rewarded and neglect unmeasured aspects such as resolution quality.","options":["Both A and R are true and R explains A","Both A and R are true but R does not explain A","A is true but R is false","A is false but R is true"],"answer":0,"explanation":"This is the 'folly of rewarding A while hoping for B': agents rush calls to raise the counted metric while quality falls. R gives the mechanism behind A.","difficulty":"hard","source":"HR MT · Consulting"},
  {"id":"mgmt-hr-ob-326","question":"Which statement about Maslow's theory is the most accurate reading of the idea of prepotency?","options":["Higher needs are stronger than lower needs from the start","A need that is substantially satisfied no longer motivates, and the next level becomes dominant","All five needs motivate equally at all times","Self-actualisation can be fully and permanently satisfied"],"answer":1,"explanation":"In Maslow's hierarchy a satisfied need stops being a motivator and the next higher need becomes prepotent. Self-actualisation is the one need that keeps growing as it is fed.","difficulty":"moderate","source":"HR MT · MBA placement"},
  {"id":"mgmt-hr-ob-327","question":"A newly appointed plant head is distrusted by her team, the turnaround task she faces is vague and unstructured, and she has little formal power to hire, fire or reward. According to Fiedler's contingency model, which leader is likely to perform better here?","options":["A high-LPC (relationship-motivated) leader","A low-LPC (task-motivated) leader","Either, since style does not matter in such situations","A leader who switches between styles"],"answer":1,"explanation":"Poor relations, an unstructured task and weak position power make the situation very unfavourable, where Fiedler found task-motivated (low-LPC) leaders more effective. Fiedler treated style as fixed, so switching styles is not part of his model.","difficulty":"hard","source":"HR MT · Consulting · MBA placement"},
  {"id":"mgmt-hr-ob-328","question":"A team leader has good relations with her team, but the task is unstructured and her position power is weak. Fiedler's model rates this as a moderately favourable situation. Which leader does it predict will do better?","options":["A low-LPC (task-motivated) leader","Neither: Fiedler makes no prediction for moderate situations","A high-LPC (relationship-motivated) leader","Whichever leader has more expert power"],"answer":2,"explanation":"Fiedler found that relationship-motivated (high-LPC) leaders do best in moderately favourable situations, while task-motivated leaders do best at both extremes.","difficulty":"very-hard","source":"HR MT · Consulting"},
  {"id":"mgmt-hr-ob-329","question":"A leader is asked to think of the co-worker she has least liked working with and describes that person as pleasant, friendly and helpful. In Fiedler's model she is:","options":["A high-LPC, relationship-motivated leader","A low-LPC, task-motivated leader","A leader with a 9,9 team-management style","A transactional leader"],"answer":0,"explanation":"Describing even the least-preferred co-worker favourably gives a high LPC score, which Fiedler read as relationship motivation. A harsh description signals a task-motivated, low-LPC leader.","difficulty":"moderate","source":"HR MT · MBA placement"},
  {"id":"mgmt-hr-ob-330","question":"Because Fiedler treated leadership style as relatively fixed, what did he recommend when a leader's style does not fit the situation?","options":["Train the leader to adopt the opposite style","Change the situation, for example by restructuring tasks or adjusting position power, or replace the leader","Let the group choose its own leader","Use participative decision making for all issues"],"answer":1,"explanation":"Fiedler's 'leader match' advice was to engineer the situation to fit the leader, or to move the leader, rather than try to change a stable style.","difficulty":"hard","source":"HR MT · MBA placement"},
  {"id":"mgmt-hr-ob-331","question":"Call-centre agents handle highly routine, monotonous calls and often face abusive customers. According to House's path–goal theory, which leader behaviour will most improve their satisfaction?","options":["Directive leadership","Achievement-oriented leadership","Participative leadership","Supportive leadership"],"answer":3,"explanation":"Path–goal theory says supportive leadership compensates for stressful, boring or frustrating tasks. Directive behaviour adds little when the task is already routine and clear.","difficulty":"hard","source":"HR MT · MBA placement"},
  {"id":"mgmt-hr-ob-332","question":"A manager gives highly experienced, skilled engineers detailed step-by-step instructions on routine work they already know well. According to path–goal theory, what is the likely effect?","options":["Higher satisfaction, because role ambiguity falls","No effect, because ability does not moderate leadership","Higher performance, because structure always helps","Lower satisfaction, because the directive behaviour is redundant"],"answer":3,"explanation":"Path–goal theory predicts directive leadership is seen as redundant, even controlling, by able, experienced people doing clear tasks, so satisfaction falls.","difficulty":"hard","source":"HR MT · Consulting"},
  {"id":"mgmt-hr-ob-333","question":"In a research lab, scientists are highly trained, find their work intrinsically satisfying and follow clear professional standards, so they rarely need the lab head's instructions. Kerr and Jermier would call these features:","options":["Substitutes for leadership","Leader–member exchange","Situational favourableness","Neutralisers of transformational leadership only"],"answer":0,"explanation":"Professional orientation, intrinsically satisfying tasks and formal standards are substitutes for leadership: they provide the guidance or motivation a leader would otherwise supply.","difficulty":"very-hard","source":"HR MT · Consulting"},
  {"id":"mgmt-hr-ob-334","question":"A manager trusts a few team members, gives them challenging assignments and extra time, and deals with the rest mostly through formal rules. Which theory describes this, and what does research generally find?","options":["Fiedler's model; the trusted members perform worse","Leader–member exchange; in-group members tend to have higher performance ratings and satisfaction","Path–goal theory; out-group members are more satisfied","Hersey–Blanchard; the trusted members are at the lowest readiness"],"answer":1,"explanation":"LMX theory describes high-quality (in-group) and low-quality (out-group) exchanges. In-group members typically get better ratings, more satisfaction and lower turnover intention.","difficulty":"hard","source":"HR MT · MBA placement"},
  {"id":"mgmt-hr-ob-335","question":"A department head sees her main job as removing obstacles for her team, developing each person and putting their needs ahead of her own status. Which style is this?","options":["Transactional leadership","Charismatic leadership","Servant leadership","Laissez-faire leadership"],"answer":2,"explanation":"Servant leadership, described by Greenleaf, puts serving and developing followers first. Laissez-faire also involves stepping back, but through abdication, not active service.","difficulty":"moderate","source":"HR MT · MBA placement"},
  {"id":"mgmt-hr-ob-336","question":"Arrange these leader behaviours on Tannenbaum and Schmidt's continuum, from most boss-centred to most subordinate-centred.\nP. Presents a tentative decision subject to change\nQ. Sells the decision\nR. Defines limits and asks the group to decide\nS. Presents the problem, gets suggestions, then decides","options":["Q, S, P, R","P, Q, S, R","Q, P, R, S","Q, P, S, R"],"answer":3,"explanation":"The continuum runs: tells, sells, presents ideas and invites questions, presents a tentative decision, presents the problem and gets suggestions, defines limits and asks the group to decide, and lets the group function within limits.","difficulty":"very-hard","source":"HR MT · MBA placement"},
  {"id":"mgmt-hr-ob-337","question":"The University of Michigan leadership studies compared employee-centred and production-centred supervisors. What did they generally conclude?","options":["Employee-centred supervisors were associated with higher productivity and satisfaction","Production-centred supervisors were associated with higher productivity and satisfaction","Neither style made any difference","The best supervisors were high on both styles"],"answer":0,"explanation":"The Michigan studies favoured employee-centred supervision. The 'high on both' idea comes from the Ohio State and Blake–Mouton work, where the dimensions were treated as independent.","difficulty":"moderate","source":"HR MT · MBA placement"},
  {"id":"mgmt-hr-ob-338","question":"Consider these statements about the Ohio State leadership studies:\nI. Initiating structure and consideration were treated as independent dimensions.\nII. A leader can be high on both dimensions at once.\nIII. Later research showed that high–high is always the most effective style in every situation.\nWhich are correct?","options":["I, II and III","I and II only","II and III only","I only"],"answer":1,"explanation":"The two dimensions were independent, so high–high is possible. But the evidence for high–high being universally best was mixed, which pushed researchers towards contingency theories.","difficulty":"hard","source":"HR MT · MBA placement"},
  {"id":"mgmt-hr-ob-339","question":"A management trainee is enthusiastic and eager to learn but does not yet have the skills for the task. Which Hersey–Blanchard style fits her readiness level?","options":["Delegating","Telling","Participating","Selling (coaching)"],"answer":3,"explanation":"Unable but willing is readiness R2, which calls for selling: high task direction to build skill plus high relationship support to keep her motivation. Telling suits people who are unable and unwilling or insecure.","difficulty":"hard","source":"HR MT · MBA placement"},
  {"id":"mgmt-hr-ob-340","question":"In Bass's full-range leadership model, which behaviour is generally found to be the least effective form of transactional leadership?","options":["Contingent reward","Active management by exception","Passive management by exception","Individualised consideration"],"answer":2,"explanation":"Passive management by exception, intervening only after problems become serious, is close to laissez-faire at the ineffective end. Contingent reward is the most effective transactional behaviour; individualised consideration is transformational.","difficulty":"hard","source":"HR MT · Consulting"},
  {"id":"mgmt-hr-ob-341","question":"A manager does just enough to meet output targets while keeping morale at a 'satisfactory' level, avoiding any push that might upset either side. Where does he sit on the Blake–Mouton grid?","options":["1,1 impoverished management","5,5 middle-of-the-road management","9,1 authority–compliance","1,9 country-club management"],"answer":1,"explanation":"5,5 balances moderate concern for production with moderate concern for people, settling for adequate performance. 1,1 shows minimal concern for both.","difficulty":"moderate","source":"HR MT · MBA placement"},
  {"id":"mgmt-hr-ob-342","question":"A manager wants approval for a new tool. Before meeting the director, she gets three other department heads to agree to back her request in the meeting. Which influence tactic is she using?","options":["Coalition","Ingratiation","Legitimating","Exchange"],"answer":0,"explanation":"Enlisting others' support to strengthen a request is a coalition tactic. Exchange would offer the heads something in return; legitimating relies on policy or authority.","difficulty":"hard","source":"HR MT · MBA placement"},
  {"id":"mgmt-hr-ob-343","question":"Research on influence tactics generally finds which of these to be among the most effective across situations?","options":["Pressure, legitimating and coalition","Ingratiation, exchange and pressure","Rational persuasion, inspirational appeals and consultation","Pressure and upward appeals"],"answer":2,"explanation":"Rational persuasion, inspirational appeals and consultation tend to produce commitment. Pressure and legitimating usually produce at best compliance and often resistance.","difficulty":"hard","source":"HR MT · Consulting"},
  {"id":"mgmt-hr-ob-344","question":"Which Big Five trait is most strongly linked with leader emergence, that is, being seen as a leader by a group?","options":["Agreeableness","Neuroticism","Openness to experience","Extraversion"],"answer":3,"explanation":"Meta-analyses find extraversion is the strongest Big Five correlate of leader emergence, because extraverts speak up and assert themselves. Conscientiousness is the best general predictor of job performance, a different question.","difficulty":"hard","source":"HR MT · MBA placement"},
  {"id":"mgmt-hr-ob-345","question":"A sales director sets extremely high standards, does much of the work herself to show how it should be done, and quickly takes over from anyone who lags. In the short run her highly skilled team delivers, but morale is falling. Which of Goleman's leadership styles is this?","options":["Coaching","Pacesetting","Authoritative (visionary)","Affiliative"],"answer":1,"explanation":"The pacesetting style sets and models very high standards. It can work briefly with a highly competent, motivated team but tends to damage climate if overused.","difficulty":"hard","source":"HR MT · Consulting"},
  {"id":"mgmt-hr-ob-346","question":"Which of Goleman's six leadership styles did his research associate with the most strongly positive effect on organisational climate?","options":["Coercive","Pacesetting","Democratic","Authoritative (visionary)"],"answer":3,"explanation":"Goleman found the authoritative style, which sets a clear vision and leaves people free to choose the means, had the most positive effect on climate. Coercive and pacesetting styles had negative effects overall.","difficulty":"very-hard","source":"HR MT · Consulting"},
  {"id":"mgmt-hr-ob-347","question":"When a company performs extremely well or extremely badly, observers tend to credit or blame the CEO, even when industry-wide factors explain most of the result. This tendency is known as:","options":["The romance of leadership","The halo effect in appraisal","The leniency error","Leader–member exchange"],"answer":0,"explanation":"The romance of leadership (Meindl) describes how people over-attribute organisational outcomes to leaders, especially when outcomes are extreme. It is an attribution bias, not a rating error.","difficulty":"hard","source":"HR MT · Consulting"},
  {"id":"mgmt-hr-ob-348","question":"Jim Collins described 'Level 5' leaders who took companies from good to great. What combination did they show?","options":["Charisma and a strong personal brand","Personal humility combined with intense professional will","High need for affiliation and low need for power","Directive control combined with frequent restructuring"],"answer":1,"explanation":"Collins's Level 5 leaders combined modesty about themselves with fierce resolve for the company's results, often in contrast to celebrity CEOs.","difficulty":"hard","source":"Consulting · MBA placement"},
  {"id":"mgmt-hr-ob-349","question":"In Robert Kelley's model of followership, a team member thinks independently and critically about decisions but is passive, cynical and rarely acts on her views. She is:","options":["An exemplary follower","A conformist follower","An alienated follower","A passive follower"],"answer":2,"explanation":"Kelley's alienated followers combine independent critical thinking with passive engagement. Exemplary followers are both critical and active; conformists are active but uncritical.","difficulty":"very-hard","source":"HR MT · Consulting"},
  {"id":"mgmt-hr-ob-350","question":"Match each transformational or transactional behaviour with an example.\nA. Contingent reward  B. Intellectual stimulation  C. Active management by exception  D. Inspirational motivation\n1. Monitors for errors and corrects them before they become problems\n2. Agrees targets and the bonus each will earn\n3. Paints a compelling picture of what the team can achieve\n4. Encourages people to question assumptions and try new approaches","options":["A-2, B-4, C-1, D-3","A-2, B-3, C-1, D-4","A-1, B-4, C-2, D-3","A-4, B-2, C-1, D-3"],"answer":0,"explanation":"Contingent reward trades rewards for agreed results, active management by exception watches for deviations, intellectual stimulation challenges assumptions and inspirational motivation communicates an appealing vision.","difficulty":"hard","source":"HR MT · MBA placement"},
  {"id":"mgmt-hr-ob-351","question":"Assertion (A): A charismatic leader can be harmful to an organisation even while followers remain highly committed.\nReason (R): Charismatic leaders may use their influence to pursue personal goals and discourage dissent, so followers stop questioning poor decisions.","options":["Both A and R are true and R explains A","Both A and R are true but R does not explain A","A is true but R is false","A is false but R is true"],"answer":0,"explanation":"Personalised charisma can produce blind loyalty and suppress the debate that would catch mistakes, so commitment and harm coexist. R explains A.","difficulty":"hard","source":"HR MT · Consulting"},
  {"id":"mgmt-hr-ob-352","question":"A manager uses the same highly directive style with every subordinate. Which of these theories explicitly says the right leader behaviour should differ from one follower to another depending on that follower's competence and commitment?","options":["Trait theory","Fiedler's contingency model","Hersey–Blanchard situational leadership","The Ohio State studies"],"answer":2,"explanation":"Hersey–Blanchard matches style to each follower's readiness. Fiedler's model also is contingent, but on the overall situation, and it treats the leader's own style as fixed.","difficulty":"moderate","source":"HR MT · MBA placement"},
  {"id":"mgmt-hr-ob-353","question":"John Kotter distinguished management, which copes with complexity, from leadership, which copes with change. Which pairing of activities matches his distinction?","options":["Management: setting direction, aligning people, motivating; Leadership: planning, budgeting, controlling","Management: motivating and inspiring; Leadership: organising and staffing","Management: planning and budgeting, organising and staffing, controlling; Leadership: setting direction, aligning people, motivating and inspiring","Management and leadership involve the same activities at different levels"],"answer":2,"explanation":"Kotter paired planning–budgeting with setting direction, organising–staffing with aligning people, and controlling–problem solving with motivating and inspiring. The first option simply swaps the two lists.","difficulty":"hard","source":"HR MT · Consulting"},
  {"id":"mgmt-hr-ob-354","question":"Executives from sales, production and finance read the same case about a struggling company. The sales executives mostly conclude the core problem is weak selling; production executives see a manufacturing problem. Which perceptual process does this illustrate?","options":["Selective perception","Projection","Contrast effect","Halo effect"],"answer":0,"explanation":"People notice and interpret information through the lens of their own background and interests, which is selective perception (the classic Dearborn and Simon finding). Projection would be attributing one's own feelings to others.","difficulty":"hard","source":"HR MT · Consulting · MBA placement"},
  {"id":"mgmt-hr-ob-355","question":"An interviewer meets three weak candidates in a row and then rates an average fourth candidate as 'excellent'. Which perceptual error is this?","options":["Halo effect","Contrast effect","Central tendency","Recency effect"],"answer":1,"explanation":"Judging someone relative to the people evaluated just before, rather than against the standard, is the contrast effect. Halo would come from one trait of the same candidate colouring the rest.","difficulty":"moderate","source":"HR MT · MBA placement"},
  {"id":"mgmt-hr-ob-356","question":"A manager who cuts corners on expense claims assumes that most of his team must be doing the same and audits them harshly. Which perceptual bias is this?","options":["Stereotyping","Fundamental attribution error","Projection","Selective perception"],"answer":2,"explanation":"Projection is attributing one's own traits or motives to others. Stereotyping judges someone by the group they belong to, which is not the basis here.","difficulty":"hard","source":"HR MT · MBA placement"},
  {"id":"mgmt-hr-ob-357","question":"Trainees are randomly assigned to two groups, but instructors are told one group has 'low potential'. That group's performance later falls below the other's, though the groups were equal at the start. Which effect is this?","options":["Pygmalion effect","Galatea effect","Halo effect","Golem effect"],"answer":3,"explanation":"Low expectations held by a leader that drag performance down is the Golem effect, the negative counterpart of the Pygmalion effect. The Galatea effect concerns a person's expectations of herself.","difficulty":"very-hard","source":"HR MT · Consulting"},
  {"id":"mgmt-hr-ob-358","question":"When an employee misses a deadline, her manager blames her carelessness, while she explains the delay by pointing to late inputs from another team. This pattern is best described as:","options":["The actor–observer bias","The halo effect","Projection","The contrast effect"],"answer":0,"explanation":"Observers tend to explain others' behaviour by internal causes, while actors explain their own behaviour by situational causes. The fundamental attribution error describes only the observer's half of this pattern.","difficulty":"hard","source":"HR MT · MBA placement"},
  {"id":"mgmt-hr-ob-359","question":"Which Big Five trait is most consistently linked with creativity and with doing well in training programmes?","options":["Agreeableness","Openness to experience","Extraversion","Emotional stability"],"answer":1,"explanation":"Openness to experience, being curious, imaginative and receptive to new ideas, predicts creativity and training proficiency. Conscientiousness is the broadest predictor of overall job performance.","difficulty":"hard","source":"HR MT · MBA placement"},
  {"id":"mgmt-hr-ob-360","question":"Research suggests that people high in Machiavellianism tend to outperform others in which kind of situation?","options":["Highly structured jobs with tight rules and remote contact","Routine jobs with clear procedures","Face-to-face dealings where rules are loose and others are emotionally distracted","Jobs that reward strict honesty and transparency"],"answer":2,"explanation":"High Machs do best when interacting face to face, when there are few rules leaving room to improvise, and when emotional involvement distracts others. In tightly structured settings they have little room to manoeuvre.","difficulty":"very-hard","source":"HR MT · Consulting"},
  {"id":"mgmt-hr-ob-361","question":"A consultant is quick to read each client's expectations and adapts her manner to suit very different settings, from a boardroom to a factory floor. Which personality trait does this reflect, and what does research link it to?","options":["High self-monitoring; more frequent promotions and success in boundary-spanning roles","Low self-monitoring; stronger consistency and higher trust","High neuroticism; higher stress","External locus of control; lower ambition"],"answer":0,"explanation":"High self-monitors adjust their behaviour to situational cues. Studies link the trait to more promotions and to success in roles that span groups, though such people may seem less consistent.","difficulty":"hard","source":"HR MT · Consulting"},
  {"id":"mgmt-hr-ob-362","question":"A Type A manager is impatient, competitive and always racing against the clock. Which statement about Type A behaviour in organisations is most accurate?","options":["Type A people are generally better at complex decisions that need careful deliberation","Type A people usually make the best senior executives","Type A people often score well on speed and quantity but may sacrifice quality on complex tasks","Type A behaviour has no link with stress"],"answer":2,"explanation":"Type A individuals value speed and quantity and are prone to stress; they may rush complex judgements. Studies have found that senior executives are often Type B, being more patient with complex problems.","difficulty":"hard","source":"HR MT · MBA placement"},
  {"id":"mgmt-hr-ob-363","question":"In a classic experiment, people who were paid very little to tell others that a boring task was interesting later rated the task as more enjoyable than people who were paid a lot to say the same thing. Which theory explains this?","options":["Equity theory","Reinforcement theory","Expectancy theory","Cognitive dissonance theory"],"answer":3,"explanation":"Those paid little had no external justification for saying what they did not believe, so they reduced dissonance by changing their attitude. A large payment justified the lie, so attitudes did not need to change.","difficulty":"very-hard","source":"HR MT · Consulting"},
  {"id":"mgmt-hr-ob-364","question":"Match each statement with the attitude component it represents.\nA. \"My manager allocates shifts unfairly.\"  B. \"I really dislike working under her.\"  C. \"I have started applying for jobs elsewhere.\"\n1. Affective  2. Behavioural  3. Cognitive","options":["A-1, B-3, C-2","A-3, B-1, C-2","A-3, B-2, C-1","A-2, B-1, C-3"],"answer":1,"explanation":"A belief or evaluation is cognitive, a feeling is affective, and an intention to act is behavioural. The three usually move together but are distinct.","difficulty":"moderate","source":"HR MT · MBA placement"},
  {"id":"mgmt-hr-ob-365","question":"In the exit–voice–loyalty–neglect framework of responses to job dissatisfaction, which response is passive but constructive?","options":["Loyalty: waiting patiently and trusting the organisation to improve","Voice: suggesting improvements to the manager","Neglect: arriving late and putting in less effort","Exit: looking for another job"],"answer":0,"explanation":"Voice is active and constructive, loyalty passive and constructive, exit active and destructive, neglect passive and destructive.","difficulty":"hard","source":"HR MT · MBA placement"},
  {"id":"mgmt-hr-ob-366","question":"An employee stays with her company mainly because she would lose a large pension benefit by leaving and sees no comparable jobs available. Which form of organisational commitment (Meyer and Allen) is this?","options":["Affective commitment","Normative commitment","Continuance commitment","Calculative trust"],"answer":2,"explanation":"Continuance commitment rests on the perceived cost of leaving. Affective commitment is emotional attachment, and normative commitment is a felt moral obligation to stay.","difficulty":"hard","source":"HR MT · MBA placement"},
  {"id":"mgmt-hr-ob-367","question":"A manager whose MBA was fully sponsored by her company stays on even though she has a better offer, because she feels it would be wrong to leave after what the firm did for her. Which form of commitment is this?","options":["Continuance commitment","Normative commitment","Affective commitment","Instrumental commitment"],"answer":1,"explanation":"Staying out of a felt moral obligation is normative commitment. Her better offer shows that the cost of leaving is low, so continuance commitment is not the main reason.","difficulty":"very-hard","source":"HR MT · Consulting"},
  {"id":"mgmt-hr-ob-368","question":"A flight attendant smiles warmly at a rude passenger while privately feeling irritated, without trying to change how she actually feels. This is called ______, and research links it more strongly to ______.","options":["deep acting; burnout","emotional contagion; job satisfaction","surface acting; burnout and emotional exhaustion","deep acting; customer complaints"],"answer":2,"explanation":"Displaying required emotions without feeling them is surface acting; the gap between felt and displayed emotion (emotional dissonance) is linked to exhaustion. Deep acting tries to actually feel the required emotion and is less draining.","difficulty":"hard","source":"HR MT · MBA placement"},
  {"id":"mgmt-hr-ob-369","question":"Which theory proposes that daily work events, such as a rude email or praise from a client, trigger emotional reactions that in turn shape job satisfaction and performance?","options":["Affective events theory","Two-factor theory","Social learning theory","Equity theory"],"answer":0,"explanation":"Affective events theory (Weiss and Cropanzano) links work events to emotional reactions and then to attitudes and behaviour, with personality and mood moderating the reactions.","difficulty":"hard","source":"HR MT · MBA placement"},
  {"id":"mgmt-hr-ob-370","question":"A trainee watches a senior negotiator close deals, remembers her techniques, practises them in role-plays and sees that the senior is praised for the results. Bandura's social learning theory lists four processes in this kind of learning. Which is NOT one of them?","options":["Attention","Retention","Extinction","Motor reproduction"],"answer":2,"explanation":"Bandura's modelling processes are attention, retention, motor reproduction and reinforcement. Extinction is a reinforcement-theory term for a behaviour dying out when it is no longer rewarded.","difficulty":"moderate","source":"HR MT · MBA placement"},
  {"id":"mgmt-hr-ob-371","question":"A supervisor first praises a new hire for any attempt at a sales pitch, then only for pitches that include the product's key benefits, and finally only for pitches that also close the sale. What is this technique called?","options":["Negative reinforcement","Shaping","Modelling","Extinction"],"answer":1,"explanation":"Reinforcing closer and closer approximations of the target behaviour is shaping. Modelling would involve learning by observing someone else.","difficulty":"moderate","source":"HR MT · MBA placement"},
  {"id":"mgmt-hr-ob-372","question":"In Rokeach's value survey, which of these is a terminal value rather than an instrumental value?","options":["Being ambitious","Being honest","Being responsible","A comfortable life"],"answer":3,"explanation":"Terminal values are desirable end states, such as a comfortable life or family security. Ambitious, honest and responsible describe preferred modes of behaviour, so they are instrumental values.","difficulty":"hard","source":"HR MT · MBA placement"},
  {"id":"mgmt-hr-ob-373","question":"According to Karasek's job demand–control model, which job is expected to produce the most psychological strain?","options":["High demands with high decision latitude","Low demands with high decision latitude","Low demands with low decision latitude","High demands with low decision latitude"],"answer":3,"explanation":"High-strain jobs combine heavy demands with little control, as in many assembly-line or call-centre roles. High demands with high control are 'active' jobs, which can be stimulating rather than harmful.","difficulty":"very-hard","source":"HR MT · Consulting"},
  {"id":"mgmt-hr-ob-374","question":"Consider these statements about work stress:\nI. Challenge stressors, such as a heavy but meaningful workload, tend to relate to higher performance than hindrance stressors such as red tape.\nII. The Yerkes–Dodson pattern suggests performance rises with arousal up to a point and then falls.\nIII. Any level of stress always lowers performance.\nWhich are correct?","options":["I and II only","II only","I, II and III","II and III only"],"answer":0,"explanation":"Challenge stressors can energise people, while hindrance stressors mainly drain them, and the inverted-U shows a moderate level of arousal is best. III contradicts both points.","difficulty":"hard","source":"HR MT · MBA placement"},
  {"id":"mgmt-hr-ob-375","question":"A nurse feels drained at the end of every shift, has begun treating patients as cases rather than people, and feels she accomplishes little. In Maslach's model, these are the three dimensions of:","options":["Emotional labour","Role ambiguity","Burnout","Learned helplessness"],"answer":2,"explanation":"Maslach describes burnout as emotional exhaustion, depersonalisation (cynicism) and reduced personal accomplishment. Emotional labour can contribute to burnout but is not the same thing.","difficulty":"hard","source":"HR MT · MBA placement"},
  {"id":"mgmt-hr-ob-376","question":"A career counsellor matches a candidate who likes analysing data and solving abstract problems to a research-analyst role. In Holland's RIASEC model, this candidate's dominant type is:","options":["Realistic","Social","Enterprising","Investigative"],"answer":3,"explanation":"Investigative types prefer observing, analysing and solving problems. Enterprising types prefer persuading and leading; realistic types prefer working with tools and machines.","difficulty":"hard","source":"HR MT · MBA placement"},
  {"id":"mgmt-hr-ob-377","question":"An appraiser notices that one sales rep is often late to meetings and then rates her low on product knowledge, customer handling and teamwork, without any evidence on those dimensions. This is the:","options":["Leniency error","Horns effect","Contrast effect","Recency effect"],"answer":1,"explanation":"Letting one negative trait drag down ratings on unrelated dimensions is the horns effect, the negative mirror of the halo effect.","difficulty":"moderate","source":"HR MT · MBA placement"},
  {"id":"mgmt-hr-ob-378","question":"Assertion (A): Personality tests such as the MBTI are not recommended as the main basis for hiring decisions.\nReason (R): The MBTI sorts people into types on forced either–or dimensions and shows weak links with job performance.","options":["Both A and R are true and R explains A","Both A and R are true but R does not explain A","A is true but R is false","A is false but R is true"],"answer":0,"explanation":"The MBTI forces continuous traits into categories and its type has little predictive validity for performance, so it is better used for self-awareness and team discussion than for selection.","difficulty":"hard","source":"HR MT · Consulting"},
  {"id":"mgmt-hr-ob-379","question":"After three months of a hiring freeze, a team's mood falls; one gloomy senior keeps complaining in the open office and soon most of the team sounds gloomy too. Which concept explains how the mood spread?","options":["Groupthink","Emotional contagion","Social loafing","Cognitive dissonance"],"answer":1,"explanation":"Emotional contagion is the process by which people 'catch' others' emotions through mimicry and interaction. Groupthink concerns pressure for agreement in decisions, not shared mood.","difficulty":"moderate","source":"HR MT · MBA placement"},
  {"id":"mgmt-hr-ob-380","question":"Consider these statements about core self-evaluation (CSE):\nI. CSE combines self-esteem, generalised self-efficacy, locus of control and emotional stability.\nII. People with positive CSE tend to report higher job satisfaction.\nIII. People with negative CSE tend to set more ambitious goals.\nWhich are correct?","options":["I and III only","I, II and III","II only","I and II only"],"answer":3,"explanation":"CSE bundles self-esteem, self-efficacy, internal locus of control and emotional stability. Positive CSE goes with higher satisfaction and more ambitious goals, so III reverses the finding.","difficulty":"very-hard","source":"HR MT · Consulting"},
  {"id":"mgmt-hr-ob-381","question":"A project team with a 12-week deadline drifts with little progress for about six weeks, then suddenly drops its old approach, adopts a new plan and works intensely until the end. Which model of group development describes this?","options":["Tuckman's five-stage model","Gersick's punctuated-equilibrium model","Lewin's three-step model","The Johari window"],"answer":1,"explanation":"Gersick found that temporary groups with deadlines show inertia until about the midpoint, then a burst of change, then a second phase of inertia and a final push. Tuckman's stages describe a steady sequence instead.","difficulty":"very-hard","source":"HR MT · Consulting · MBA placement"},
  {"id":"mgmt-hr-ob-382","question":"A work group is very close-knit, but its informal norm is to do the bare minimum. Compared with other combinations of cohesiveness and performance norms, what productivity would you expect?","options":["The highest, because cohesion always lifts output","Moderate, because cohesion offsets the low norm","Low, but higher than a loose group with low norms","The lowest, because a cohesive group enforces its low norm strongly"],"answer":3,"explanation":"Cohesion magnifies whatever norm the group holds. High cohesion with high norms gives the highest output; high cohesion with low norms gives the lowest, since members police one another into restricting effort.","difficulty":"very-hard","source":"HR MT · Consulting"},
  {"id":"mgmt-hr-ob-383","question":"Before a meeting, each member of an investment committee privately favours a moderately risky investment. After discussion, the committee chooses a far riskier option than any member preferred initially. This is called:","options":["Groupthink","Group shift (polarisation)","Social loafing","Escalation of commitment"],"answer":1,"explanation":"Group shift is the tendency for a group decision to be more extreme than members' initial average, in the direction they already leaned. Groupthink is about suppressing dissent to keep harmony.","difficulty":"hard","source":"HR MT · MBA placement"},
  {"id":"mgmt-hr-ob-384","question":"In a product team, one member generates highly original but sometimes impractical ideas, another coolly weighs all options and judges them accurately, and a third polishes the final output and catches every error before release. In Belbin's terms, these three are:","options":["Shaper, Coordinator, Implementer","Resource investigator, Specialist, Team worker","Plant, Monitor evaluator, Completer finisher","Plant, Coordinator, Implementer"],"answer":2,"explanation":"The Plant is the creative idea generator, the Monitor evaluator is the sober, strategic judge, and the Completer finisher searches for errors and delivers on time.","difficulty":"hard","source":"HR MT · Consulting"},
  {"id":"mgmt-hr-ob-385","question":"A team member is outgoing, has a wide network outside the company, and keeps bringing back contacts and ideas from other firms, though she loses interest once the initial excitement fades. Which Belbin role fits her?","options":["Resource investigator","Plant","Shaper","Team worker"],"answer":0,"explanation":"The Resource investigator explores outside opportunities and builds contacts, but may lose enthusiasm quickly. The Plant generates ideas from within rather than by networking.","difficulty":"hard","source":"HR MT · Consulting"},
  {"id":"mgmt-hr-ob-386","question":"Cyclists ride faster when racing alongside others, and skilled typists type faster when watched, but trainees solving unfamiliar complex problems do worse when observed. Which concept explains both patterns?","options":["Social loafing","Groupthink","Social facilitation","Conformity"],"answer":2,"explanation":"Social facilitation: the presence of others improves performance on simple or well-learned tasks but hurts it on complex or new ones, because arousal strengthens dominant responses.","difficulty":"hard","source":"HR MT · MBA placement"},
  {"id":"mgmt-hr-ob-387","question":"Alone, each of three workers can pull a load of 60 kg, 65 kg and 64 kg. Pulling together, the three manage only 160 kg. What is the process loss as a percentage of their potential productivity?","options":["About 15.3%","About 18.1%","About 84.7%","29%"],"answer":0,"explanation":"Potential = 60 + 65 + 64 = 189 kg, so the loss is 29 kg and 29 / 189 ≈ 15.3%. 18.1% divides by the actual 160 kg, and 84.7% is the share of potential achieved, not the loss.","difficulty":"hard","source":"HR analyst · MBA placement"},
  {"id":"mgmt-hr-ob-388","question":"A company announces plant closures and layoffs to 300 employees through a short, formally worded email. According to media-richness theory, why is this a poor choice?","options":["Email is too rich a channel for a routine message","A message that is non-routine, emotional and ambiguous needs a rich channel such as face-to-face meetings","Email cannot be stored or forwarded","Lean channels are always better for large audiences"],"answer":1,"explanation":"Media-richness theory matches rich channels (face to face, allowing immediate feedback and multiple cues) with non-routine, ambiguous messages. Email is lean and suits routine, clear messages.","difficulty":"hard","source":"HR MT · MBA placement"},
  {"id":"mgmt-hr-ob-389","question":"Which statement about small-group communication networks is supported by research?","options":["The chain network gives the highest member satisfaction","The wheel network is the best for complex problems","The all-channel network is fastest for simple tasks and produces a clear leader","The wheel is fast and accurate for simple tasks and produces a clear leader, but member satisfaction is low"],"answer":3,"explanation":"Centralised networks like the wheel route information through one person, which is efficient for simple tasks and makes the hub the leader. All-channel networks suit complex problems and give the highest satisfaction.","difficulty":"very-hard","source":"HR MT · Consulting"},
  {"id":"mgmt-hr-ob-390","question":"A project lead reports only the good parts of a delayed project's status to her director because she knows the director dislikes bad news. Which communication barrier is this?","options":["Selective perception","Information overload","Filtering","Semantic noise"],"answer":2,"explanation":"Filtering is the sender deliberately manipulating information so it looks more favourable to the receiver. Selective perception happens on the receiver's side.","difficulty":"moderate","source":"HR MT · MBA placement"},
  {"id":"mgmt-hr-ob-391","question":"Arrange the stages of Pondy's model of conflict in the correct order.\nP. Felt conflict  Q. Latent conflict  R. Manifest conflict  S. Perceived conflict  T. Conflict aftermath","options":["Q, S, P, R, T","Q, P, S, R, T","S, Q, P, R, T","Q, S, R, P, T"],"answer":0,"explanation":"Pondy's sequence runs from latent conditions, to perceiving the conflict, to feeling it emotionally, to overt (manifest) behaviour, and finally the aftermath that shapes the next episode.","difficulty":"hard","source":"HR MT · MBA placement"},
  {"id":"mgmt-hr-ob-392","question":"Which statement about types of conflict in teams is most consistent with research?","options":["Relationship conflict is usually functional because it surfaces hidden tensions","Low to moderate task conflict can improve decisions, while relationship conflict is almost always dysfunctional","Process conflict is always beneficial at any level","All conflict reduces team performance"],"answer":1,"explanation":"Debate about the content of work, at low to moderate levels, can raise decision quality; personal friction tends to raise hostility and lower performance. High process conflict over who does what usually hurts.","difficulty":"hard","source":"HR MT · Consulting"},
  {"id":"mgmt-hr-ob-393","question":"A manager deliberately appoints a sharp critic to every planning committee to stir debate, because he believes a group that is too harmonious becomes stagnant. Which view of conflict guides him?","options":["Traditional view","Human relations view","Interactionist view","Unitarist view"],"answer":2,"explanation":"The interactionist view holds that some conflict is necessary for a group to stay creative and self-critical, so managers may even stimulate it. The traditional view sees all conflict as harmful.","difficulty":"hard","source":"HR MT · MBA placement"},
  {"id":"mgmt-hr-ob-394","question":"A seller lists a used machine at ₹8 lakh. The buyer immediately accepts the first price. The seller now feels she could have got more, and the buyer worries he overpaid. This feeling is known as:","options":["The winner's curse","The anchoring effect","Escalation of commitment","The endowment effect"],"answer":0,"explanation":"The winner's curse is the post-deal regret both sides feel when an offer is accepted too readily, suggesting it was off-target. Anchoring is the pull of a first number on later offers.","difficulty":"hard","source":"HR MT · MBA placement"},
  {"id":"mgmt-hr-ob-395","question":"An analyst stays visibly late at the office whenever senior partners are around and mentions how much personal time she gives up, so that she will be seen as dedicated. Which impression-management tactic is this?","options":["Ingratiation","Self-promotion","Supplication","Exemplification"],"answer":3,"explanation":"Exemplification means going beyond the call of duty, visibly, to be seen as dedicated. Self-promotion highlights one's own competence and achievements; ingratiation flatters others to be liked.","difficulty":"very-hard","source":"HR MT · Consulting"},
  {"id":"mgmt-hr-ob-396","question":"Which of these would NOT help a top team guard against groupthink?","options":["Appointing a member to play devil's advocate","Inviting outside experts to challenge the plan","The leader stating her preferred option at the start of the discussion","Holding a 'second-chance' meeting before finalising the decision"],"answer":2,"explanation":"A leader who announces her preference early signals the 'right' answer and silences dissent, which feeds groupthink. The other three are classic remedies that bring in critical views.","difficulty":"hard","source":"HR MT · MBA placement"},
  {"id":"mgmt-hr-ob-397","question":"In Lencioni's model of the five dysfunctions of a team, which dysfunction sits at the base of the pyramid and gives rise to the others?","options":["Fear of conflict","Absence of trust","Lack of commitment","Inattention to results"],"answer":1,"explanation":"Without trust, members won't show vulnerability, which leads to fear of conflict, lack of commitment, avoidance of accountability and finally inattention to results.","difficulty":"hard","source":"HR MT · Consulting"},
  {"id":"mgmt-hr-ob-398","question":"A sales team's bonus is shared equally, and some members coast on others' effort. Which change is most likely to reduce this social loafing while keeping the team incentive?","options":["Making each member's contribution identifiable and evaluated","Making the team bigger","Paying the bonus only to the team leader","Removing all individual targets"],"answer":0,"explanation":"Social loafing grows when individual effort is hidden in the group total. Making contributions visible and individually evaluated, while keeping a team element, reduces free-riding; bigger teams make it worse.","difficulty":"moderate","source":"HR MT · MBA placement"},
  {"id":"mgmt-hr-ob-399","question":"In Asch's line-judgement experiments, many participants gave a clearly wrong answer when all the other group members (confederates) gave it first. What did the studies also find?","options":["Conformity rose steadily without limit as the group grew","Conformity was the same whether answers were given publicly or privately","Nobody ever conformed in the first trial","Conformity fell sharply when even one other member gave the correct answer"],"answer":3,"explanation":"Asch found that a single dissenting ally greatly reduced conformity, and that the effect levelled off after a group of three or four. Private responses also reduced conformity.","difficulty":"very-hard","source":"HR MT · Consulting"},
  {"id":"mgmt-hr-ob-400","question":"Match each type of role conflict with its example.\nA. Intra-sender  B. Inter-sender  C. Inter-role  D. Person–role\n1. Her boss and the client give incompatible instructions\n2. A late board meeting clashes with collecting her child from school\n3. Her boss asks her to cut costs by 20% and also improve quality, with no new resources\n4. She is asked to push a product she believes is harmful to buyers","options":["A-1, B-3, C-2, D-4","A-3, B-1, C-4, D-2","A-3, B-1, C-2, D-4","A-3, B-2, C-1, D-4"],"answer":2,"explanation":"Incompatible demands from one sender are intra-sender conflict; from two senders, inter-sender; between two roles a person holds (manager and parent), inter-role; and between the role and her own values, person–role.","difficulty":"very-hard","source":"HR MT · Consulting"},
  {"id":"mgmt-hr-ob-401","question":"A strategy team assigns one subgroup to build the case for the proposed acquisition and another to develop a full alternative plan built on opposite assumptions; the two then debate before management decides. This technique is:","options":["Devil's advocacy","Nominal group technique","Delphi technique","Dialectical inquiry"],"answer":3,"explanation":"Dialectical inquiry sets a plan against a counter-plan built on opposing assumptions. Devil's advocacy only critiques the plan, without proposing a fully developed alternative.","difficulty":"very-hard","source":"Consulting · MBA placement"},
  {"id":"mgmt-hr-ob-402","question":"Staff from design, engineering, procurement and marketing work together for a year to launch a new appliance, with each member also keeping a home department. This is best described as a:","options":["Cross-functional team","Self-managed work team","Problem-solving (quality circle) team","Command group"],"answer":0,"explanation":"A cross-functional team brings people from different functions at about the same level together for a task. A quality circle is a small group from one area meeting regularly to solve work problems.","difficulty":"moderate","source":"HR MT · MBA placement"},
  {"id":"mgmt-hr-ob-403","question":"Consider these statements about informal groups at work:\nI. They can transmit information faster than formal channels.\nII. They may develop norms that conflict with management goals.\nIII. Managers can and should eliminate them for efficiency.\nWhich are correct?","options":["I, II and III","I only","I and II only","II and III only"],"answer":2,"explanation":"Informal groups spread information quickly and set their own norms, which may help or hinder management. They arise naturally and cannot be abolished; wise managers work with them.","difficulty":"moderate","source":"HR MT · MBA placement"},
  {"id":"mgmt-hr-ob-404","question":"Assertion (A): Adding more members to a problem-solving team always improves the quality of its decisions.\nReason (R): Larger groups bring more information and perspectives.","options":["Both A and R are true and R explains A","Both A and R are true but R does not explain A","A is true but R is false","A is false but R is true"],"answer":3,"explanation":"Larger groups do bring more inputs, but they also raise coordination costs, social loafing and pressure to conform, so quality does not keep rising. R is true while the word 'always' makes A false.","difficulty":"hard","source":"HR MT · MBA placement"},
  {"id":"mgmt-hr-ob-405","question":"Two teams compete for the same shared lab, each convinced the other wastes slots. Which approach to inter-group conflict reduces hostility most durably, according to classic research such as Sherif's camp studies?","options":["Increasing contact between the groups without any shared purpose","Setting a superordinate goal that neither team can achieve without the other","Letting the more powerful team win the dispute","Separating the teams completely"],"answer":1,"explanation":"Sherif found that mere contact often inflamed hostility, while superordinate goals requiring cooperation reduced it. Forcing a win or separation leaves the underlying conflict in place.","difficulty":"hard","source":"HR MT · Consulting"},
  {"id":"mgmt-hr-ob-406","question":"Two parties negotiate over price and delivery date. The buyer cares a lot about early delivery but little about a ₹50,000 price difference; the seller cares a lot about price and can deliver early at little cost. Which outcome reflects integrative bargaining?","options":["They split the price difference down the middle and keep the original delivery date","The seller gets the higher price and the buyer gets early delivery","The buyer gets both the lower price and early delivery","They postpone the decision to a later meeting"],"answer":1,"explanation":"Integrative bargaining (logrolling) trades issues the parties value differently, so each gets what matters more to it and the joint gain rises. Splitting the difference is a distributive compromise.","difficulty":"hard","source":"HR MT · Consulting"},
  {"id":"mgmt-hr-ob-407","question":"A firm's website and induction deck say 'we value work–life balance', yet every recent promotion went to people known for answering emails at midnight, and staff quietly assume that long hours are what really counts. In Schein's model, the belief about long hours belongs to which level?","options":["Artifacts","Espoused values","Basic underlying assumptions","Formal policies"],"answer":2,"explanation":"Espoused values are what the firm says it values; basic underlying assumptions are the taken-for-granted beliefs that actually drive behaviour. When the two diverge, behaviour follows the assumptions.","difficulty":"very-hard","source":"HR MT · Consulting · MBA placement"},
  {"id":"mgmt-hr-ob-408","question":"Consider these statements about strong organisational cultures:\nI. They can reduce the need for formal rules because norms guide behaviour.\nII. They can become a barrier when the environment changes quickly.\nIII. They make mergers with firms of a different culture easier.\nWhich are correct?","options":["I and II only","I, II and III","II and III only","I only"],"answer":0,"explanation":"Strong cultures act as an informal control system but can make a firm rigid when conditions shift. They usually make cross-cultural mergers harder, not easier, because each side holds its values firmly.","difficulty":"hard","source":"HR MT · Consulting"},
  {"id":"mgmt-hr-ob-409","question":"An oil-exploration company makes huge, risky bets whose results are known only years later, and its culture values careful deliberation and long-term thinking. In Deal and Kennedy's typology, this is a:","options":["Tough-guy, macho culture","Work-hard/play-hard culture","Process culture","Bet-your-company culture"],"answer":3,"explanation":"Deal and Kennedy classify cultures by risk and speed of feedback. High risk with slow feedback is the bet-your-company culture; high risk with fast feedback is the tough-guy culture.","difficulty":"very-hard","source":"Consulting · MBA placement"},
  {"id":"mgmt-hr-ob-410","question":"A company's culture is externally focused and control-oriented: it is obsessed with beating competitors, hitting market-share targets and rewarding winners. In the competing values framework, this is a:","options":["Clan culture","Hierarchy culture","Market culture","Adhocracy culture"],"answer":2,"explanation":"The market culture combines an external focus with stability and control, emphasising results and competitiveness. A hierarchy culture is internally focused and control-oriented.","difficulty":"hard","source":"HR MT · Consulting"},
  {"id":"mgmt-hr-ob-411","question":"In Charles Handy's classification of organisational cultures, a bureaucracy run by roles, rules and procedures, with functional departments as its pillars, is symbolised by:","options":["A web","A Greek temple","A net","A cluster"],"answer":1,"explanation":"Handy pictured the role culture as a Greek temple whose pillars are functions. The web is the power culture, the net the task culture and the cluster the person culture.","difficulty":"hard","source":"HR MT · MBA placement"},
  {"id":"mgmt-hr-ob-412","question":"In her first month, a new hire realises that the role differs from what she was told at interview and that her expectations about the team and the work were unrealistic. Which stage of socialisation is she in?","options":["Pre-arrival","Metamorphosis","Encounter","Anticipatory exit"],"answer":2,"explanation":"In the encounter stage, the newcomer sees what the organisation is really like and confronts the gap with her expectations. Metamorphosis comes later, when she adjusts and internalises the norms.","difficulty":"hard","source":"HR MT · MBA placement"},
  {"id":"mgmt-hr-ob-413","question":"An army-style induction strips new recruits of their previous identities, with uniform haircuts and no personal belongings, before rebuilding them in the organisation's mould. Which socialisation tactic is this?","options":["Investiture","Divestiture","Serial","Random"],"answer":1,"explanation":"Divestiture removes or suppresses a newcomer's existing identity; investiture affirms and builds on who the newcomer already is. Serial and random concern whether experienced role models guide newcomers.","difficulty":"very-hard","source":"HR MT · Consulting"},
  {"id":"mgmt-hr-ob-414","question":"In a country's business culture, men and women are both expected to be modest and caring, quality of life matters more than winning, and sympathy goes to the underdog. On Hofstede's dimensions, this is a culture low in:","options":["Masculinity","Power distance","Uncertainty avoidance","Long-term orientation"],"answer":0,"explanation":"Hofstede's masculinity dimension contrasts competitive, achievement-driven cultures with 'feminine' cultures that value caring and quality of life and have less sharply separated gender roles.","difficulty":"hard","source":"HR MT · Consulting"},
  {"id":"mgmt-hr-ob-415","question":"A manager from one culture is shocked that a close friend in another country expected her to overlook a contract clause for him 'because we are friends'. In Trompenaars' terms, the friend's culture leans towards:","options":["Universalism","Individualism","Achievement","Particularism"],"answer":3,"explanation":"Particularist cultures let relationships and circumstances shape how rules apply; universalist cultures apply the same rules to everyone regardless of relationship.","difficulty":"very-hard","source":"HR MT · Consulting"},
  {"id":"mgmt-hr-ob-416","question":"A negotiator from a culture where messages are explicit and contracts spell everything out is frustrated that his counterparts rely on unstated cues, relationships and tone, and treat the written contract as a loose guide. Using Edward Hall's framework, his counterparts come from a:","options":["Low-context culture","High-context culture","Polychronic, low-context culture","Universalist culture"],"answer":1,"explanation":"High-context cultures carry much of the meaning in context, relationships and non-verbal cues; low-context cultures put meaning in explicit words and written terms.","difficulty":"hard","source":"HR MT · Consulting"},
  {"id":"mgmt-hr-ob-417","question":"A plant is moving to a new shift system that will cost unionised workers most of their overtime earnings. The union is strong enough to block the change. According to Kotter and Schlesinger, which approach to resistance is most appropriate here?","options":["Education and communication","Facilitation and support","Coercion","Negotiation and agreement"],"answer":3,"explanation":"When a group will clearly lose out and has the power to resist, Kotter and Schlesinger recommend negotiation and agreement, such as compensation. Education helps only when resistance comes from misinformation.","difficulty":"very-hard","source":"HR MT · Consulting"},
  {"id":"mgmt-hr-ob-418","question":"Office staff support a move to new accounting software in principle, but resist because they are anxious they won't be able to learn it. Which Kotter–Schlesinger approach fits best?","options":["Facilitation and support, such as training and time to adjust","Coercion","Manipulation and co-optation","Negotiation and agreement"],"answer":0,"explanation":"When people resist because of adjustment problems and anxiety, facilitation and support (training, coaching, time off) address the cause. Negotiation fits groups that stand to lose something specific.","difficulty":"hard","source":"HR MT · MBA placement"},
  {"id":"mgmt-hr-ob-419","question":"A company celebrates a successful pilot of its new sales process by disbanding the change team and moving on, and within a year most branches have slipped back to old habits. According to Kotter, which common error did it make?","options":["Not creating a sense of urgency","Declaring victory too soon","Under-communicating the vision","Not forming a guiding coalition"],"answer":1,"explanation":"Kotter warns that celebrating early wins is good, but declaring the change complete before it is anchored in the culture lets old ways return.","difficulty":"hard","source":"HR MT · Consulting"},
  {"id":"mgmt-hr-ob-420","question":"Arrange the four phases of the appreciative inquiry '4-D' cycle in order.\nP. Design  Q. Discovery  R. Destiny  S. Dream","options":["Q, S, R, P","S, Q, P, R","Q, P, S, R","Q, S, P, R"],"answer":3,"explanation":"Appreciative inquiry first discovers what works well, then dreams about what could be, designs how to get there and finally delivers in the destiny (or delivery) phase.","difficulty":"hard","source":"HR MT · Consulting"},
  {"id":"mgmt-hr-ob-421","question":"A consultant sits in on a management team's meetings, observes how members communicate, make decisions and handle conflict, and then helps them diagnose and improve these interactions themselves. Which OD intervention is this?","options":["Survey feedback","Sensitivity (T-group) training","Process consultation","Team building through outdoor activities"],"answer":2,"explanation":"Schein's process consultation helps a client see and act on the processes in its own interactions, rather than having the consultant solve the business problem. T-groups are unstructured groups focused on personal awareness.","difficulty":"very-hard","source":"HR MT · Consulting"},
  {"id":"mgmt-hr-ob-422","question":"Which of these is the correct general order of steps in the action-research model of organisational change?","options":["Diagnosis, analysis, feedback, action, evaluation","Action, diagnosis, analysis, evaluation, feedback","Analysis, action, diagnosis, feedback, evaluation","Feedback, diagnosis, action, analysis, evaluation"],"answer":0,"explanation":"Action research collects and diagnoses data, analyses it, feeds it back to those involved, plans and takes action, and then evaluates the results, often in repeating cycles.","difficulty":"moderate","source":"HR MT · MBA placement"},
  {"id":"mgmt-hr-ob-423","question":"Peter Senge named five disciplines of a learning organisation. Which one did he call 'the fifth discipline' that integrates the others?","options":["Personal mastery","Shared vision","Team learning","Systems thinking"],"answer":3,"explanation":"Systems thinking, seeing interrelationships and patterns rather than isolated events, ties together personal mastery, mental models, shared vision and team learning.","difficulty":"moderate","source":"HR MT · MBA placement"},
  {"id":"mgmt-hr-ob-424","question":"A support team keeps fixing customer complaints faster each month by tweaking its scripts. Only when a new manager asks why the product generates so many complaints in the first place does the team question its basic goals. In Argyris's terms, the shift is from:","options":["Double-loop to single-loop learning","Single-loop to double-loop learning","Deutero-learning to single-loop learning","Exploitation to imitation"],"answer":1,"explanation":"Single-loop learning corrects errors within existing goals and assumptions; double-loop learning questions the goals and assumptions themselves.","difficulty":"hard","source":"HR MT · Consulting"},
  {"id":"mgmt-hr-ob-425","question":"In William Bridges' transition model, people go through three phases as they adjust to change. Which is the correct order?","options":["Ending, losing, letting go → the neutral zone → the new beginning","Unfreeze → change → refreeze","The neutral zone → ending → the new beginning","Denial → resistance → commitment"],"answer":0,"explanation":"Bridges focuses on the psychological transition: people first let go of the old, pass through a confusing neutral zone, and then embrace a new beginning. Unfreeze–change–refreeze is Lewin's model.","difficulty":"hard","source":"HR MT · Consulting"},
  {"id":"mgmt-hr-ob-426","question":"In a CRM rollout, employees understand why the change is needed and want it to succeed, but many do not yet know how to use the new screens. In Prosci's ADKAR model, which element is the current barrier?","options":["Awareness","Desire","Knowledge","Reinforcement"],"answer":2,"explanation":"ADKAR runs Awareness, Desire, Knowledge, Ability, Reinforcement. Awareness and desire are in place; knowing how to change is the gap, so training is the next step.","difficulty":"hard","source":"HR MT · Consulting"},
  {"id":"mgmt-hr-ob-427","question":"A hospital unit where nurses openly report their own medication errors, without fear of blame, ends up recording more errors than other units but makes fewer serious mistakes over time. Which concept best explains this?","options":["Groupthink","Psychological safety","Social loafing","Escalation of commitment"],"answer":1,"explanation":"Edmondson found that teams with high psychological safety report more errors because members feel safe to speak up, which lets them learn and prevent serious harm.","difficulty":"hard","source":"HR MT · Consulting"},
  {"id":"mgmt-hr-ob-428","question":"Which of these is an organisational, rather than an individual, source of resistance to change?","options":["Habit","Fear of the unknown","Selective information processing","Threat to established resource allocations"],"answer":3,"explanation":"Organisational sources include structural inertia, group inertia, threats to expertise, power relationships and established resource allocations. Habit, fear of the unknown and selective processing arise within individuals.","difficulty":"hard","source":"HR MT · MBA placement"},
  {"id":"mgmt-hr-ob-429","question":"After a successful rollout of a new quality process, workers drift back to the old method within six months. Investigation shows that the bonus formula still rewards volume alone. In Lewin's model, which step was neglected?","options":["Unfreezing","Moving","Refreezing","Diagnosis"],"answer":2,"explanation":"Refreezing stabilises the new behaviour by aligning rewards, structures and norms with it. Leaving the old reward system in place lets the new behaviour fade.","difficulty":"moderate","source":"HR MT · MBA placement"},
  {"id":"mgmt-hr-ob-430","question":"In a force-field analysis, a manager finds the forces against a change roughly balance the forces for it. According to Lewin, which approach usually produces a more lasting change with less tension?","options":["Adding more driving forces, such as tighter deadlines","Reducing the restraining forces, such as addressing workers' fears","Ignoring both and implementing by order","Waiting for the balance to shift on its own"],"answer":1,"explanation":"Increasing driving forces tends to raise opposing pressure and tension; reducing restraining forces lets the equilibrium move with less resistance.","difficulty":"hard","source":"HR MT · MBA placement"},
  {"id":"mgmt-hr-ob-431","question":"According to Edgar Schein, which of these is a primary mechanism by which leaders embed culture, rather than a secondary reinforcing one?","options":["What leaders systematically pay attention to, measure and reward","The design of the office space","The company's formal mission statement","Stories and legends about the founder"],"answer":0,"explanation":"Schein's primary mechanisms include what leaders attend to and measure, how they react to crises, how they allocate resources and rewards, and whom they hire and promote. Structures, physical spaces, stories and formal statements only reinforce them.","difficulty":"very-hard","source":"HR MT · Consulting"},
  {"id":"mgmt-hr-ob-432","question":"Assertion (A): Two business units of the same company can have noticeably different cultures.\nReason (R): Subcultures form around shared problems and experiences in departments or locations, while still sharing the organisation's core values.","options":["Both A and R are true and R explains A","Both A and R are true but R does not explain A","A is true but R is false","A is false but R is true"],"answer":0,"explanation":"Large organisations contain subcultures shaped by their units' work, geography and leaders. These coexist with the dominant culture's core values, which explains the variation.","difficulty":"moderate","source":"HR MT · MBA placement"},
  {"id":"mgmt-hr-ob-433","question":"An HR team runs a 'safety climate' survey and separately studies the company's culture. Which of these is the most accurate distinction between organisational culture and climate?","options":["Climate refers to deep, shared assumptions; culture is a short-term mood","They are identical concepts","Culture refers to deep, shared values and assumptions; climate is employees' shared perceptions of the current work environment, such as policies and practices","Climate exists only at the individual level, and culture only at the national level"],"answer":2,"explanation":"Culture is the deeper, slower-changing system of values and assumptions; climate is the more immediate, measurable perception of practices, such as a safety or service climate.","difficulty":"hard","source":"HR MT · Consulting"},
  {"id":"mgmt-hr-ob-434","question":"For a trainee-officer role, 60 of 120 applicants from Group A are selected, and 18 of 50 applicants from Group B. Under the widely used four-fifths (80%) rule of thumb for adverse impact, what is the conclusion?","options":["No adverse impact, because 18 people from Group B were hired","No adverse impact, because the ratio of selection rates is 0.9","Possible adverse impact, because Group B's selection rate is only 72% of Group A's","Possible adverse impact, because Group B had fewer applicants"],"answer":2,"explanation":"Selection rates are 50% for A and 36% for B; 36 / 50 = 0.72, below 0.80, which flags possible adverse impact. The rule compares rates, not head counts or applicant numbers.","difficulty":"very-hard","source":"HR analyst · MBA placement"},
  {"id":"mgmt-hr-ob-435","question":"A firm hires 20 people a year for a role where they stay on average 2 years. Its new test has validity 0.4, the standard deviation of yearly job performance in money terms is ₹3 lakh, and those hired average 1.0 standard deviation above the applicant mean on the test. Testing 200 applicants costs ₹2,000 each. Using utility gain = N × T × r × SDy × Z − cost, what is the gain from using the test?","options":["₹48 lakh","₹44 lakh","₹24 lakh","₹20 lakh"],"answer":1,"explanation":"Gain = 20 × 2 × 0.4 × 3 lakh × 1.0 − (200 × ₹2,000) = ₹48 lakh − ₹4 lakh = ₹44 lakh. ₹48 lakh forgets the testing cost; ₹24 lakh and ₹20 lakh ignore the 2-year tenure.","difficulty":"very-hard","source":"HR analyst · Consulting"},
  {"id":"mgmt-hr-ob-436","question":"A bank validates a new aptitude test by correlating test scores with performance ratings, but only for people it hired, who were already screened on a similar test. What is the most likely effect on the validity coefficient?","options":["It will be underestimated because of restriction of range","It will be overestimated because hired people perform better","It will be unaffected","It will become negative"],"answer":0,"explanation":"Low scorers were never hired, so the test-score range in the sample is narrowed, which shrinks the observed correlation. The test's true validity in the full applicant pool is higher.","difficulty":"very-hard","source":"HR analyst · Consulting"},
  {"id":"mgmt-hr-ob-437","question":"An HR team gives a new test to current employees and immediately correlates their scores with their latest performance ratings, rather than testing applicants and waiting to see how they perform. This is an estimate of:","options":["Predictive validity","Content validity","Face validity","Concurrent validity"],"answer":3,"explanation":"Concurrent validity uses test scores and criterion data gathered at about the same time, usually from current employees. Predictive validity tests applicants first and measures performance later.","difficulty":"hard","source":"HR analyst · MBA placement"},
  {"id":"mgmt-hr-ob-438","question":"A selection test has a validity coefficient of 0.4 against job performance. What share of the variation in performance does it account for?","options":["40%","20%","16%","60%"],"answer":2,"explanation":"Variance explained is r² = 0.4² = 0.16, or 16%. Reading the coefficient itself as a percentage (40%) is the common trap.","difficulty":"hard","source":"HR analyst · MBA placement"},
  {"id":"mgmt-hr-ob-439","question":"A job-analysis tool asks analysts to rate 194 items describing worker behaviour, grouped under information input, mental processes, work output, relationships with others and job context. Which method is this?","options":["Functional job analysis","Position Analysis Questionnaire (PAQ)","Critical incident technique","Hay guide-chart method"],"answer":1,"explanation":"The PAQ is a structured, worker-oriented questionnaire of 194 elements in those groups, which allows jobs to be compared quantitatively. The Hay method is a job-evaluation system, not job analysis.","difficulty":"hard","source":"HR MT · MBA placement"},
  {"id":"mgmt-hr-ob-440","question":"Functional job analysis (Fine) describes what a worker does in relation to three things, each rated by level of complexity. What are they?","options":["Skill, effort and responsibility","Knowledge, skills and abilities","Tasks, duties and responsibilities","Data, people and things"],"answer":3,"explanation":"Functional job analysis rates a job's involvement with data, people and things. Skill, effort, responsibility and working conditions are the classic compensable factors in job evaluation.","difficulty":"very-hard","source":"HR MT · Consulting"},
  {"id":"mgmt-hr-ob-441","question":"An HR team keeps a chart for each senior post showing which internal employees could step in, how ready each is now (for example 'ready now' or 'ready in two years') and their current performance. This tool is a:","options":["Replacement chart","Skills inventory","Markov transition matrix","Job specification"],"answer":0,"explanation":"Replacement charts map possible successors for key positions along with their readiness and performance. A skills inventory lists employees' skills generally, not succession for a specific post.","difficulty":"moderate","source":"HR MT · MBA placement"},
  {"id":"mgmt-hr-ob-442","question":"A company expects sales of ₹120 crore next year, and each sales rep produces about ₹1.5 crore a year. It has 70 reps now and expects 20% of them to leave during the year. Assuming the new hires all stay, how many reps should it hire?","options":["10","14","24","26"],"answer":2,"explanation":"Required reps = 120 / 1.5 = 80. Of the current 70, 20% (14) leave, so 56 remain and it must hire 80 − 56 = 24. Hiring only 10 ignores attrition.","difficulty":"hard","source":"HR analyst · MBA placement"},
  {"id":"mgmt-hr-ob-443","question":"A packing unit must pack 60,000 cartons a year, and each carton takes 0.5 standard hours. Each worker offers 1,800 working hours a year, but about 10% of that is lost to absence. How many workers does the unit need?","options":["17","18","20","19"],"answer":3,"explanation":"Workload = 60,000 × 0.5 = 30,000 hours. Effective hours per worker = 1,800 × 0.9 = 1,620, so 30,000 / 1,620 ≈ 18.5, rounded up to 19. Ignoring absence gives 16.7, or 17.","difficulty":"hard","source":"HR analyst · MBA placement"},
  {"id":"mgmt-hr-ob-444","question":"Source A (job portal) costs ₹2 lakh and yields 10 hires, of whom 60% are still with the firm after a year. Source B (employee referrals) costs ₹1.5 lakh and yields 6 hires, of whom 90% stay a year. Which source is cheaper per hire still employed after a year, and by roughly how much?","options":["Source A, by ₹5,000 per hire","Source B, by about ₹5,556 per retained hire","Source A, by about ₹5,556 per retained hire","Both cost the same per retained hire"],"answer":1,"explanation":"Cost per retained hire: A = 2,00,000 / 6 ≈ ₹33,333; B = 1,50,000 / 5.4 ≈ ₹27,778, so B is cheaper by about ₹5,556. On raw cost per hire A looks cheaper (₹20,000 vs ₹25,000), which is the trap.","difficulty":"very-hard","source":"HR analyst · Consulting"},
  {"id":"mgmt-hr-ob-445","question":"Each year 80% of juniors stay junior, 10% are promoted to senior and 10% leave; 85% of seniors stay and 15% leave. All hiring is at junior level. If the firm wants a steady state with 200 seniors, how many juniors must it hire each year?","options":["60","30","40","45"],"answer":0,"explanation":"At steady state seniors satisfy 0.15S = 0.1J, so J = 1.5 × 200 = 300 juniors. Juniors satisfy J = 0.8J + H, so H = 0.2 × 300 = 60. Hiring 30 replaces only the leavers and forgets the 10% who move up.","difficulty":"very-hard","source":"HR analyst · Consulting"},
  {"id":"mgmt-hr-ob-446","question":"Candidates are rated 1–5 on three equally weighted dimensions, and a minimum of 3 is required on each. Candidate X scores 5, 2 and 5; Candidate Y scores 3, 4 and 3. Which is selected under a multiple-cutoff approach and which under a purely compensatory approach?","options":["X under both","Y under multiple cutoff; X under compensatory","X under multiple cutoff; Y under compensatory","Y under both"],"answer":1,"explanation":"X fails the cutoff on the second dimension, so only Y survives a multiple-cutoff screen. A compensatory approach averages scores (X ≈ 4.0, Y ≈ 3.3), letting X's strengths make up for the weakness.","difficulty":"very-hard","source":"HR analyst · MBA placement"},
  {"id":"mgmt-hr-ob-447","question":"An interviewer asks: \"Tell me about a time when you had to handle an angry client. What did you do, and what happened?\" What type of structured interview question is this, and what is it based on?","options":["A situational question, based on intended future behaviour","A stress question, based on reactions under pressure","A brainteaser, based on general reasoning","A behavioural question, based on past behaviour predicting future behaviour"],"answer":3,"explanation":"Behavioural description questions ask about real past situations, on the idea that past behaviour predicts future behaviour. Situational questions start with 'What would you do if…'.","difficulty":"moderate","source":"HR MT · MBA placement"},
  {"id":"mgmt-hr-ob-448","question":"A candidate rejected at the interview stage joins a competitor and becomes its top performer. In selection terms, this is a:","options":["True negative","False positive (erroneous acceptance)","False negative (erroneous rejection)","True positive"],"answer":2,"explanation":"Rejecting someone who would have succeeded is a false negative. A false positive is hiring someone who then fails.","difficulty":"moderate","source":"HR MT · MBA placement"},
  {"id":"mgmt-hr-ob-449","question":"Consider these statements about selection methods:\nI. General mental ability tests are among the best single predictors of job performance across a wide range of jobs.\nII. Adding a second test that is highly correlated with the first usually adds a lot of incremental validity.\nIII. Combining a cognitive test with a structured interview can raise overall validity.\nWhich are correct?","options":["I and II only","II and III only","I, II and III","I and III only"],"answer":3,"explanation":"GMA tests predict well across jobs, and a structured interview captures different information, so combining them adds validity. A second test that overlaps heavily with the first adds little new information.","difficulty":"hard","source":"HR analyst · Consulting"},
  {"id":"mgmt-hr-ob-450","question":"For a test of fixed, positive validity, which change will raise the percentage of hired people who turn out to be successful?","options":["Raising the selection ratio, so the firm hires a larger share of applicants","Lowering the selection ratio, so the firm hires a smaller, more selective share","Lowering the test's reliability","Using only unstructured interviews"],"answer":1,"explanation":"With a valid test, a lower selection ratio means picking only the top scorers, which raises the success rate among those hired (the Taylor–Russell insight). A high selection ratio leaves little room to choose.","difficulty":"hard","source":"HR analyst · MBA placement"},
  {"id":"mgmt-hr-ob-451","question":"Two assessors independently score the same 40 candidates in a group discussion, and their scores correlate at only 0.35. What does this mainly indicate?","options":["Low inter-rater reliability","Low predictive validity only","High content validity","Low test–retest reliability"],"answer":0,"explanation":"Agreement between independent raters is inter-rater reliability; 0.35 is low, so the scores depend heavily on who rates. Low reliability also caps validity, but the direct issue is rater consistency.","difficulty":"moderate","source":"HR analyst · MBA placement"},
  {"id":"mgmt-hr-ob-452","question":"A bank's typing and data-accuracy test closely samples the actual tasks a teller performs, as confirmed by job experts. Which type of validity does this mainly establish?","options":["Predictive validity","Construct validity","Content validity","Concurrent validity"],"answer":2,"explanation":"Content validity is shown when a test's content is a representative sample of the job's tasks, as judged by experts. It is established by analysis, not by correlating scores with later performance.","difficulty":"hard","source":"HR MT · MBA placement"},
  {"id":"mgmt-hr-ob-453","question":"A star salesperson resigns to join a rival for higher pay, while a poor performer is let go after repeated warnings. How would HR analytics usually classify the two separations?","options":["Both as functional turnover","The first as dysfunctional, avoidable turnover; the second as functional turnover","The first as functional; the second as dysfunctional","Both as unavoidable turnover"],"answer":1,"explanation":"Losing a high performer whom the firm could have retained (for instance with pay) is dysfunctional and avoidable. Losing a poor performer is functional turnover, which can even benefit the firm.","difficulty":"hard","source":"HR analyst · MBA placement"},
  {"id":"mgmt-hr-ob-454","question":"A company reports 'time to fill' and 'time to hire' for its vacancies. What is the difference?","options":["They are two names for the same metric","Time to fill runs from candidate application to offer; time to hire runs from requisition approval to joining","Time to fill runs from requisition approval until the offer is accepted; time to hire runs from when the chosen candidate enters the pipeline until she accepts","Time to hire always exceeds time to fill"],"answer":2,"explanation":"Time to fill measures the vacancy's duration from the approved requisition; time to hire measures how long the selected candidate took to move through the process. Time to hire is usually the shorter of the two.","difficulty":"hard","source":"HR analyst · MBA placement"},
  {"id":"mgmt-hr-ob-455","question":"A company expects 15% annual attrition, needs 460 staff by year-end and has 400 now. It also knows that 20% of the people it hires during the year will leave before year-end. Ignoring timing within the year, how many people should it hire?","options":["120","144","75","150"],"answer":3,"explanation":"Current staff left at year-end = 400 × 0.85 = 340, so 120 net additions are needed. Only 80% of hires stay, so hires = 120 / 0.8 = 150. Stopping at 120 ignores new-hire attrition; 144 wrongly multiplies by 1.2 instead of dividing by 0.8.","difficulty":"very-hard","source":"HR analyst · Consulting"},
  {"id":"mgmt-hr-ob-456","question":"A recruiter wants 12 joiners. Historically, 25% of applicants pass screening, 40% of those pass the interview, 75% of those get and accept an offer, and 10% of acceptors renege before joining. How many applicants does she need?","options":["About 178","160","About 133","200"],"answer":0,"explanation":"Applicants to joiners = 0.25 × 0.40 × 0.75 × 0.90 = 0.0675, so 12 / 0.0675 ≈ 177.8, or about 178. Ignoring the 10% reneging gives 160.","difficulty":"hard","source":"HR analyst · MBA placement"},
  {"id":"mgmt-hr-ob-457","question":"Assertion (A): Employee referrals often produce hires who stay longer than hires from job advertisements.\nReason (R): Referred candidates usually get a more realistic picture of the job and culture from the employee who refers them.","options":["Both A and R are true and R explains A","Both A and R are true but R does not explain A","A is true but R is false","A is false but R is true"],"answer":0,"explanation":"Referral hires tend to have lower early turnover, and one main explanation is the realistic, inside information they get from the referrer, along with better person–organisation fit.","difficulty":"moderate","source":"HR MT · MBA placement"},
  {"id":"mgmt-hr-ob-458","question":"Which job-analysis method asks supervisors to record specific examples of very effective and very ineffective behaviour observed on the job, which are then grouped into performance dimensions?","options":["Critical incident technique","Work sampling","Diary method","Functional job analysis"],"answer":0,"explanation":"The critical incident technique collects concrete examples of effective and ineffective behaviour; these later feed into BARS and behavioural interviews. Diaries are kept by job holders about their own activities.","difficulty":"hard","source":"HR MT · MBA placement"},
  {"id":"mgmt-hr-ob-459","question":"A company fills a vacancy internally by promoting Priya, which creates a vacancy in her old post, filled by promoting Ravi, whose post is then filled from outside. Which statement about this chain is correct?","options":["One internal move creates only one vacancy in total","Internal promotions never need external hiring","The chain shows that one internal promotion can trigger several internal moves but still ends in at least one external hire if headcount is unchanged","The external hire replaces Priya directly"],"answer":2,"explanation":"Internal promotions set off 'vacancy chains': each move opens another post until a vacancy is filled from outside or eliminated. With fixed headcount, the chain still ends with an entry-level external hire.","difficulty":"hard","source":"HR MT · MBA placement"},
  {"id":"mgmt-hr-ob-460","question":"A manager uses the paired-comparison method to rank her team of 16, comparing every employee with every other employee once. If she can make 30 comparisons an hour, how long will the exercise take?","options":["About 8.5 hours","4 hours","8 hours","2 hours"],"answer":1,"explanation":"Number of pairs = n(n − 1)/2 = 16 × 15 / 2 = 120, which takes 120 / 30 = 4 hours. Using n × (n − 1) without halving gives 240 comparisons and 8 hours, the common slip.","difficulty":"hard","source":"HR analyst · MBA placement"},
  {"id":"mgmt-hr-ob-461","question":"A rater first picks the best employee on the list, then the worst, then the next best, then the next worst, and so on until everyone is placed. This appraisal method is called:","options":["Forced distribution","Paired comparison","Alternation ranking","Graphic rating scale"],"answer":2,"explanation":"Alternation ranking moves between the extremes because people find it easier to identify the best and worst than to rank the middle. Paired comparison compares every possible pair.","difficulty":"moderate","source":"HR MT · MBA placement"},
  {"id":"mgmt-hr-ob-462","question":"An appraisal form lists specific job behaviours, such as 'Greets customers within 30 seconds' and 'Follows up unresolved complaints within 24 hours', and asks the rater how often the employee shows each one, from 'almost never' to 'almost always'. This is a:","options":["Behaviourally anchored rating scale (BARS)","Behavioural observation scale (BOS)","Forced-choice scale","Critical incident log"],"answer":1,"explanation":"A BOS rates the frequency of many specific behaviours. A BARS places behavioural examples as anchors on a single scale for each dimension and asks which anchor best describes the employee.","difficulty":"very-hard","source":"HR MT · Consulting"},
  {"id":"mgmt-hr-ob-463","question":"On an appraisal form, the rater must choose, from each group of four statements that look equally favourable, the one that is most and the one that is least descriptive of the employee. Only HR knows which statements actually predict good performance. What is this method mainly designed to reduce?","options":["The cost of appraisal","The need for job analysis","Deliberate leniency and rater bias","Recency error only"],"answer":2,"explanation":"In the forced-choice method, the statements are matched on social desirability, so a rater who wants to inflate a rating cannot tell which choice helps. That curbs leniency and favouritism, though raters often dislike it.","difficulty":"very-hard","source":"HR MT · Consulting"},
  {"id":"mgmt-hr-ob-464","question":"In the first week of the appraisal year, a new team member makes a serious error in a client presentation. For the rest of the year she performs well, but her year-end rating is mediocre. Which rating error is this?","options":["Recency effect","Central tendency","Leniency","Primacy (first-impression) effect"],"answer":3,"explanation":"Letting early information dominate the overall judgement is the primacy or first-impression effect. Recency is the opposite: overweighting the last few weeks.","difficulty":"hard","source":"HR MT · MBA placement"},
  {"id":"mgmt-hr-ob-465","question":"A company trains its managers by showing them examples of performance at different levels on each dimension, discussing why each example deserves its rating, and practising until their ratings agree. What is this rater training called, and what does it mainly improve?","options":["Rater error training; it removes leniency entirely","Frame-of-reference training; it improves rating accuracy by giving raters a shared standard","Sensitivity training; it improves raters' self-awareness","Behaviour modelling; it improves raters' presentation skills"],"answer":1,"explanation":"Frame-of-reference training gives raters a common understanding of what each performance level looks like, which improves accuracy. Rater-error training mainly teaches raters to spread ratings out and can reduce accuracy.","difficulty":"very-hard","source":"HR MT · Consulting"},
  {"id":"mgmt-hr-ob-466","question":"Research on 360° and manager ratings finds that a large share of the variation in ratings reflects the rater's own tendencies rather than the performance of the person rated. This is called the:","options":["Halo effect","Pygmalion effect","Idiosyncratic rater effect","Similar-to-me error"],"answer":2,"explanation":"The idiosyncratic rater effect means ratings tell you a lot about the rater's own standards and quirks. It is one reason firms calibrate ratings and use several raters.","difficulty":"very-hard","source":"HR analyst · Consulting"},
  {"id":"mgmt-hr-ob-467","question":"A training group scores 52 on a product-knowledge test before the course and 74 after. A comparable control group with no training scores 50 and 58 on the same tests over the same period. What learning gain can be attributed to the training?","options":["22 points","24 points","16 points","14 points"],"answer":3,"explanation":"Net gain = (74 − 52) − (58 − 50) = 22 − 8 = 14 points. Ignoring the control group's improvement, which reflects practice or other factors, overstates the gain at 22.","difficulty":"hard","source":"HR analyst · MBA placement"},
  {"id":"mgmt-hr-ob-468","question":"A sales-training programme costs ₹12 lakh. Participants report ₹30 lakh of extra annual profit, estimate that 60% of it was due to the training, and say they are 80% confident in that estimate. Adjusting conservatively for both, what is the programme's ROI using Phillips' method?","options":["20%","50%","150%","44%"],"answer":0,"explanation":"Adjusted benefit = 30 × 0.60 × 0.80 = ₹14.4 lakh; ROI = (14.4 − 12) / 12 = 20%. Taking the full ₹30 lakh gives 150%, and adjusting only for attribution (₹18 lakh) gives 50%.","difficulty":"very-hard","source":"HR analyst · Consulting"},
  {"id":"mgmt-hr-ob-469","question":"A training programme has a benefit–cost ratio (BCR) of 1.5. What is its ROI as Phillips defines it?","options":["150%","50%","1.5%","66.7%"],"answer":1,"explanation":"BCR = benefits / costs, while ROI = (benefits − costs) / costs = BCR − 1 = 0.5, or 50%. Reading BCR as ROI is the common error.","difficulty":"hard","source":"HR analyst · MBA placement"},
  {"id":"mgmt-hr-ob-470","question":"A bank trains new tellers in a separate room equipped with the same counters, terminals and cash machines they will use at branches, so that mistakes do not affect real customers. This is:","options":["Vestibule training","Apprenticeship","Job rotation","Coaching on the job"],"answer":0,"explanation":"Vestibule training reproduces the real work equipment in an off-the-job setting. It combines realism with safety from the pressures of live work.","difficulty":"moderate","source":"HR MT · MBA placement"},
  {"id":"mgmt-hr-ob-471","question":"A learning-and-development head says that about 70% of a manager's development should come from challenging assignments, 20% from relationships such as coaching and feedback, and 10% from formal courses. What practical implication does this model carry?","options":["Formal courses can be dropped altogether","Classroom training should take most of the L&D budget","Development plans should focus mainly on stretch assignments and coaching, with courses as support","Only senior managers can learn from experience"],"answer":2,"explanation":"The 70-20-10 framework says most development happens through experience and others, so plans should be built around assignments and feedback. It does not say formal training is useless.","difficulty":"hard","source":"HR MT · Consulting"},
  {"id":"mgmt-hr-ob-472","question":"Trainees learn a negotiation technique through role-plays that closely copy their real client meetings, using the same documents and typical objections. According to the theory of identical elements, why should this help?","options":["Transfer of training is greater when the training situation resembles the job situation","Learning is greater when practice is massed into a single long session","Trainees learn best from abstract principles","Trainees remember more when there is no feedback"],"answer":0,"explanation":"Identical-elements theory says transfer to the job is greatest when training tasks, tools and conditions match those of the job. That supports near transfer; far transfer to new situations needs teaching of principles.","difficulty":"hard","source":"HR MT · MBA placement"},
  {"id":"mgmt-hr-ob-473","question":"Two groups learn the same software. Group A attends one 8-hour session; Group B attends four 2-hour sessions spread over two weeks. What does learning research generally predict about long-term retention?","options":["Group A retains more because the session was continuous","Both retain the same, because total time is equal","Group A retains more because it had less time to forget","Group B retains more, because spaced practice beats massed practice"],"answer":3,"explanation":"Distributed (spaced) practice generally leads to better long-term retention than massed practice, especially for complex skills, even with the same total time.","difficulty":"hard","source":"HR MT · MBA placement"},
  {"id":"mgmt-hr-ob-474","question":"Which principle of adult learning (andragogy, Knowles) is a training designer applying when she builds every module around real problems the managers face at work and lets them choose the cases they work on?","options":["Adults prefer to learn by rote","Adults learn only through extrinsic rewards","Adults are self-directed and want learning that is immediately relevant to problems they face","Adults learn best from lectures without discussion"],"answer":2,"explanation":"Knowles held that adults are self-directed, bring experience, and are problem-centred, wanting learning they can apply at once. Choice and real cases address both.","difficulty":"moderate","source":"HR MT · MBA placement"},
  {"id":"mgmt-hr-ob-475","question":"A brilliant software architect turns down a promotion to engineering manager because she wants to keep deepening her technical expertise and fears that managing people would take her away from it. In Schein's career anchors, her anchor is:","options":["General managerial competence","Autonomy and independence","Security and stability","Technical/functional competence"],"answer":3,"explanation":"People anchored in technical/functional competence want to keep growing in their specialty and resist general management. A dual career ladder lets firms reward them without forcing a move into management.","difficulty":"hard","source":"HR MT · MBA placement"},
  {"id":"mgmt-hr-ob-476","question":"An IT firm creates a 'principal engineer' track with pay and status equal to director level, so that senior engineers can advance without moving into people management. This is a:","options":["Dual career ladder","Broadbanded pay structure","Succession plan","Fast-track programme"],"answer":0,"explanation":"A dual career ladder offers parallel managerial and professional paths with comparable rewards, which helps retain technical experts.","difficulty":"moderate","source":"HR MT · MBA placement"},
  {"id":"mgmt-hr-ob-477","question":"Kathy Kram classified the functions a mentor provides into career functions and psychosocial functions. Which of these is a psychosocial function?","options":["Sponsorship for promotion","Giving challenging assignments","Role modelling","Exposure and visibility to senior leaders"],"answer":2,"explanation":"Kram's psychosocial functions are role modelling, acceptance and confirmation, counselling and friendship. Sponsorship, coaching, exposure, protection and challenging assignments are career functions.","difficulty":"very-hard","source":"HR MT · Consulting"},
  {"id":"mgmt-hr-ob-478","question":"A top sales rep is promoted to sales manager, struggles with planning and coaching, and stays in the role, performing poorly. Which principle describes this pattern?","options":["The Peter principle","Parkinson's law","The Pareto principle","The Hawthorne effect"],"answer":0,"explanation":"The Peter principle says people tend to be promoted on the basis of performance in their current job until they reach a level where they are no longer competent. Parkinson's law is about work expanding to fill the time available.","difficulty":"moderate","source":"HR MT · MBA placement"},
  {"id":"mgmt-hr-ob-479","question":"An employee changes companies and industries several times, takes charge of her own skill-building and judges success by her own values and growth rather than by promotions in one firm. Which career concept best describes her?","options":["Linear career","Protean career","Dual career ladder","Plateaued career"],"answer":1,"explanation":"A protean career is self-directed and values-driven, with the individual, not the organisation, managing it. A linear career moves steadily up one hierarchy.","difficulty":"hard","source":"HR MT · MBA placement"},
  {"id":"mgmt-hr-ob-480","question":"A manager rates an employee 'average' this year mainly because she was rated 'average' last year, even though her results this year were clearly stronger. This is best described as:","options":["Contrast effect","Central tendency","Leniency","Spillover (anchoring on past ratings) effect"],"answer":3,"explanation":"Letting past ratings carry over into the current period, regardless of current performance, is the spillover effect. Central tendency would show as rating most people in the middle.","difficulty":"hard","source":"HR MT · MBA placement"},
  {"id":"mgmt-hr-ob-481","question":"After managers rate their teams, a company holds meetings where managers of similar teams compare and adjust their ratings against common standards before the ratings are finalised. What is the main purpose of these calibration meetings?","options":["To guarantee that every employee gets a higher rating","To replace the manager's judgement with HR's","To make ratings more consistent across managers and reduce individual rater biases","To make the forced-distribution curve unnecessary in all cases"],"answer":2,"explanation":"Calibration aligns standards across raters so that a '4' means the same thing in every team. It reduces leniency, strictness and idiosyncratic effects; it does not mechanically raise ratings.","difficulty":"hard","source":"HR MT · Consulting"},
  {"id":"mgmt-hr-ob-482","question":"Consider these statements about OKRs (objectives and key results) compared with traditional annual KRAs:\nI. OKRs are usually set and reviewed more often, such as quarterly.\nII. Key results are meant to be measurable outcomes.\nIII. OKRs are normally designed so that missing a stretch key result automatically triggers a low performance rating.\nWhich are correct?","options":["I and II only","I, II and III","II and III only","I only"],"answer":0,"explanation":"OKRs are set frequently, are often transparent and use measurable key results. Most firms deliberately separate stretch OKRs from ratings and pay, so that people aim high without fear.","difficulty":"hard","source":"HR MT · Consulting"},
  {"id":"mgmt-hr-ob-483","question":"Assertion (A): Self-appraisals used for pay decisions tend to be more lenient than supervisor ratings.\nReason (R): When outcomes depend on the rating, people tend to present their own performance favourably.","options":["Both A and R are true and R explains A","Both A and R are true but R does not explain A","A is true but R is false","A is false but R is true"],"answer":0,"explanation":"Self-ratings are usually higher than supervisor ratings, particularly when tied to rewards, because of self-enhancement. They work better for development discussions than for pay.","difficulty":"moderate","source":"HR MT · MBA placement"},
  {"id":"mgmt-hr-ob-484","question":"A manager's KRAs carry weights of 40%, 30%, 20% and 10%, and she scores 4, 3, 5 and 2 on a 5-point scale. The company pays a bonus multiplier of 0.8 for an overall score below 3.6, 1.0 from 3.6 to below 4.0, and 1.2 from 4.0 up. What is her multiplier?","options":["0.8, because the overall score is 3.5","1.0, because the overall score is 3.7","1.2, because the overall score is 4.0","0.8, because the overall score is 3.3"],"answer":1,"explanation":"Weighted score = 0.4 × 4 + 0.3 × 3 + 0.2 × 5 + 0.1 × 2 = 1.6 + 0.9 + 1.0 + 0.2 = 3.7, in the 1.0 band. A simple average gives 3.5, and applying the weights in reverse order gives 3.3; both wrongly land in the 0.8 band.","difficulty":"hard","source":"HR analyst · MBA placement"},
  {"id":"mgmt-hr-ob-485","question":"Arrange the five phases of the ADDIE model of instructional design in order.\nP. Development  Q. Analysis  R. Evaluation  S. Design  T. Implementation","options":["Q, P, S, T, R","S, Q, P, T, R","Q, S, T, P, R","Q, S, P, T, R"],"answer":3,"explanation":"ADDIE runs Analysis, Design, Development, Implementation and Evaluation. Evaluation also feeds back into each phase in practice.","difficulty":"moderate","source":"HR MT · MBA placement"},
  {"id":"mgmt-hr-ob-486","question":"A point-factor plan allots a maximum of 200 points to skill, 100 to effort, 150 to responsibility and 50 to working conditions. Each factor has 5 degrees, and a job earns (degree ÷ 5) × the factor's maximum. A job is rated at degree 3 on skill, 2 on effort, 4 on responsibility and 1 on working conditions. How many points does it get?","options":["250","290","300","310"],"answer":1,"explanation":"Skill 3/5 × 200 = 120, effort 2/5 × 100 = 40, responsibility 4/5 × 150 = 120, working conditions 1/5 × 50 = 10; total 290. Averaging the degrees and scaling to 500 (2.5/5 × 500 = 250) ignores the factor weights.","difficulty":"hard","source":"HR analyst · MBA placement"},
  {"id":"mgmt-hr-ob-487","question":"Two benchmark jobs anchor a company's pay-policy line: a 200-point job pays ₹30,000 a month and a 400-point job pays ₹50,000. If the line is straight, what monthly pay does it set for a 290-point job?","options":["₹43,500","₹40,000","₹39,000","₹36,250"],"answer":2,"explanation":"The slope is (50,000 − 30,000) / (400 − 200) = ₹100 a point, so pay = 30,000 + 90 × 100 = ₹39,000. Scaling ₹30,000 in proportion to points (290/200) gives ₹43,500, which wrongly assumes the line passes through zero.","difficulty":"very-hard","source":"HR analyst · Consulting"},
  {"id":"mgmt-hr-ob-488","question":"A job-evaluation method selects key benchmark jobs, ranks them factor by factor (skill, mental effort, physical effort, responsibility, working conditions), and assigns a money value per factor; other jobs are slotted by comparison with the benchmarks on each factor. This is the:","options":["Ranking method","Job classification method","Point-factor method","Factor comparison method"],"answer":3,"explanation":"Factor comparison combines ranking with money values per factor, using benchmark jobs as a scale. The point method assigns points rather than money directly to factor degrees.","difficulty":"hard","source":"HR MT · MBA placement"},
  {"id":"mgmt-hr-ob-489","question":"The Hay guide-chart profile method evaluates jobs mainly on which three factors?","options":["Know-how, problem solving and accountability","Skill, effort and responsibility","Data, people and things","Education, experience and age"],"answer":0,"explanation":"The Hay method scores know-how, problem solving (the thinking required to apply know-how) and accountability, with working conditions added for some jobs. Skill, effort and responsibility are the classic generic compensable factors.","difficulty":"hard","source":"HR MT · Consulting"},
  {"id":"mgmt-hr-ob-490","question":"A government department sorts jobs into a set of predefined grades, each with a written description such as 'routine clerical work under close supervision', and places each job into the grade whose description fits best. This is:","options":["Ranking","Job classification (grading)","Factor comparison","Market pricing"],"answer":1,"explanation":"The classification method defines grades first and slots whole jobs into them by matching descriptions. Ranking simply orders jobs from highest to lowest with no predefined grades.","difficulty":"moderate","source":"HR MT · MBA placement"},
  {"id":"mgmt-hr-ob-491","question":"A merit matrix gives 8% to an 'exceeds' performer with a compa-ratio below 0.95, 4% to a 'meets' performer with a compa-ratio from 0.95 to 1.05, and 2% to a 'meets' performer above 1.05. A team has three people: A earns ₹50,000 (exceeds, CR 0.90), B earns ₹60,000 (meets, CR 1.00) and C earns ₹70,000 (meets, CR 1.15). What is the team's total increase as a percentage of its payroll?","options":["About 4.33%","4.67%","About 4.0%","5.0%"],"answer":0,"explanation":"Increases = 4,000 + 2,400 + 1,400 = ₹7,800 on a payroll of ₹1,80,000, which is about 4.33%. The simple average of 8%, 4% and 2% is 4.67%, which ignores that the 8% applies to the lowest salary.","difficulty":"very-hard","source":"HR analyst · Consulting"},
  {"id":"mgmt-hr-ob-492","question":"The market rate for a role is ₹10 lakh today and market pay is expected to rise 6% over the coming year. A firm that wants to lead the market in the first half of the year and lag it in the second half (a lead–lag policy) should set pay at the start of the year at about:","options":["₹10 lakh","₹10.6 lakh","₹10.3 lakh","₹9.7 lakh"],"answer":2,"explanation":"Lead–lag pay matches the market at mid-year, about 10 × 1.03 = ₹10.3 lakh. Setting ₹10.6 lakh would lead the market all year; ₹10 lakh would lag it all year.","difficulty":"very-hard","source":"HR analyst · Consulting"},
  {"id":"mgmt-hr-ob-493","question":"A sales manager's on-target earnings are ₹20 lakh with a 60:40 pay mix (base : target incentive). Above 100% of quota, each extra percentage point of attainment pays 1.5 times the normal rate. What does she earn at 120% of quota?","options":["₹21.6 lakh","₹22.4 lakh","₹24 lakh","₹23.2 lakh"],"answer":1,"explanation":"Base = ₹12 lakh and target incentive = ₹8 lakh. At 120% the incentive is 8 × (1 + 0.20 × 1.5) = ₹10.4 lakh, so total = ₹22.4 lakh. Without the accelerator, 8 × 1.2 + 12 = ₹21.6 lakh.","difficulty":"very-hard","source":"HR analyst · MBA placement"},
  {"id":"mgmt-hr-ob-494","question":"An employee is granted 4,800 stock options vesting over four years with a one-year cliff, after which options vest in equal monthly instalments. She resigns after exactly 18 months. How many options have vested?","options":["1,200","2,400","0","1,800"],"answer":3,"explanation":"At the one-year cliff, a quarter (1,200) vests at once; after that 100 options vest each month (4,800 / 48), so six more months add 600, for 1,800. Forgetting the post-cliff monthly vesting gives 1,200.","difficulty":"very-hard","source":"HR analyst · Consulting"},
  {"id":"mgmt-hr-ob-495","question":"A company's annual CTC offer is ₹12 lakh. Basic pay is 40% of CTC, and the CTC includes the employer's PF contribution at 12% of basic and a gratuity provision at 4.81% of basic. The employee also contributes 12% of basic to PF. Ignoring income tax, roughly what is her annual take-home pay?","options":["₹10.62 lakh","₹11.19 lakh","₹11.42 lakh","₹10.85 lakh"],"answer":0,"explanation":"Basic = ₹4.8 lakh; employer PF = 0.576 and gratuity = 0.231, so gross = 12 − 0.807 ≈ ₹11.19 lakh. Deducting her own PF of 0.576 gives about ₹10.62 lakh. Stopping at gross, or ignoring the gratuity provision, gives the other figures.","difficulty":"very-hard","source":"HR analyst · MBA placement"},
  {"id":"mgmt-hr-ob-496","question":"Many Indian companies show a gratuity provision of 4.81% of basic salary in the CTC. Where does this figure come from?","options":["It is 15 days' wages out of 365 days","It is 15 days' wages per year, with a month taken as 26 working days, spread over 12 months: (15/26) / 12","It is a fixed rate set by the Income Tax Act","It is half of the 12% PF rate, adjusted for tax"],"answer":1,"explanation":"Gratuity is 15 days' wages for every year of service, with the monthly wage divided by 26. Yearly cost as a share of monthly basic is 15/26, and as a share of annual basic it is (15/26)/12 ≈ 4.81%.","difficulty":"very-hard","source":"HR analyst · MBA placement"},
  {"id":"mgmt-hr-ob-497","question":"Two analysts in the same job and grade are paid differently because one has consistently higher performance ratings. Which kind of pay equity does this difference address?","options":["Internal equity","External equity","Individual (employee) equity","Procedural equity"],"answer":2,"explanation":"Individual equity concerns differences among people in the same job based on performance or experience. Internal equity compares the relative worth of different jobs; external equity compares pay with the market.","difficulty":"moderate","source":"HR MT · MBA placement"},
  {"id":"mgmt-hr-ob-498","question":"A plant pays operators according to the number of certified machine skills they have mastered, regardless of which machine they actually run on a given day. What is this pay system, and what is its main advantage?","options":["Piece-rate pay; it ties pay to output","Seniority pay; it rewards loyalty","Job-based pay; it simplifies job evaluation","Skill-based pay; it builds a flexible, multi-skilled workforce"],"answer":3,"explanation":"Skill-based pay rewards what people can do rather than the job they hold, which encourages learning and lets the plant deploy people flexibly. Its risk is paying for skills that are rarely used.","difficulty":"hard","source":"HR MT · MBA placement"},
  {"id":"mgmt-hr-ob-499","question":"A plant's gain-sharing scheme pays a bonus based on the labour hours saved, compared with a standard number of hours needed to produce its output, with savings shared between the company and all workers. Which plan does this describe?","options":["Improshare","Scanlon plan","Rucker plan","Profit-sharing plan"],"answer":0,"explanation":"Improshare measures productivity as standard hours earned versus actual hours worked. The Scanlon plan uses the ratio of labour cost to sales value, and the Rucker plan uses labour cost relative to value added.","difficulty":"very-hard","source":"HR analyst · Consulting"},
  {"id":"mgmt-hr-ob-500","question":"Which statement best distinguishes gain-sharing from profit-sharing?","options":["Gain-sharing pays a share of company profit; profit-sharing pays for cost savings","Gain-sharing rewards improvements in measures employees can influence, such as productivity or cost; profit-sharing pays a share of overall profit, which depends on many factors outside employees' control","Both are always paid as company shares","Profit-sharing is legally required and gain-sharing is not"],"answer":1,"explanation":"Gain-sharing links rewards to operational gains a group can influence, giving a clearer line of sight. Profit-sharing ties rewards to the bottom line, which is affected by prices, interest and markets.","difficulty":"hard","source":"HR MT · MBA placement"},
  {"id":"mgmt-hr-ob-501","question":"A company deliberately pays warehouse staff 20% above the local market rate, arguing that this reduces turnover, attracts better workers and makes workers less likely to shirk because they would lose a well-paid job. Which economic idea supports this?","options":["Marginal productivity theory","Wage-fund theory","Efficiency wage theory","Subsistence theory of wages"],"answer":2,"explanation":"Efficiency wage theory argues that above-market pay can pay for itself through lower turnover, better applicants and more effort. Marginal productivity theory says wages equal the value of the last worker's output.","difficulty":"hard","source":"HR MT · Consulting"},
  {"id":"mgmt-hr-ob-502","question":"Grade 3 has a pay range of ₹40,000–₹60,000 a month and Grade 4 has ₹50,000–₹75,000. What share of Grade 4's range overlaps with Grade 3's range?","options":["50%","25%","20%","40%"],"answer":3,"explanation":"The overlap runs from ₹50,000 to ₹60,000, which is ₹10,000. Grade 4's range is ₹25,000 wide, so the overlap is 10 / 25 = 40% of it. Against Grade 3's ₹20,000 range, the same overlap is 50%.","difficulty":"hard","source":"HR analyst · MBA placement"},
  {"id":"mgmt-hr-ob-503","question":"A company sets its pay for each job at the 75th percentile of a salary survey. Which pay policy is this, and what is its main purpose?","options":["A lag policy, to cut costs","A match policy, to stay neutral","A lead policy, to attract and keep better talent","A red-circle policy, to protect long-serving staff"],"answer":2,"explanation":"Paying above the market median is a lead policy, used to attract and retain talent, often for critical roles. A match policy targets the median (50th percentile).","difficulty":"moderate","source":"HR MT · MBA placement"},
  {"id":"mgmt-hr-ob-504","question":"In job evaluation, why are 'benchmark' jobs used?","options":["They are the highest-paid jobs in the company","They are jobs that will be eliminated soon","They are well known, stable jobs that exist in many organisations, so they can anchor internal evaluation and be priced against market surveys","They are jobs held by the longest-serving employees"],"answer":2,"explanation":"Benchmark jobs are common, clearly defined and found across firms, so their market rates are reliable. They link the internal job hierarchy to external pay data.","difficulty":"moderate","source":"HR MT · MBA placement"},
  {"id":"mgmt-hr-ob-505","question":"A company with a 40% gross margin must decide whether to pay a ₹50,000 annual retention bonus to each of 20 key engineers. Without it, it expects 5 of them to leave; with it, only 1. Replacing an engineer costs ₹6 lakh. What is the net financial effect of paying the bonus?","options":["A saving of ₹24 lakh","A loss of ₹10 lakh","A saving of ₹14 lakh","A saving of ₹30 lakh"],"answer":2,"explanation":"The bonus costs 20 × ₹50,000 = ₹10 lakh, and it avoids 4 departures worth 4 × ₹6 lakh = ₹24 lakh, a net saving of ₹14 lakh. The gross margin is irrelevant here; the trap is forgetting that all 20 get the bonus.","difficulty":"hard","source":"HR analyst · Consulting"},
  {"id":"mgmt-hr-ob-506","question":"Consider these statements about variable pay:\nI. Team incentives can reduce cooperation problems that individual incentives create.\nII. Team incentives are prone to free-riding when individual contributions are hard to see.\nIII. Individual incentives work best when tasks are highly interdependent.\nWhich are correct?","options":["I and II only","II and III only","I, II and III","I only"],"answer":0,"explanation":"Team incentives encourage cooperation but invite free-riding. Individual incentives fit independent tasks with clearly measurable outputs; with high interdependence, they can set people against each other.","difficulty":"hard","source":"HR MT · MBA placement"},
  {"id":"mgmt-hr-ob-507","question":"An employee's salary is ₹96,000 a month and his grade's range is ₹60,000–₹90,000. HR freezes his base pay and gives future increases as a lump sum that is not added to base. What is he, and why is this done?","options":["A green-circle employee; to raise him to the minimum","A red-circle employee; to bring him back into range over time without cutting pay","A broadband employee; to widen his range","A compressed employee; to restore internal equity with new hires"],"answer":1,"explanation":"Pay above the range maximum is red-circled; lump-sum increases reward him without pushing base pay further above the maximum. Green-circle employees are below the minimum.","difficulty":"hard","source":"HR MT · MBA placement"},
  {"id":"mgmt-hr-ob-508","question":"Assertion (A): A company can have good internal equity but still lose staff to competitors.\nReason (R): Internal equity is about fair relative pay among jobs inside the firm, while external competitiveness compares pay with the market.","options":["Both A and R are true and R explains A","Both A and R are true but R does not explain A","A is true but R is false","A is false but R is true"],"answer":0,"explanation":"A well-ordered internal structure can still sit below the market. People compare across employers, so external competitiveness matters for retention; R explains why both can coexist.","difficulty":"moderate","source":"HR MT · MBA placement"},
  {"id":"mgmt-hr-ob-509","question":"A firm's job-evaluation committee ranks 'Senior Accountant' above 'Sales Executive', but the market pays sales executives 25% more. The firm needs to hire sales executives quickly. What is the most common practical resolution?","options":["Ignore the market and pay strictly by job-evaluation points","Cut senior accountants' pay to restore balance","Abolish job evaluation for all jobs","Keep the internal structure but pay a market premium or place the sales role in a separate market-based structure"],"answer":3,"explanation":"When internal value and market value conflict for hot-skill roles, firms often add a market premium or use separate structures, balancing internal equity against the need to compete for talent.","difficulty":"hard","source":"HR MT · Consulting"},
  {"id":"mgmt-hr-ob-510","question":"A company's merit budget is 6% of payroll. Its payroll is ₹40 crore, of which ₹10 crore belongs to employees who will get no increase because they joined in the last three months. If the 6% budget must cover only the remaining employees, what average increase can they get?","options":["6%","4.5%","7.5%","8%"],"answer":3,"explanation":"Budget = 6% × 40 = ₹2.4 crore, spread over ₹30 crore of eligible payroll, giving 2.4 / 30 = 8%. 4.5% applies 6% to the eligible pool only and then divides by the full payroll.","difficulty":"hard","source":"HR analyst · MBA placement"},
  {"id":"mgmt-hr-ob-511","question":"A firm starts the year with 400 employees; 60 of them leave during the year. It hires 80 people, of whom 15 also leave before year-end. What is its retention rate (share of starting employees still employed at year-end), and roughly what is its attrition rate on average headcount?","options":["Retention 81.25%; attrition 18.75%","Retention 85%; attrition about 18.6%","Retention 85%; attrition 15%","Retention 83.8%; attrition about 18.6%"],"answer":1,"explanation":"Retention = (400 − 60) / 400 = 85%. Year-end headcount = 400 − 60 + 80 − 15 = 405, so average = 402.5 and attrition = 75 / 402.5 ≈ 18.6%. The two are not complements, because attrition counts new hires who left and uses a different base.","difficulty":"very-hard","source":"HR analyst · Consulting · MBA placement"},
  {"id":"mgmt-hr-ob-512","question":"A company has revenue of ₹500 crore, total operating expenses of ₹420 crore, and total employee costs (pay and benefits) of ₹120 crore within those expenses. Using human capital ROI = [revenue − (operating expenses − employee costs)] ÷ employee costs, what is its HCROI?","options":["0.67","4.17","1.67","2.50"],"answer":2,"explanation":"Non-people expenses = 420 − 120 = ₹300 crore, so the value attributable to people = 500 − 300 = ₹200 crore, and HCROI = 200 / 120 ≈ 1.67. Using profit (500 − 420 = 80) over 120 gives 0.67.","difficulty":"hard","source":"HR analyst · Consulting"},
  {"id":"mgmt-hr-ob-513","question":"Using the same figures (revenue ₹500 crore, operating expenses ₹420 crore including ₹120 crore of employee costs) and 2,000 full-time equivalent employees, what is the human capital value added per FTE, defined as [revenue − (operating expenses − employee costs)] ÷ FTEs?","options":["₹25 lakh","₹4 lakh","₹6 lakh","₹10 lakh"],"answer":3,"explanation":"Revenue minus non-people costs = 500 − 300 = ₹200 crore; divided by 2,000 FTEs gives ₹10 lakh. Revenue per FTE (₹25 lakh) ignores costs, and profit per FTE is ₹4 lakh.","difficulty":"hard","source":"HR analyst · Consulting"},
  {"id":"mgmt-hr-ob-514","question":"An HR team defines quality of hire as the simple average of three indicators for last year's hires: average first-year performance rating as a percentage of the maximum (80%), first-year retention (90%) and hiring-manager satisfaction (70%). What is the quality-of-hire score?","options":["80%","90%","70%","50.4%"],"answer":0,"explanation":"Simple average = (80 + 90 + 70) / 3 = 80%. Multiplying the three (0.8 × 0.9 × 0.7 = 50.4%) is a different and much harsher index.","difficulty":"moderate","source":"HR analyst · MBA placement"},
  {"id":"mgmt-hr-ob-515","question":"A plant recorded 6 lost-time injuries in a year. It has 800 workers, each working 2,400 hours a year. What is its lost-time injury frequency rate per million hours worked?","options":["7.5","3.125","0.75","2.5"],"answer":1,"explanation":"Hours worked = 800 × 2,400 = 19.2 lakh; LTIFR = 6 × 10,00,000 / 19,20,000 = 3.125. Using injuries per 100 workers gives 0.75, which is a different measure.","difficulty":"hard","source":"HR analyst · MBA placement"},
  {"id":"mgmt-hr-ob-516","question":"Three team members earn ₹45,000, ₹60,000 and ₹90,000 a month, and the midpoints of their grades are ₹50,000, ₹60,000 and ₹1,00,000. What is the team's group compa-ratio (total pay ÷ total midpoints)?","options":["0.933","0.900","1.000","0.929"],"answer":3,"explanation":"Group compa-ratio = 1,95,000 / 2,10,000 ≈ 0.929. The simple average of individual ratios (0.9, 1.0 and 0.9) is 0.933, which gives the same weight to each person regardless of salary size.","difficulty":"very-hard","source":"HR analyst · Consulting"},
  {"id":"mgmt-hr-ob-517","question":"A BPO's monthly attrition is a steady 2% of the headcount at the start of each month, and nobody is hired. What share of the starting staff will have left after 12 months?","options":["24%","About 21.5%","About 78.5%","2%"],"answer":1,"explanation":"Survivors after 12 months = 0.98¹² ≈ 0.785, so about 21.5% have left. Simply multiplying 2% × 12 = 24% ignores that each month's 2% applies to a shrinking base.","difficulty":"very-hard","source":"HR analyst · Consulting"},
  {"id":"mgmt-hr-ob-518","question":"In a plant, 2,000 worker-days a year are lost to paid sick leave. Each absent worker is still paid ₹1,500 a day, and the shift is covered by a colleague on overtime at 1.5 times that rate. What is the extra cost caused by these absences compared with full attendance?","options":["₹45 lakh","₹75 lakh","₹30 lakh","₹15 lakh"],"answer":0,"explanation":"With full attendance the firm would still pay the ₹1,500 wage, so the extra cost per absent day is the overtime of 1.5 × 1,500 = ₹2,250, giving 2,000 × 2,250 = ₹45 lakh. Adding the absentee's wage double-counts it (₹75 lakh).","difficulty":"very-hard","source":"HR analyst · Consulting"},
  {"id":"mgmt-hr-ob-519","question":"In a company of 500, 60% of employees are engaged, with annual attrition of 8%; the rest are disengaged, with attrition of 20%. Each departure costs ₹5 lakh. If engagement rises to 70% and both attrition rates stay the same, how much does the company save each year?","options":["₹50 lakh","₹60 lakh","₹30 lakh","₹12 lakh"],"answer":2,"explanation":"Leavers now = 300 × 0.08 + 200 × 0.20 = 64; after the change = 350 × 0.08 + 150 × 0.20 = 58. Six fewer departures × ₹5 lakh = ₹30 lakh.","difficulty":"very-hard","source":"HR analyst · Consulting"},
  {"id":"mgmt-hr-ob-520","question":"A department's headcount was 500 at the start of the year. During the year it hired 120 people, received 10 transfers from other departments, lost 90 employees through separations and transferred 15 people out. What is its year-end headcount?","options":["515","530","525","540"],"answer":2,"explanation":"500 + 120 + 10 − 90 − 15 = 525. Leaving out the internal transfers gives 530; counting transfers out as separations in the attrition rate is a separate (common) mistake.","difficulty":"moderate","source":"HR analyst · MBA placement"},
  {"id":"mgmt-hr-ob-521","question":"Five women in a team earn ₹40k, ₹50k, ₹60k, ₹70k and ₹180k a month; five men earn ₹50k, ₹60k, ₹70k, ₹80k and ₹90k. Which statement about the gender pay gap (men's pay minus women's, as a share of men's) is correct?","options":["Both the mean and median show women earning about 14% less","Both show women earning about 14% more","The mean gap is zero and the median gap is 14%","The mean shows women earning about 14% more, while the median shows them earning about 14% less"],"answer":3,"explanation":"Means: women ₹80k, men ₹70k, so women earn about 14% more on average. Medians: women ₹60k, men ₹70k, so the median woman earns about 14% less. One very high earner pulls the women's mean up, which is why both measures are reported.","difficulty":"very-hard","source":"HR analyst · Consulting"},
  {"id":"mgmt-hr-ob-522","question":"Last year a company filled 120 vacancies, 30 of them with existing employees and 90 from outside. Its leadership wants an internal fill rate of at least 40%. If next year it again fills 120 vacancies, how many more must it fill internally than last year?","options":["10","18","48","12"],"answer":1,"explanation":"Last year's internal fill rate = 30 / 120 = 25%. At 40%, it needs 0.40 × 120 = 48 internal fills, which is 18 more than last year. 48 is the total needed, not the increase.","difficulty":"hard","source":"HR analyst · MBA placement"},
  {"id":"mgmt-hr-ob-523","question":"An HR function costs ₹2.4 crore a year and serves 1,600 employees, while the industry benchmark is ₹12,000 of HR cost per employee. What is the function's HR cost per employee, and how does it compare with the benchmark?","options":["₹15,000; 25% above the benchmark","₹15,000; 20% above the benchmark","₹1,500; far below the benchmark","₹12,000; equal to the benchmark"],"answer":0,"explanation":"HR cost per employee = 2,40,00,000 / 1,600 = ₹15,000, which is (15,000 − 12,000) / 12,000 = 25% above the benchmark. Dividing the gap by ₹15,000 gives 20%, the wrong base.","difficulty":"moderate","source":"HR analyst · MBA placement"},
  {"id":"mgmt-hr-ob-524","question":"A new hire earning ₹1 lakh a month produces output worth twice her salary once fully productive. She ramps up linearly from 0% to 100% productivity over her first 6 months. What value of output is lost during the ramp-up compared with an already-productive employee?","options":["₹12 lakh","₹3 lakh","₹6 lakh","₹4 lakh"],"answer":2,"explanation":"A linear ramp from 0 to 100% averages 50% over 6 months, so the shortfall equals 3 months of full output. Full output is ₹2 lakh a month, so the loss is 3 × 2 = ₹6 lakh. Using salary rather than output value gives ₹3 lakh.","difficulty":"very-hard","source":"HR analyst · Consulting"},
  {"id":"mgmt-hr-ob-525","question":"A team has 40 employees working a standard 160 hours a month. In one month they log 7,040 hours in total, all hours beyond the standard being overtime. What is the overtime percentage (overtime hours ÷ standard hours)?","options":["10%","9.1%","12%","8%"],"answer":0,"explanation":"Standard hours = 40 × 160 = 6,400, so overtime = 7,040 − 6,400 = 640 hours, or 640 / 6,400 = 10%. Dividing by total hours (640 / 7,040) gives about 9.1%.","difficulty":"moderate","source":"HR analyst · MBA placement"},
  {"id":"mgmt-hr-ob-526","question":"Consider these statements about HR metrics:\nI. Revenue per employee can rise simply because work is outsourced, even if productivity is unchanged.\nII. A low cost per hire is always good, regardless of quality of hire.\nIII. Time to fill can fall while quality of hire also falls.\nWhich are correct?","options":["I only","I, II and III","I and III only","II and III only"],"answer":2,"explanation":"Outsourcing cuts headcount without cutting revenue, inflating revenue per employee, and speed can come at the expense of quality. A cheap hire who performs poorly or leaves quickly is not a good outcome, so II is false.","difficulty":"hard","source":"HR analyst · Consulting"},
  {"id":"mgmt-hr-ob-527","question":"A firm recorded 36 voluntary resignations last year on an average headcount of 300. HR classifies 12 of them as 'regretted' (people it wanted to keep). What are the voluntary attrition rate and the regretted attrition rate?","options":["12% and 33%","12% and 4%","36% and 12%","4% and 12%"],"answer":1,"explanation":"Voluntary attrition = 36 / 300 = 12%; regretted attrition = 12 / 300 = 4%. 33% is the share of resignations that were regretted (12 / 36), which uses a different base.","difficulty":"hard","source":"HR analyst · MBA placement"},
  {"id":"mgmt-hr-ob-528","question":"Exit interviews show that 45% of leavers cite 'manager relationship', 25% 'pay', 20% 'career growth' and 10% other reasons. Last year 120 people left at an average replacement cost of ₹4 lakh. If a manager-training programme halves departures caused by manager relationships, what saving does it produce, assuming nothing else changes?","options":["₹2.16 crore","₹1.20 crore","₹1.08 crore","₹54 lakh"],"answer":2,"explanation":"Manager-related departures = 0.45 × 120 = 54; halving avoids 27 departures × ₹4 lakh = ₹1.08 crore. ₹2.16 crore assumes all 54 are avoided.","difficulty":"hard","source":"HR analyst · Consulting"},
  {"id":"mgmt-hr-ob-529","question":"A company's training spend is ₹1.8 crore on a payroll of ₹60 crore, and it trains 1,200 employees for an average of 24 hours each. What are training spend as a share of payroll and training cost per hour?","options":["3% and ₹625 per hour","3% and ₹15,000 per hour","0.3% and ₹625 per hour","3.33% and ₹6,250 per hour"],"answer":0,"explanation":"Spend / payroll = 1.8 / 60 = 3%. Total training hours = 1,200 × 24 = 28,800, so cost per hour = 1,80,00,000 / 28,800 = ₹625. ₹15,000 is the cost per employee, not per hour.","difficulty":"hard","source":"HR analyst · MBA placement"},
  {"id":"mgmt-hr-ob-530","question":"An engagement survey item's favourable score rose from 62% to 68%. One analyst reports 'a 6% increase' and another 'a 9.7% increase'. Which is the most precise description?","options":["Both are wrong; the change is 68%","A 6-percentage-point increase, which is a relative rise of about 9.7%","A 6% relative increase, which is 9.7 percentage points","A 9.7-percentage-point increase"],"answer":1,"explanation":"68 − 62 = 6 percentage points; 6 / 62 ≈ 9.7% relative change. Confusing percentage points with percent change is a common reporting error in HR dashboards.","difficulty":"moderate","source":"HR analyst · MBA placement"},
  {"id":"mgmt-hr-ob-531","question":"A sales unit's annual attrition is 30% on an average headcount of 200. Each departure costs ₹3 lakh, and a retention programme costing ₹40 lakh a year would cut attrition to 22%. What is the net annual saving?","options":["₹48 lakh","₹8 lakh","₹1.32 crore","A loss of ₹8 lakh"],"answer":1,"explanation":"Departures fall from 60 to 44, avoiding 16 × ₹3 lakh = ₹48 lakh; after the ₹40 lakh cost, the net saving is ₹8 lakh. ₹48 lakh forgets the programme's cost.","difficulty":"hard","source":"HR analyst · MBA placement"},
  {"id":"mgmt-hr-ob-532","question":"A company tracks absence frequency (number of separate absence spells per employee) and absence rate (days lost as a share of available days). Team P has 50 employees with 25 spells totalling 250 days; Team Q has 50 employees with 100 spells totalling 150 days. Both teams have 250 working days a year. Which statement is correct?","options":["Team P has both the higher frequency and the higher absence rate","Team Q has both the higher frequency and the higher absence rate","Team P has the higher absence rate but Team Q has the higher frequency of spells","Both teams have the same absence rate"],"answer":2,"explanation":"Absence rate: P = 250 / 12,500 = 2.0%, Q = 150 / 12,500 = 1.2%. Frequency: P = 0.5 spells per employee, Q = 2.0. Q's many short absences are more disruptive, which is why frequency is tracked separately.","difficulty":"hard","source":"HR analyst · MBA placement"},
  {"id":"mgmt-hr-ob-533","question":"Women make up 45% of a company's entry-level staff, 30% of middle managers and 15% of senior leaders. Last year 80 women and 120 men were eligible for promotion to middle management; 12 women and 30 men were promoted. What is the ratio of the women's promotion rate to the men's?","options":["0.40","0.80","1.67","0.60"],"answer":3,"explanation":"Promotion rates are 12 / 80 = 15% for women and 30 / 120 = 25% for men, a ratio of 0.60. Comparing head counts (12 / 30 = 0.40) ignores the different numbers eligible.","difficulty":"hard","source":"HR analyst · Consulting"},
  {"id":"mgmt-hr-ob-534","question":"A company calculates annual attrition as separations divided by year-end headcount. It started the year with 1,000 employees, hired 500 and lost 200. Compared with using average headcount, this method:","options":["Overstates attrition, giving about 15.4% instead of 13.3%","Gives the same result","Understates attrition, giving about 15.4% instead of 16.7%","Understates attrition, giving about 15.4% instead of 17.4%"],"answer":3,"explanation":"Year-end headcount = 1,300, so 200 / 1,300 ≈ 15.4%; average headcount = 1,150, so 200 / 1,150 ≈ 17.4%. In a growing firm the end-of-year base is the largest, so it understates attrition.","difficulty":"very-hard","source":"HR analyst · Consulting"},
  {"id":"mgmt-hr-ob-535","question":"Assertion (A): A company's average tenure can rise even while its retention of new hires is getting worse.\nReason (R): If hiring slows sharply, the workforce is dominated by long-serving staff, which pushes average tenure up regardless of what happens to new joiners.","options":["Both A and R are true and R explains A","Both A and R are true but R does not explain A","A is true but R is false","A is false but R is true"],"answer":0,"explanation":"Average tenure depends heavily on the hiring mix. A hiring freeze ages the workforce and raises tenure even as early attrition worsens, so tenure alone is a poor retention metric.","difficulty":"very-hard","source":"HR analyst · Consulting"},
  {"id":"mgmt-hr-ob-536","question":"A recruiter's dashboard shows 400 applications, 80 interviews, 20 offers and 15 joiners for a role. What are the interview-to-offer ratio and the offer-to-join rate?","options":["5:1 and 75%","4:1 and 80%","20:1 and 75%","4:1 and 75%"],"answer":3,"explanation":"Interviews per offer = 80 / 20 = 4, so 4:1; offer-to-join = 15 / 20 = 75%. 5:1 is the application-to-interview ratio (400 / 80).","difficulty":"moderate","source":"HR analyst · MBA placement"},
  {"id":"mgmt-hr-ob-537","question":"Under India's bonus law (the Payment of Bonus Act, with the same limits carried into the Code on Wages), what are the minimum and maximum statutory bonus as a percentage of the salary or wages on which bonus is calculated?","options":["8.33% and 20%","8.33% and 25%","10% and 20%","5% and 15%"],"answer":0,"explanation":"Statutory bonus must be at least 8.33% (one month's pay in twelve) and cannot exceed 20%. Within that band, the actual rate depends on the allocable surplus.","difficulty":"moderate","source":"HR MT · MBA placement"},
  {"id":"mgmt-hr-ob-538","question":"A worker is retrenched after 7 years and 8 months of continuous service. His last-drawn average pay is ₹26,000 a month. Using the Indian rule of 15 days' average pay for each completed year of service, and treating any part of a year over six months as a full year, with a month taken as 26 days, what retrenchment compensation is due?","options":["₹1,05,000","₹1,20,000","₹90,000","₹1,30,000"],"answer":1,"explanation":"Seven years and eight months counts as 8 years. Daily pay = 26,000 / 26 = ₹1,000, so compensation = 15 × 1,000 × 8 = ₹1,20,000. Ignoring the part-year rule gives 7 years and ₹1,05,000.","difficulty":"very-hard","source":"HR analyst · MBA placement"},
  {"id":"mgmt-hr-ob-539","question":"A factory's adult workers are scheduled for 9 hours a day, 6 days a week. Which statement about the Factories Act limits is correct?","options":["It breaches the weekly limit of 48 hours unless the extra hours are treated as overtime paid at twice the ordinary rate","It is lawful, because 9 hours a day is within the daily limit","It breaches only the daily limit","It is lawful, because the weekly limit is 60 hours"],"answer":0,"explanation":"The Factories Act limits adult workers to 9 hours a day and 48 hours a week. Six 9-hour days make 54 hours, so 6 hours count as overtime, payable at twice the ordinary rate of wages.","difficulty":"hard","source":"HR MT · MBA placement"},
  {"id":"mgmt-hr-ob-540","question":"Under the Maternity Benefit Act as amended in 2017, what is the maximum period of paid maternity benefit for a woman having her first or second child?","options":["26 weeks","12 weeks","18 weeks","6 months plus 12 weeks"],"answer":0,"explanation":"The 2017 amendment raised maternity benefit to 26 weeks for the first two children; for the third child onwards it remains 12 weeks.","difficulty":"moderate","source":"HR MT · MBA placement"},
  {"id":"mgmt-hr-ob-541","question":"A company pays its workers through a contractor, and the contractor fails to pay one month's wages. Under the principle followed in Indian contract-labour law, who must ensure the workers are paid?","options":["Nobody; the workers must sue the contractor","The workers' trade union","The principal employer, who can then recover the amount from the contractor","The state labour department from its own funds"],"answer":2,"explanation":"The principal employer is responsible for ensuring contract workers are paid if the contractor fails, and may recover the amount from the contractor. This is why principal employers check contractors' wage compliance.","difficulty":"hard","source":"HR MT · MBA placement"},
  {"id":"mgmt-hr-ob-542","question":"Under the Employees' Provident Fund scheme, the employer contributes 12% of basic wages plus dearness allowance. How is the employer's 12% split?","options":["All 12% goes to the employee's provident fund account","6% to provident fund and 6% to pension","10% to provident fund and 2% to insurance","8.33% to the pension scheme (EPS) and 3.67% to the provident fund (EPF)"],"answer":3,"explanation":"Of the employer's 12%, 8.33% goes to the Employees' Pension Scheme (subject to the wage ceiling) and the balance of 3.67% to the EPF account; the employee's own 12% goes fully to EPF.","difficulty":"hard","source":"HR MT · MBA placement"},
  {"id":"mgmt-hr-ob-543","question":"A company's net profits (as computed for CSR purposes) for the last three financial years were ₹40 crore, ₹60 crore and ₹80 crore, and it falls within the CSR thresholds of the Companies Act, 2013. What is its minimum CSR spend for the current year?","options":["₹1.6 crore","₹3.6 crore","₹1.2 crore","₹0.8 crore"],"answer":2,"explanation":"Section 135 requires at least 2% of the average net profit of the three immediately preceding years: average = 60, and 2% of 60 = ₹1.2 crore. Using the latest year's ₹80 crore gives ₹1.6 crore.","difficulty":"hard","source":"HR MT · Consulting"},
  {"id":"mgmt-hr-ob-544","question":"Workers in a plant deliberately slow their work to a crawl to pressure management, while staying at their machines. How is such a 'go-slow' generally treated in Indian industrial relations?","options":["As a lawful strike, since workers have stopped normal output","As a lockout by the employer","As a form of collective bargaining protected by law","As misconduct, not as a strike, since workers keep drawing full wages while withholding output"],"answer":3,"explanation":"Indian courts have treated go-slow as serious misconduct rather than a strike: workers remain at work and claim full wages while deliberately restricting output. A strike involves a cessation of work.","difficulty":"very-hard","source":"HR MT · MBA placement"},
  {"id":"mgmt-hr-ob-545","question":"When retrenching workers in a category, an employer ordinarily retrenches the employee who joined most recently first, unless it records reasons for doing otherwise. What is this principle called?","options":["Last come, first go","First come, first go","Merit-based retrenchment","Seniority bypass"],"answer":0,"explanation":"Indian law follows 'last come, first go' for retrenchment within a category, unless the employer records valid reasons for departing from it. This protects senior workers from arbitrary selection.","difficulty":"moderate","source":"HR MT · MBA placement"},
  {"id":"mgmt-hr-ob-546","question":"Dunlop's industrial-relations system theory describes three main actors. Who are they?","options":["Workers, consumers and shareholders","Managers, workers and their organisations, and government agencies","Unions, courts and the media","Employers, suppliers and customers"],"answer":1,"explanation":"Dunlop's actors are managers, workers and their representatives, and specialised government agencies. They interact within technological, market and power contexts and a shared ideology to produce a 'web of rules'.","difficulty":"hard","source":"HR MT · MBA placement"},
  {"id":"mgmt-hr-ob-547","question":"A CEO says: \"In a well-run company everyone shares the same goals; unions only bring in outsiders and create needless conflict.\" Which perspective on industrial relations does this reflect?","options":["Pluralist","Marxist (radical)","Unitarist","Systems"],"answer":2,"explanation":"The unitarist view sees the organisation as one team with common interests and treats conflict and unions as unnecessary or harmful. The pluralist view accepts that groups have legitimate different interests and that conflict should be managed.","difficulty":"hard","source":"HR MT · MBA placement"},
  {"id":"mgmt-hr-ob-548","question":"Walton and McKersie described four sub-processes in labour negotiations. A union leader spends time convincing her own members to lower their unrealistic expectations before the next round. Which sub-process is she engaged in?","options":["Distributive bargaining","Integrative bargaining","Attitudinal structuring","Intra-organisational bargaining"],"answer":3,"explanation":"Intra-organisational bargaining is the negotiation within each side to align its own members' expectations. Attitudinal structuring shapes the relationship and trust between the two sides.","difficulty":"very-hard","source":"HR MT · Consulting"},
  {"id":"mgmt-hr-ob-549","question":"A company and its union agree that the company will deduct union dues directly from members' salaries and pass them to the union. This arrangement is called:","options":["A closed shop","A check-off system","An agency shop","A union shop"],"answer":1,"explanation":"Under the check-off system the employer deducts union subscriptions at source. A closed shop requires union membership before hiring, and a union shop requires joining after hiring.","difficulty":"moderate","source":"HR MT · MBA placement"},
  {"id":"mgmt-hr-ob-550","question":"A wage dispute reaches an impasse. Both parties agree to refer it to a mutually chosen person whose decision they accept as binding. This is:","options":["Conciliation","Adjudication","Voluntary arbitration","Mediation"],"answer":2,"explanation":"In voluntary arbitration, the parties jointly choose the arbitrator and agree to be bound. A conciliator or mediator only helps them reach their own agreement; adjudication is compulsory reference to a labour court or tribunal.","difficulty":"hard","source":"HR MT · MBA placement"},
  {"id":"mgmt-hr-ob-551","question":"An employee feels she was unfairly denied overtime and raises the issue. Which sequence reflects a typical grievance procedure in Indian companies?","options":["Supervisor → department head → grievance committee → top management, with voluntary arbitration as a last step","Labour court → HR → supervisor → management","Union → government → supervisor","Top management → supervisor → HR"],"answer":0,"explanation":"Grievances are first raised with the immediate supervisor, then escalated to the department head, a grievance committee and top management, with arbitration as a final step if unresolved.","difficulty":"moderate","source":"HR MT · MBA placement"},
  {"id":"mgmt-hr-ob-552","question":"A manager reasons: \"I won't falsify the report because I could get caught and fired.\" A colleague reasons: \"I won't falsify it because honesty in reporting is a principle I hold, whatever the rules say.\" In Kohlberg's stages of moral development, which levels do they reflect?","options":["Manager: post-conventional; colleague: pre-conventional","Both are at the conventional level","Manager: conventional; colleague: pre-conventional","Manager: pre-conventional; colleague: post-conventional"],"answer":3,"explanation":"Avoiding punishment is pre-conventional reasoning; acting on self-chosen universal principles is post-conventional. The conventional level rests on meeting others' expectations and following laws and rules.","difficulty":"hard","source":"HR MT · Consulting"},
  {"id":"mgmt-hr-ob-553","question":"An employee who discovers that her company is dumping toxic waste first reports it through internal channels, gets no response, and then informs the pollution control board. Which statement best fits mainstream ethical thinking on whistleblowing?","options":["She acted wrongly, because loyalty to the employer always comes first","Going external after internal channels failed, on a serious harm backed by evidence, is generally regarded as justified","She should have gone to the media first","Whistleblowing is justified only if she gains financially"],"answer":1,"explanation":"Whistleblowing is widely seen as justified when the harm is serious, the evidence is solid and internal channels have been tried or are futile. Going to the competent regulator rather than straight to the media fits this.","difficulty":"hard","source":"HR MT · Consulting"},
  {"id":"mgmt-hr-ob-554","question":"Consider these statements about gratuity in India:\nI. It is ordinarily payable after at least five years of continuous service.\nII. The five-year condition does not apply when service ends because of death or disablement.\nIII. It is calculated at 30 days' wages for each completed year of service.\nWhich are correct?","options":["I and II only","I, II and III","II and III only","I only"],"answer":0,"explanation":"Gratuity normally needs five years of continuous service, waived on death or disablement, and is calculated at 15 days' wages per completed year (wages divided by 26). III doubles the rate.","difficulty":"hard","source":"HR MT · MBA placement"},
  {"id":"mgmt-hr-ob-555","question":"In a domestic enquiry for misconduct, the charge-sheeted employee asks to cross-examine the witnesses whose statements are being used against him. The enquiry officer refuses. Which principle is most clearly at risk?","options":["The rule against bias","Audi alteram partem (the right to be heard)","The hot-stove rule","Progressive discipline"],"answer":1,"explanation":"The right to be heard includes knowing the evidence and being able to test it, for example by cross-examining witnesses. Denying this can make the enquiry unfair and any punishment liable to be set aside.","difficulty":"very-hard","source":"HR MT · MBA placement"},
  {"id":"mgmt-hr-ob-556","question":"Which of these is a lockout rather than a strike?","options":["Workers refuse to work until a colleague is reinstated","Workers stay inside the plant but refuse to work","The employer temporarily closes the workplace or refuses to employ its workers to pressure them during a dispute","Workers work exactly to rule to slow output"],"answer":2,"explanation":"A lockout is the employer's weapon: temporary closure or refusal to continue employing workers in a dispute. The other actions are taken by workers.","difficulty":"moderate","source":"HR MT · MBA placement"},
  {"id":"mgmt-hr-ob-557","question":"Assertion (A): In Indian law, lay-off and retrenchment are different.\nReason (R): In a lay-off the employment relationship continues and workers are temporarily not given work, whereas retrenchment terminates the employment.","options":["Both A and R are true and R explains A","Both A and R are true but R does not explain A","A is true but R is false","A is false but R is true"],"answer":0,"explanation":"A laid-off worker remains an employee and receives lay-off compensation (half of basic plus DA) for the period, while retrenchment ends employment and attracts retrenchment compensation. R explains the difference stated in A.","difficulty":"hard","source":"HR MT · MBA placement"},
  {"id":"mgmt-hr-ob-558","question":"A company's code of conduct bans all gifts above ₹1,000 from suppliers. A supplier sends a ₹600 box of sweets for Diwali to the purchase manager's home while a large tender is under evaluation. What is the most defensible course?","options":["Accept it, since it is under the ₹1,000 limit","Accept it and award the tender to the supplier as a courtesy","Return it quietly without telling anyone","Decline or declare it, because the timing during an open tender creates a conflict of interest regardless of value"],"answer":3,"explanation":"Gift policies cover appearance and timing, not only value: any gift from a bidder during a live tender can be seen as an attempt to influence the decision. Declaring or returning it with a record protects both parties.","difficulty":"hard","source":"HR MT · Consulting"},
  {"id":"mgmt-hr-ob-559","question":"A union wants a 12% wage rise; management offers 6%. After talks, both sides agree to a productivity-linked deal: 8% now and a further 4% if output per worker rises 10%. In Walton and McKersie's terms, the move from arguing over the percentage to designing the productivity link is a shift from:","options":["Attitudinal structuring to distributive bargaining","Integrative to distributive bargaining","Distributive to integrative bargaining","Intra-organisational to attitudinal bargaining"],"answer":2,"explanation":"Haggling over how to split a fixed amount is distributive bargaining; creating extra value through a productivity link that benefits both sides is integrative bargaining.","difficulty":"very-hard","source":"HR MT · Consulting"},
  {"id":"mgmt-hr-ob-560","question":"A union representative is told by a manager that she will be passed over for promotion unless she persuades workers to drop their pending dispute. Which statement best describes this under Indian labour law principles?","options":["It is acceptable negotiation tactics","It may amount to an unfair labour practice by the employer, such as victimisation for union activity","It is a lockout","It is a valid disciplinary action"],"answer":1,"explanation":"Threatening or victimising a worker for legitimate union activity is treated as an unfair labour practice. Employers may negotiate firmly but may not punish workers for representing others.","difficulty":"hard","source":"HR MT · MBA placement"},
  {"id":"mgmt-hr-ob-561","question":"A firm sets up a joint council of elected worker representatives and managers to discuss safety, welfare and production problems, though the council has no say over wages. This is an example of:","options":["Collective bargaining","Grievance arbitration","Workers' participation in management","A closed shop"],"answer":2,"explanation":"Joint councils and works committees are forms of workers' participation in management, usually consultative. Collective bargaining covers terms like wages and is adversarial in structure.","difficulty":"moderate","source":"HR MT · MBA placement"},
  {"id":"mgmt-hr-ob-562","question":"An engineering company with 400 workers has certified standing orders. What is the main purpose of such standing orders under Indian labour law?","options":["To fix the minimum wage for each category of worker","To define and make known the conditions of employment, such as classification of workers, shift working, attendance, leave, misconduct and the disciplinary procedure","To register the company's trade union","To set the annual bonus rate"],"answer":1,"explanation":"Standing orders codify service conditions so that employer and workers know the rules on classification, hours, leave, misconduct and discipline. Wages and bonus are governed by other laws and agreements.","difficulty":"hard","source":"HR MT · MBA placement"},
  {"id":"mgmt-hr-ob-563","question":"A manager must choose between two actions: Action X maximises total benefit for most stakeholders but breaks a promise made to a small supplier; Action Y keeps the promise but produces somewhat less total benefit. A utilitarian and a Kantian (deontological) thinker would most likely choose:","options":["Utilitarian: Y; Kantian: X","Both would choose X","Both would choose Y","Utilitarian: X; Kantian: Y"],"answer":3,"explanation":"Utilitarianism judges actions by their total consequences, so it favours X. Kantian ethics treats keeping promises as a duty that cannot be overridden by better outcomes, so it favours Y.","difficulty":"hard","source":"HR MT · Consulting"},
  {"id":"mgmt-hr-ob-564","question":"A firm can fill a key role with an experienced hire costing ₹15 lakh a year who succeeds 90% of the time, or with a fresher costing ₹8 lakh a year plus ₹3 lakh of training who succeeds 60% of the time. A failure in either case costs an extra ₹10 lakh to fix. On expected first-year cost, which option is cheaper and by how much?","options":["Experienced hire, by ₹1 lakh","Fresher, by ₹4 lakh","Fresher, by ₹1 lakh","Experienced hire, by ₹3 lakh"],"answer":2,"explanation":"Experienced: 15 + 0.1 × 10 = ₹16 lakh. Fresher: 8 + 3 + 0.4 × 10 = ₹15 lakh. So the fresher is cheaper by ₹1 lakh; ignoring failure risk gives ₹4 lakh, and ignoring training flips the gap.","difficulty":"very-hard","source":"HR analyst · Consulting · MBA placement"},
  {"id":"mgmt-hr-ob-565","question":"A company fills 120 vacancies a year, and each stays open an average of 45 days. On a typical day, roughly how many vacancies are open?","options":["About 15","About 3","45","About 27"],"answer":0,"explanation":"By Little's law, average open vacancies = arrival rate × average duration = (120 / 365) × 45 ≈ 14.8. This links time to fill directly to the standing backlog of open roles.","difficulty":"very-hard","source":"HR analyst · Consulting"},
  {"id":"mgmt-hr-ob-566","question":"Baldwin and Ford's model of training transfer identifies three groups of inputs that affect whether learning is applied on the job. Which are they?","options":["Reaction, learning and behaviour","Trainee characteristics, training design and the work environment","Analysis, design and evaluation","Cost, time and quality"],"answer":1,"explanation":"Baldwin and Ford named trainee characteristics (ability, motivation), training design and work-environment support, such as a manager who lets trainees use new skills. Reaction, learning and behaviour are Kirkpatrick levels.","difficulty":"hard","source":"HR MT · Consulting"},
  {"id":"mgmt-hr-ob-567","question":"During restructuring, a company follows a fair process and treats staff respectfully, but gives only vague, delayed explanations of why particular roles were cut. In Colquitt's four-factor model of organisational justice, which form of justice is weakest?","options":["Distributive justice","Procedural justice","Interpersonal justice","Informational justice"],"answer":3,"explanation":"Informational justice concerns timely, candid and adequate explanations; interpersonal justice concerns dignity and respect. Here the process and respect are fine, but explanations are missing.","difficulty":"very-hard","source":"HR MT · Consulting"},
  {"id":"mgmt-hr-ob-568","question":"William Kahn argued that people engage fully in their work roles when three psychological conditions are met. Which are they?","options":["Pay, security and status","Autonomy, competence and relatedness","Meaningfulness, safety and availability","Vigour, dedication and absorption"],"answer":2,"explanation":"Kahn's conditions are meaningfulness (the work matters), psychological safety (one can show oneself without fear) and availability (one has the physical and emotional resources). Vigour, dedication and absorption describe engagement itself in a later scale.","difficulty":"very-hard","source":"HR MT · Consulting"},
  {"id":"mgmt-hr-ob-569","question":"In the job demands–resources (JD-R) model, which statement is correct?","options":["High job demands mainly drive burnout, while job resources such as support and autonomy mainly drive engagement and can buffer the effect of demands","Job resources mainly cause burnout","Demands and resources have identical effects","Engagement depends only on pay"],"answer":0,"explanation":"The JD-R model has two processes: a health-impairment path from demands to strain and burnout, and a motivational path from resources to engagement. Resources also cushion the effect of high demands.","difficulty":"hard","source":"HR MT · Consulting"},
  {"id":"mgmt-hr-ob-570","question":"An employee comes to work despite a bad fever, works at half pace for a week and infects two colleagues. HR's absenteeism metric shows no problem. What concept does this illustrate, and why does it matter?","options":["Absenteeism; she was absent","Social loafing; she shirked in a group","Withdrawal; she was planning to quit","Presenteeism; productivity is lost even though attendance looks perfect"],"answer":3,"explanation":"Presenteeism is being at work while unwell or unable to function fully. It can cost more than absence, because output falls and illness spreads, yet attendance-based metrics miss it.","difficulty":"hard","source":"HR MT · MBA placement"},
  {"id":"mgmt-hr-ob-571","question":"Using Miles and Snow's strategy types, a 'prospector' firm that constantly enters new markets with new products would most likely favour which HR approach?","options":["'Make' talent: hire mainly at entry level and develop internally with long career ladders","'Buy' talent: recruit experienced people from outside at all levels and reward results","Minimise training and pay at the market median for all roles","Freeze hiring and focus on efficiency"],"answer":1,"explanation":"Prospectors need new skills quickly and change often, so they buy talent externally and use results-based rewards. Defenders, competing on efficiency in stable niches, tend to make talent through internal development.","difficulty":"very-hard","source":"HR MT · Consulting"},
  {"id":"mgmt-hr-ob-572","question":"In Dave Ulrich's model, an HR business partner who sits with the leadership team to align hiring, capability building and rewards with the firm's three-year growth plan is acting mainly as a:","options":["Administrative expert","Employee champion","Change agent","Strategic partner"],"answer":3,"explanation":"The strategic-partner role aligns HR practices with business strategy. The administrative expert focuses on efficient processes, the employee champion on employees' concerns, and the change agent on transformation.","difficulty":"hard","source":"HR MT · MBA placement"},
  {"id":"mgmt-hr-ob-573","question":"Which statement best distinguishes the Michigan (matching) model of HRM from the Harvard model?","options":["The Michigan model emphasises stakeholder interests and employee influence; the Harvard model emphasises tight fit with strategy","The Michigan model stresses fitting HR systems (selection, appraisal, rewards, development) tightly to business strategy, a 'hard' view, while the Harvard model stresses multiple stakeholder interests and employee influence, a 'soft' view","Both models ignore strategy","Only the Harvard model includes performance appraisal"],"answer":1,"explanation":"The Michigan model treats people as resources to be managed in line with strategy through the HR cycle. The Harvard 'map' brings in stakeholders, situational factors and outcomes such as commitment and congruence.","difficulty":"very-hard","source":"HR MT · Consulting"},
  {"id":"mgmt-hr-ob-574","question":"A CEO's pay package is mostly long-term stock that vests only if total shareholder return beats peers over three years. Which theory most directly underpins this design?","options":["Agency theory","Equity theory","Two-factor theory","Expectancy theory alone"],"answer":0,"explanation":"Agency theory sees managers as agents whose interests may differ from owners'; linking pay to long-term shareholder outcomes aligns them. Equity theory concerns perceived fairness, not owner–manager alignment.","difficulty":"hard","source":"HR MT · Consulting"},
  {"id":"mgmt-hr-ob-575","question":"In many firms the pay jump from vice-president to CEO is far larger than any difference in their jobs would justify. Which theory explains this as a deliberate way of motivating all the vice-presidents?","options":["Efficiency wage theory","Tournament theory","Human capital theory","Two-factor theory"],"answer":1,"explanation":"Tournament theory treats promotions as prizes in a contest: a big prize for the winner motivates all competitors at the level below, so the gap is about incentives for many people, not the job content of one.","difficulty":"very-hard","source":"HR MT · Consulting"},
  {"id":"mgmt-hr-ob-576","question":"A manager deciding whether to promote one of two candidates asks: \"Which choice would I accept as fair if I did not know whether I would be the candidate who wins or the one who loses?\" Which ethical approach is she using?","options":["Utilitarianism","Rights approach","Rawlsian justice (veil of ignorance)","Virtue ethics"],"answer":2,"explanation":"Rawls asks us to choose principles behind a 'veil of ignorance' about our own position, which pushes towards fair rules that protect the worse off. Utilitarianism would ask which choice maximises total good.","difficulty":"hard","source":"HR MT · Consulting"},
  {"id":"mgmt-hr-ob-577","question":"A company's projects keep finishing late, even though its planners have years of data showing similar projects took 40% longer than planned. Each new plan still assumes things will go smoothly. Which bias is this, and what is a good remedy?","options":["Anchoring; avoid using any past data","Escalation of commitment; cancel all projects","Hindsight bias; review plans only after completion","Planning fallacy; use reference-class forecasting based on similar past projects"],"answer":3,"explanation":"The planning fallacy is underestimating time and cost despite knowing that past efforts overran. Reference-class forecasting corrects it by anchoring estimates on the actual outcomes of similar projects.","difficulty":"hard","source":"Consulting · MBA placement"},
  {"id":"mgmt-hr-ob-578","question":"Galbraith's information-processing view says that as task uncertainty rises, an organisation must either reduce its need to process information or increase its capacity to do so. Which of these increases processing capacity?","options":["Creating slack resources such as longer deadlines","Creating self-contained units that each have all the resources they need","Investing in vertical information systems and lateral relations such as liaison roles and teams","Lowering performance targets"],"answer":2,"explanation":"Galbraith listed slack resources and self-contained tasks as ways to reduce information needs, and vertical information systems and lateral relations as ways to increase capacity.","difficulty":"very-hard","source":"Consulting · MBA placement"},
  {"id":"mgmt-hr-ob-579","question":"Herbert Simon described decision making as three phases. Which order is correct?","options":["Choice, design, intelligence","Intelligence, design, choice","Design, intelligence, choice","Intelligence, choice, design"],"answer":1,"explanation":"Intelligence is finding situations that need a decision, design is developing possible courses of action, and choice is selecting one. Simon later added review as a fourth step.","difficulty":"hard","source":"HR MT · MBA placement"},
  {"id":"mgmt-hr-ob-580","question":"A training manager uses an 80% learning curve: each time cumulative output doubles, the time per unit falls to 80% of its previous level. If a trainee takes 100 minutes for the first assembly, how long does she take for the 8th?","options":["51.2 minutes","64 minutes","40 minutes","44 minutes"],"answer":0,"explanation":"Doubling three times: 100 → 80 (2nd) → 64 (4th) → 51.2 minutes (8th). Subtracting 20 minutes per doubling gives 40, which treats the curve as linear.","difficulty":"hard","source":"HR analyst · MBA placement"},
  {"id":"mgmt-hr-ob-581","question":"A manager meets her best performers individually to ask what keeps them in the company, what might tempt them away and what would make their work better, long before any of them resign. These are called:","options":["Exit interviews","Stay interviews","Skip-level meetings","Performance reviews"],"answer":1,"explanation":"Stay interviews explore retention drivers with current employees so that issues can be fixed in time. Exit interviews come too late for the person who is already leaving.","difficulty":"hard","source":"HR MT · MBA placement"},
  {"id":"mgmt-hr-ob-582","question":"Assertion (A): A firm that copies the 'best practices' of a successful rival exactly may still see poor results.\nReason (R): The best-fit view holds that HR practices work when they fit the firm's own strategy, culture and context, and practices must also fit each other.","options":["Both A and R are true and R explains A","Both A and R are true but R does not explain A","A is true but R is false","A is false but R is true"],"answer":0,"explanation":"Practices that work as a bundle in one context may clash with another firm's strategy or with its other practices. The best-fit and bundling arguments explain why imitation often fails.","difficulty":"very-hard","source":"HR MT · Consulting"},
  {"id":"mgmt-hr-ob-583","question":"A sales team's incentive pays the top 10% of reps a large bonus. Most reps believe that winners are decided mainly by which territory they are given, not by effort. Using Vroom's model, which component is weakest, and which fix targets it?","options":["Valence; increase the bonus","Expectancy; give more training","Instrumentality; adjust targets for territory potential so that performance, not territory, decides who wins","Valence; let reps choose non-cash prizes"],"answer":2,"explanation":"Reps doubt that good performance will be what wins the reward, so instrumentality is low. Territory-adjusted quotas restore the link between performance and reward; a bigger prize does not fix a broken link.","difficulty":"very-hard","source":"HR MT · Consulting"},
  {"id":"mgmt-hr-ob-584","question":"A 1,000-person firm has 4 management layers above front-line staff, with these headcounts from the top: 1, 6, 36 and 216 managers, all with a span of 6 except the bottom layer. The bottom layer of 216 supervisors manages 741 front-line staff. What is the average span of control of the bottom layer, and how many managers are there in total?","options":["About 3.4; 259 managers","About 3.4; 258 managers","6; 259 managers","About 4.6; 259 managers"],"answer":0,"explanation":"741 / 216 ≈ 3.4 people per supervisor. Managers = 1 + 6 + 36 + 216 = 259, and 259 + 741 = 1,000. A span of only 3.4 at the bottom is a sign of an over-layered structure.","difficulty":"hard","source":"HR analyst · Consulting"},
  {"id":"mgmt-hr-ob-585","question":"A balanced scorecard groups measures into four perspectives. In which perspective would metrics such as employee capability, training hours, retention of key talent and information-system readiness usually sit?","options":["Financial","Customer","Learning and growth","Internal business process"],"answer":2,"explanation":"Kaplan and Norton's learning and growth perspective covers people, systems and culture, the foundations that drive process, customer and financial results.","difficulty":"moderate","source":"HR MT · Consulting"},
  {"id":"mgmt-hr-ob-586","question":"Consider these statements about 'hard' and 'soft' HRM:\nI. Hard HRM treats employees mainly as a cost and resource to be used efficiently in line with strategy.\nII. Soft HRM emphasises commitment, communication and development.\nIII. A firm cannot combine elements of both.\nWhich are correct?","options":["I and II only","I, II and III","II and III only","I only"],"answer":0,"explanation":"Hard HRM is calculative and strategy-driven; soft HRM is about commitment and human relations. Most firms mix the two, so III is wrong.","difficulty":"moderate","source":"HR MT · MBA placement"},
  {"id":"mgmt-hr-ob-587","question":"Every manager at a firm rates her team on two independent 1–5 scales, performance and potential, and the firm places each employee on a 3 × 3 grid. Two employees have identical performance ratings, but one is placed in the top row for potential. What is the most appropriate use of this difference?","options":["Paying the high-potential employee a much higher bonus for the same performance","Prioritising the high-potential employee for stretch roles and succession development, while rewarding both equally for current performance","Rating the other employee lower on performance","Ignoring potential, since only performance counts"],"answer":1,"explanation":"In talent reviews, performance drives current rewards and potential guides development and succession investments. Paying different bonuses for identical performance mixes the two and undermines fairness.","difficulty":"hard","source":"HR MT · Consulting"},
  {"id":"mgmt-hr-ob-588","question":"Match each attribute of a well-designed incentive scheme with the problem it prevents.\nA. Line of sight  B. Caps on payouts  C. Clawback provisions  D. Balanced measures\n1. Rewards later found to rest on misstated results\n2. Employees cannot see how their actions affect the payout\n3. Gaming one metric at the expense of others\n4. Windfall payouts from events outside employees' control","options":["A-2, B-4, C-3, D-1","A-2, B-1, C-4, D-3","A-4, B-2, C-1, D-3","A-2, B-4, C-1, D-3"],"answer":3,"explanation":"Line of sight links actions to rewards, caps limit windfalls, clawbacks recover pay based on misstated results, and balanced scorecards of measures reduce gaming of a single metric.","difficulty":"very-hard","source":"HR analyst · Consulting"},
  {"id":"mgmt-hr-ob-589","question":"A company wants managers to make good use of 360° feedback for development. Which design choice is most likely to make the feedback useful?","options":["Linking the 360° scores directly to each manager's bonus","Having managers pick only their friends as raters","Following up the report with a coaching conversation and a development plan","Showing the results only to HR"],"answer":2,"explanation":"Feedback changes behaviour mainly when people interpret it with help and commit to specific actions. Linking it to pay, cherry-picking raters or hiding results all reduce its developmental value.","difficulty":"hard","source":"HR MT · MBA placement"},
  {"id":"mgmt-hr-ob-590","question":"After a company quietly covers an employee's large hospital bill and gives her flexible hours during recovery, she starts volunteering for extra projects and speaks up for the company in public. Which theory best explains her response?","options":["Equity theory, because she feels under-rewarded","Two-factor theory, because a hygiene factor was improved","Goal-setting theory, because she received a goal","Social exchange theory, through perceived organisational support that she reciprocates with commitment and extra effort"],"answer":3,"explanation":"Social exchange theory says that when employees feel the organisation values and cares for them (perceived organisational support), they feel obliged to reciprocate with commitment and discretionary effort.","difficulty":"hard","source":"HR MT · Consulting"},
  {"id":"mgmt-hr-ob-591","question":"A selection test has a standard deviation of 12 and a test–retest reliability of 0.75. A candidate scores 68 against a cut-off of 70. Within what range can HR be about 95% confident that her true score lies?","options":["About 56.2 to 79.8","About 62.0 to 74.0","About 62.1 to 73.9","About 50.4 to 85.6"],"answer":0,"explanation":"SEM = SD × √(1 − r) = 12 × 0.5 = 6, and the 95% band is 68 ± 1.96 × 6. The ±6 band is only about 68% confidence, and using SD × (1 − r) = 3 understates the error; either way, 68 vs 70 is not a meaningful difference.","difficulty":"hard","source":"HR analyst · MBA placement"},
  {"id":"mgmt-hr-ob-592","question":"A 20-item situational-judgement test has a reliability of 0.60. The assessment team triples it to 60 comparable items. Using the Spearman–Brown formula, what reliability should they expect?","options":["About 0.75","About 0.82","About 0.94","Still 0.60, since length does not affect reliability"],"answer":1,"explanation":"Spearman–Brown: r' = k·r / (1 + (k − 1)·r) = 3 × 0.6 / (1 + 2 × 0.6) = 1.8 / 2.2 ≈ 0.82. 0.75 is the doubling result (k = 2), and 0.94 wrongly treats the three blocks as independent chances.","difficulty":"hard","source":"HR analyst · MBA placement"},
  {"id":"mgmt-hr-ob-593","question":"Four finalists are scored out of 100 on a test and an interview, weighted equally. P: 90 and 55; Q: 65 and 70; R: 62 and 78; S: 75 and 64. One method requires at least 60 on each stage and then picks the highest average; the other simply picks the highest average. Who is chosen under each?","options":["P under both methods","R under the first, S under the second","R under the first, P under the second","S under the first, P under the second"],"answer":2,"explanation":"Averages: P 72.5, Q 67.5, R 70, S 69.5. The multiple-hurdle rule knocks P out (55 in the interview), leaving R at 70; the purely compensatory rule lets P's 90 make up for the weak interview, so P wins.","difficulty":"very-hard","source":"HR analyst · MBA placement"},
  {"id":"mgmt-hr-ob-594","question":"A plant uses Merrick's multiple piece-rate plan: the normal rate of ₹10 a unit applies up to 83% efficiency, 110% of the normal rate applies from 83% up to 100%, and 120% applies above 100%. The standard is 50 units a day. What do workers producing 45 units and 55 units earn for the day?","options":["₹450 and ₹660","₹495 and ₹605","₹540 and ₹660","₹495 and ₹660"],"answer":3,"explanation":"45 units is 90% efficiency, so 110% of the rate: 45 × ₹11 = ₹495. 55 units is 110% efficiency, so 120%: 55 × ₹12 = ₹660. Paying 45 units at the normal rate forgets the middle slab, which is what distinguishes Merrick from Taylor.","difficulty":"hard","source":"HR · cost accounting · MBA placement"},
  {"id":"mgmt-hr-ob-595","question":"Under a Gantt task-and-bonus plan, a worker who finishes a job within the standard time is paid for the full standard time plus a bonus of 25% of that standard-time wage; a worker who takes longer gets ordinary time wages for the hours actually worked. The standard time is 10 hours and the rate is ₹60 an hour. X finishes in 8 hours and Y takes 12 hours. What do they earn?","options":["X ₹750, Y ₹720","X ₹600, Y ₹720","X ₹750, Y ₹600","X ₹600, Y ₹600"],"answer":0,"explanation":"X: 10 × ₹60 = ₹600 plus 25% bonus = ₹750. Y keeps the guaranteed time wage: 12 × ₹60 = ₹720. Basing X's pay on the 8 hours actually worked gives ₹600, and denying Y the time-wage guarantee gives ₹600. The near-equal pay shows why Gantt is used to protect learners rather than to reward speed alone.","difficulty":"very-hard","source":"HR · cost accounting · MBA placement"},
  {"id":"mgmt-hr-ob-596","question":"A plant needs 2,000 extra labour hours next year. Overtime is paid at double the ordinary rate of ₹200 an hour and attracts no extra benefits. Alternatively it can hire one worker for exactly 2,000 hours at ₹200 an hour, with benefits costing 40% of wages and one-time hiring and training costs of ₹1,00,000. By how much is hiring cheaper for the year?","options":["₹2,40,000","₹1,40,000","₹4,00,000","₹4,60,000"],"answer":1,"explanation":"Overtime = 2,000 × ₹400 = ₹8,00,000. Hiring = 2,000 × ₹200 × 1.4 + ₹1,00,000 = ₹6,60,000, so hiring saves ₹1,40,000. Forgetting the hiring cost gives ₹2,40,000, ignoring benefits too gives ₹4,00,000, and loading benefits onto the overtime gives ₹4,60,000.","difficulty":"hard","source":"HR analyst · operations · MBA placement"},
  {"id":"mgmt-hr-ob-597","question":"Two assessors independently mark 50 group-discussion candidates as Pass or Fail. Both say Pass for 20, both say Fail for 15, A passes and B fails 10, and A fails and B passes 5. What is Cohen's kappa for their agreement?","options":["0.70","0.57","0.40","0.20"],"answer":2,"explanation":"Observed agreement = 35/50 = 0.70. A passes 60% and B 50%, so chance agreement = 0.6 × 0.5 + 0.4 × 0.5 = 0.50. Kappa = (0.70 − 0.50) / (1 − 0.50) = 0.40. 0.70 is raw agreement, which ignores agreement expected by chance.","difficulty":"very-hard","source":"HR analyst · MBA placement"},
  {"id":"mgmt-hr-ob-598","question":"A sales rep earns 5% commission with a recoverable draw of ₹30,000 a month: each month she is paid the higher of the draw and (commission earned − any shortfall carried forward), and any amount paid above that figure is carried forward as a shortfall. Her sales are ₹4 lakh, ₹10 lakh and ₹5 lakh in three months. How much is she paid in total?","options":["₹1,10,000","₹95,000","₹90,000","₹1,00,000"],"answer":3,"explanation":"Month 1: commission ₹20,000, paid ₹30,000, shortfall ₹10,000. Month 2: ₹50,000 − ₹10,000 = ₹40,000 paid. Month 3: ₹25,000, paid ₹30,000 (₹5,000 carried). Total ₹1,00,000. ₹1,10,000 treats the draw as non-recoverable, and ₹95,000 is commission alone.","difficulty":"very-hard","source":"Sales HR · MBA placement"},
  {"id":"mgmt-hr-ob-599","question":"In a promotion cycle, Department A promoted 48 of 80 men and 13 of 20 women; Department B promoted 4 of 20 men and 20 of 80 women. Overall, 52% of men and 33% of women were promoted. Which reading is correct?","options":["Women had a higher promotion rate in both departments; the overall gap arises because most women applied in the department that promotes few people","The overall gap proves bias against women, because aggregate data are more reliable than department data","Men had a higher promotion rate in both departments, which the overall figures confirm","The data are inconsistent, since a group cannot do better in every part and worse overall"],"answer":0,"explanation":"Women: 65% vs men's 60% in A, and 25% vs 20% in B, yet overall 33% vs 52%, because 80% of women applied to B, where only about a quarter are promoted. This is Simpson's paradox: the mix of applications, not the department decisions, creates the aggregate gap (though why women cluster in B may still deserve a look).","difficulty":"very-hard","source":"HR analytics · consulting · MBA placement"},
  {"id":"mgmt-hr-ob-600","question":"A firm of 400 staff has 20% annual attrition and a replacement cost of ₹3 lakh per leaver. A ₹40 lakh retention programme is expected to cut attrition to 15%. What is the programme's net effect for the year?","options":["A loss of ₹28 lakh","A gain of ₹20 lakh","A gain of ₹60 lakh","A gain of ₹1.4 crore"],"answer":1,"explanation":"Leavers fall from 80 to 60, saving 20 × ₹3 lakh = ₹60 lakh, less ₹40 lakh cost = ₹20 lakh net gain. Reading the 5-point drop as 5% of the 80 leavers (4 people) gives a ₹28 lakh loss; ₹60 lakh forgets the programme cost.","difficulty":"hard","source":"HR analyst · MBA placement"},
  {"id":"mgmt-hr-ob-601","question":"Assume this rule for registering a trade union of workmen: at least 7 members, and also not less than 10% of the workmen in the establishment or 100 workmen, whichever is less. A group of 80 workmen wants to register a union. In which establishment can it apply?","options":["One with 1,500 workmen","One with 1,000 workmen","One with 750 workmen","One with 900 workmen"],"answer":2,"explanation":"The requirement is min(10%, 100): 1,500 → 100, 1,000 → 100, 900 → 90, 750 → 75. Only at 750 do 80 workmen meet it. Taking 'whichever is less' to mean 'always 100' or forgetting the cap at 100 both lead to wrong picks.","difficulty":"moderate","source":"HR · labour law · MBA placement"},
  {"id":"mgmt-hr-ob-602","question":"Under India's Employees' Compensation Act, an employer is generally liable for personal injury caused by an accident arising out of and in the course of employment. In which case does the employer escape liability?","options":["A worker who is drunk on duty falls from a ladder and dies","A worker removes a machine guard to work faster and loses both hands, causing permanent total disablement","A worker carelessly slips on the shop floor and breaks a leg, with no intoxication or disobedience involved","A worker ignores a written safety order and suffers a fractured wrist that heals fully"],"answer":3,"explanation":"The statutory exceptions (influence of drink or drugs, wilful disobedience of a safety rule, wilful removal of a safety guard) apply only to injuries that do not cause death or permanent total disablement. Ordinary carelessness is no defence, and the death and permanent total disablement cases stay compensable even with the misconduct.","difficulty":"very-hard","source":"HR · labour law · MBA placement"},
  {"id":"mgmt-hr-ob-603","question":"A sales head puts the 20 lowest-rated reps of last year through an intensive coaching programme. This year their average rating rises noticeably, while the rest of the team's average barely moves. What is the most important caution before crediting the coaching?","options":["The rise may be regression to the mean, because people picked for extreme low scores tend to score closer to average next time anyway","The rise must be a Hawthorne effect and nothing else","Coaching cannot work for low performers, so the data must be wrong","The gain is genuine because the comparison group did not improve"],"answer":0,"explanation":"Selecting people for an extreme score partly selects bad luck, so their next score drifts towards the average even with no treatment. A fair test would compare coached and uncoached reps who were equally low last year, ideally assigned at random.","difficulty":"very-hard","source":"HR analytics · consulting · MBA placement"},
  {"id":"mgmt-hr-ob-604","question":"Four managers privately think a weekend offsite is a bad idea, but each assumes the others want it, so all agree and later admit nobody wanted to go. How does this differ from groupthink?","options":["It is groupthink, since the group reached a poor unanimous decision","In the Abilene paradox members misread each other's real preferences and agree to avoid disagreement, whereas groupthink is a cohesive group suppressing doubts to protect consensus","It is social loafing, since nobody put in effort to object","It is group polarisation, since the group moved to a more extreme choice"],"answer":1,"explanation":"Harvey's Abilene paradox is a failure to manage agreement: everyone privately agrees, but they wrongly believe the others disagree. Groupthink involves pressure to conform within a cohesive group that actually supports the view.","difficulty":"hard","source":"Consulting · HR · MBA placement"},
  {"id":"mgmt-hr-ob-605","question":"A veteran master blender at a tea company records videos and writes a detailed guide explaining how she judges leaf quality, which until now only she knew by feel. In Nonaka's SECI model, which conversion is this?","options":["Socialisation","Combination","Externalisation","Internalisation"],"answer":2,"explanation":"Turning tacit know-how into explicit, shareable form is externalisation. Socialisation is tacit-to-tacit (apprenticeship), combination is explicit-to-explicit (merging documents), and internalisation is explicit-to-tacit (learning by doing from a manual).","difficulty":"hard","source":"Consulting · HR · MBA placement"},
  {"id":"mgmt-hr-ob-606","question":"In a hospital emergency department, doctors, nurses, lab staff and radiologists constantly pass a patient back and forth, each one's work depending on the others' latest output. According to Thompson, what type of interdependence is this, and how is it best coordinated?","options":["Pooled; standard rules and procedures","Sequential; plans and schedules","Reciprocal; standard rules and procedures","Reciprocal; mutual adjustment through close, ongoing communication"],"answer":3,"explanation":"When outputs flow back and forth, interdependence is reciprocal, the most demanding kind, and it needs mutual adjustment (meetings, teams, co-location). Rules suit pooled interdependence and schedules suit sequential flows.","difficulty":"hard","source":"Consulting · MBA placement"},
  {"id":"mgmt-hr-ob-607","question":"A manager asks a team member, \"Do you know where the quarterly report is?\" The team member snaps back, \"Why do you always blame me when something goes missing?\" In transactional analysis, this is:","options":["A crossed transaction: an Adult-to-Adult question met with a Child-to-Parent reply","A complementary transaction between two Adults","An ulterior transaction with a hidden psychological message","A complementary Parent-to-Child transaction"],"answer":0,"explanation":"The question was a neutral Adult-to-Adult request, but the reply came from the Child ego state aimed at a perceived Parent. When the response does not come back on the line it was sent, the transaction is crossed and communication breaks down.","difficulty":"hard","source":"HR · OB · MBA placement"},
  {"id":"mgmt-hr-ob-608","question":"During an 18-month restructuring, a finance manager first feels shaken, then works long hours and copes well for over a year, and finally becomes exhausted, gets ill often and loses interest. In Selye's general adaptation syndrome, which stage does the final phase show?","options":["Alarm","Resistance","Exhaustion","Recovery"],"answer":2,"explanation":"GAS runs alarm → resistance → exhaustion. Coping well for a long time is resistance; when the body's resources run out under continued stress, exhaustion sets in, with illness and burnout. 'Recovery' is not a GAS stage.","difficulty":"moderate","source":"HR · OB · MBA placement"},
  {"id":"mgmt-hr-ob-609","question":"A trainee runs her first client workshop, writes up what went well and badly, links this to a facilitation model from a course, and then tries a changed approach at the next workshop. In Kolb's experiential learning cycle, what is the correct order of these stages?","options":["Abstract conceptualisation → concrete experience → active experimentation → reflective observation","Concrete experience → reflective observation → abstract conceptualisation → active experimentation","Reflective observation → concrete experience → active experimentation → abstract conceptualisation","Concrete experience → active experimentation → reflective observation → abstract conceptualisation"],"answer":1,"explanation":"Kolb's cycle: do (concrete experience), review (reflective observation), conclude by linking to theory (abstract conceptualisation), and try it out (active experimentation). The trainee's steps follow exactly that order.","difficulty":"hard","source":"HR · L&D · MBA placement"},
  {"id":"mgmt-hr-ob-610","question":"A senior consultant leaves a top firm to work as a freelancer at lower pay, saying she cannot stand fixed hours, dress codes and having to follow the firm's way of doing things. Which of Schein's career anchors does this show?","options":["Security and stability","Technical/functional competence","General managerial competence","Autonomy and independence"],"answer":3,"explanation":"Giving up money and status to escape organisational rules and work on her own terms reflects the autonomy/independence anchor. A security anchor would do the opposite, and nothing suggests a pull towards managing others.","difficulty":"moderate","source":"HR · career management · MBA placement"},
  {"id":"mgmt-hr-ob-611","question":"A plant manager orders night-shift staff to stay an extra hour to clear a backlog. They comply without question. Later she tells them to skip their lawful rest breaks for a month, and they refuse en masse. Which idea best explains this?","options":["Chester Barnard's acceptance theory: authority depends on subordinates accepting orders, and orders within their zone of indifference are obeyed without question","Weber's view that legal-rational authority is always obeyed","Fayol's unity of command","Taylor's functional foremanship"],"answer":0,"explanation":"Barnard argued that authority flows upward from acceptance; orders inside the zone of indifference pass unquestioned, while orders seen as unreasonable or unlawful fall outside it and are refused regardless of formal position.","difficulty":"hard","source":"Principles of management · MBA placement"},
  {"id":"mgmt-hr-ob-612","question":"A sales head wants the windows of a meeting room open for fresh air; the finance head wants them shut so papers don't blow away. They agree to open the windows of the adjoining empty room instead. Which management thinker's idea does this illustrate, and how?","options":["Taylor: a scientific study found the one best way","Mary Parker Follett: integration, which finds a solution meeting both parties' real interests, rather than domination or compromise","Fayol: subordination of individual interest to the general interest","Weber: following a written rule removed the dispute"],"answer":1,"explanation":"This is Follett's own classic illustration of integration: neither side wins or gives up half; both underlying needs (air, undisturbed papers) are met. Compromise would mean half-open windows that satisfy neither fully.","difficulty":"very-hard","source":"Principles of management · MBA placement"},
  {"id":"mgmt-hr-ob-613","question":"A gig-delivery platform offers riders clear per-order pay and nothing more, and riders expect nothing beyond prompt payment. A family-run engineering firm offers lifelong job security and mentoring, and its staff give loyalty and extra effort in return. In psychological-contract terms, these are:","options":["Relational and transactional, respectively","Both relational, as both involve mutual expectations","Transactional and relational, respectively","Both transactional, as both involve pay"],"answer":2,"explanation":"Transactional contracts are short-term, narrow and economic; relational contracts are long-term, open-ended and built on loyalty and development. The platform-rider deal is transactional and the family firm's is relational.","difficulty":"hard","source":"HR · OB · MBA placement"},
  {"id":"mgmt-hr-ob-614","question":"A company makes a fair, data-based decision to freeze bonuses and explains the reasons clearly, but the CEO announces it by mocking staff who 'expected handouts'. In Colquitt's model, which form of organisational justice is violated?","options":["Distributive justice","Procedural justice","Informational justice","Interpersonal justice"],"answer":3,"explanation":"Interpersonal justice is about being treated with dignity and respect. The outcome rules (distributive), the decision process (procedural) and the explanation (informational) are all fine here; only the demeaning manner is unfair.","difficulty":"hard","source":"HR · OB · MBA placement"},
  {"id":"mgmt-hr-ob-615","question":"A hospital cleaner starts chatting with lonely long-stay patients, rearranges the order of her rounds to avoid disturbing their rest, and comes to see herself as part of the healing team. No one redesigned her job. What is this called?","options":["Job crafting","Job enrichment","Job rotation","Job enlargement"],"answer":0,"explanation":"Job crafting (Wrzesniewski and Dutton) is employees themselves reshaping their tasks, relationships and view of their work. Enrichment, rotation and enlargement are redesigns imposed by management.","difficulty":"hard","source":"HR · OB · MBA placement"},
  {"id":"mgmt-hr-ob-616","question":"After one widely reported case of a new joiner leaking client data, a manager insists that every new hire be barred from client systems for six months, although the firm has hired hundreds without any such incident. Which bias is most at work?","options":["Anchoring","Availability heuristic","Escalation of commitment","Self-serving bias"],"answer":1,"explanation":"A vivid, recent, easily recalled event makes the risk seem far more likely than the base rate (one incident in hundreds) justifies. This is judging probability by ease of recall.","difficulty":"moderate","source":"Consulting · HR · MBA placement"},
  {"id":"mgmt-hr-ob-617","question":"Research on board and CEO appointments finds that women are more likely than men to be appointed to lead firms that are already in crisis or falling sharply, which raises their risk of failure. What is this pattern called?","options":["Glass ceiling","Sticky floor","Glass cliff","Queen bee syndrome"],"answer":2,"explanation":"The glass cliff (Ryan and Haslam) describes women getting top roles mainly in precarious situations. The glass ceiling blocks women from reaching the top at all, and the sticky floor keeps them in low-level jobs.","difficulty":"hard","source":"HR · diversity · MBA placement"},
  {"id":"mgmt-hr-ob-618","question":"An FMCG company keeps a small core of permanent managers, outsources logistics and IT to specialist firms on contract, and uses a pool of temporary and seasonal staff for peak periods. Which model describes this structure?","options":["Weber's bureaucracy","Burns and Stalker's organic structure","A matrix structure","Handy's shamrock organisation"],"answer":3,"explanation":"Handy's shamrock has three leaves: the professional core, the contractual fringe (outsourced specialists) and the flexible labour force (temporary staff). The case maps onto all three.","difficulty":"hard","source":"Principles of management · consulting · MBA placement"},
  {"id":"mgmt-hr-ob-619","question":"A rival copies a retailer's training manuals, pay scales and appraisal forms but still cannot match the retailer's service, which comes from a trusting culture built over 20 years. In resource-based terms, why does this HR advantage last?","options":["It is valuable, rare and hard to imitate because it is path-dependent and socially complex","It is protected by patents and copyright on the manuals","Any HR practice that is costly is automatically a lasting advantage","The rival lacks money, which is the only barrier to imitation"],"answer":0,"explanation":"Under the VRIO view, written practices are easy to copy, but a culture built over time (path dependence) through countless relationships (social complexity) cannot be bought or replicated quickly, so the advantage lasts.","difficulty":"very-hard","source":"Strategic HRM · consulting · MBA placement"},
  {"id":"mgmt-hr-ob-620","question":"On a shop floor, eight volunteers from the same section meet for an hour each week under their supervisor to identify, analyse and solve quality problems in their own work area, and present solutions to management. What is this?","options":["A works committee","A quality circle","A joint management council","A cross-functional task force"],"answer":1,"explanation":"A quality circle is a small voluntary group from one work area meeting regularly to solve work-related problems. A works committee is a statutory bipartite body, and a task force draws members from many functions for one project.","difficulty":"moderate","source":"HR · industrial relations · MBA placement"},
  {"id":"mgmt-hr-ob-621","question":"Under a collective agreement, employees need not join the union, but non-members in the bargaining unit must pay the union a fee equal to its dues, because they benefit from the contract it negotiates. What is this arrangement?","options":["A closed shop","A union shop","An agency shop","An open shop"],"answer":2,"explanation":"An agency shop requires a service fee but not membership. A closed shop hires only union members, a union shop requires new hires to join within a set period, and an open shop requires neither membership nor fees.","difficulty":"hard","source":"HR · industrial relations · MBA placement"},
  {"id":"mgmt-hr-ob-622","question":"In an industrial dispute, which statement correctly separates the methods of settlement?","options":["A conciliation officer issues an award that binds both parties","Arbitration is always compulsory and is imposed by the government","Adjudication is a voluntary process in which the parties choose their own judge","A conciliator only helps the parties reach their own settlement, while adjudication by a labour court or tribunal gives a binding award"],"answer":3,"explanation":"Conciliation is facilitated negotiation with no power to impose terms. Voluntary arbitration is chosen by the parties, and adjudication is the compulsory, binding route through labour courts and tribunals.","difficulty":"hard","source":"HR · industrial relations · MBA placement"},
  {"id":"mgmt-hr-ob-623","question":"Match each situation with the correct term.\nA. Power shortage stops work; workers on the rolls are not given work for a few days\nB. The employer terminates surplus workers' services permanently for reasons other than discipline\nC. The employer temporarily shuts the gates to put pressure on workers in a dispute\nD. The employer permanently shuts down the place of employment\n1. Closure  2. Lay-off  3. Lockout  4. Retrenchment","options":["A-2, B-4, C-3, D-1","A-3, B-4, C-2, D-1","A-2, B-1, C-3, D-4","A-4, B-2, C-1, D-3"],"answer":0,"explanation":"Lay-off is a temporary inability to give work to workers who stay on the rolls; retrenchment permanently ends surplus workers' service; a lockout is a temporary shutdown used as a bargaining weapon; closure is permanent shutdown of the workplace.","difficulty":"very-hard","source":"HR · labour law · MBA placement"},
  {"id":"mgmt-hr-ob-624","question":"A union leader is loudly opposing a new performance-management system. The HR head offers her a visible seat on the design committee, mainly to win her public endorsement, though the design is largely settled. In Kotter and Schlesinger's terms, what is this, and what is its main risk?","options":["Participation; it is slow but always builds genuine commitment","Co-optation; if she realises she is being used, resistance can grow stronger","Coercion; it creates immediate compliance with no risk","Education; it fails when people already have accurate information"],"answer":1,"explanation":"Giving a resister a symbolic role to buy endorsement is co-optation, a form of manipulation. It is quick and cheap, but backfires if the person feels tricked. Real participation would let her shape the design.","difficulty":"hard","source":"HR · change management · MBA placement"},
  {"id":"mgmt-hr-ob-625","question":"A bank's bonus policy has two provisions: (1) unvested deferred bonus can be reduced or cancelled if misconduct comes to light, and (2) bonus already paid can be recovered from the executive. What are these called?","options":["Both are clawback","Vesting and cliff respectively","Malus and clawback respectively","Clawback and malus respectively"],"answer":2,"explanation":"Malus cuts or cancels awards that have not yet vested or been paid; clawback recovers amounts already paid out. Treating both as clawback misses the timing distinction regulators use.","difficulty":"very-hard","source":"HR · compensation · MBA placement"},
  {"id":"mgmt-hr-ob-626","question":"Which interview question is a situational (future-oriented) question rather than a behavioural (past-oriented) one?","options":["Tell me about a time you missed a deadline and how you handled it.","Describe the most difficult customer you have dealt with.","Give an example of when you persuaded a sceptical manager.","Suppose a key supplier calls a day before launch to say the order will be a week late. What would you do?"],"answer":3,"explanation":"Situational questions pose a hypothetical scenario and ask what the candidate would do; behavioural questions ask what the candidate actually did in a past situation. The other three all ask for past examples.","difficulty":"moderate","source":"HR · recruitment · MBA placement"},
  {"id":"mgmt-hr-ob-627","question":"An analytics team finds that teams with higher engagement scores also have higher sales, and concludes that an engagement programme will raise sales. Which objection is strongest?","options":["Success may drive engagement as much as engagement drives success, and a third factor such as a good manager may drive both","Correlation is always zero when sample sizes are small","Engagement is a hygiene factor, so it cannot affect performance","The finding must be wrong because sales are measured in rupees and engagement in percentages"],"answer":0,"explanation":"A cross-sectional correlation cannot show direction: winning teams feel engaged (reverse causality), and good managers can lift both (confounding). A pilot with comparison groups or a time-lagged analysis is needed before investing.","difficulty":"very-hard","source":"HR analytics · consulting · MBA placement"},
  {"id":"mgmt-hr-ob-628","question":"To find out what makes people leave, an HR team surveys only its current employees on what they like about the company, and finds few complaints about pay. Why might this mislead?","options":["Current employees always exaggerate complaints","It suffers from survivorship bias: those most unhappy with pay may already have left and are missing from the sample","Pay can never be a reason for attrition","Surveys of current staff are illegal under data-privacy rules"],"answer":1,"explanation":"Sampling only those who stayed filters out exactly the people who found the deal unacceptable. Exit-interview data or a survey of recent leavers is needed to see why people go.","difficulty":"hard","source":"HR analytics · MBA placement"},
  {"id":"mgmt-hr-ob-629","question":"A woman is the only female engineer in a 30-person plant team. She is highly visible, her mistakes are widely discussed, and colleagues keep treating her as a representative of 'women in engineering'. Which concept from Rosabeth Moss Kanter explains this?","options":["Glass cliff","Social loafing","Tokenism","Role ambiguity"],"answer":2,"explanation":"Kanter showed that when a group makes up a tiny share of a team (a 'token'), its members face heightened visibility, exaggerated differences and stereotyped roles. The effects fade as the minority's share grows.","difficulty":"hard","source":"HR · diversity · MBA placement"},
  {"id":"mgmt-hr-ob-630","question":"A committee given four weeks to draft a two-page policy note produces it in the last few days, after weeks of meetings that achieve little. Given two weeks for a similar note the next year, it again finishes just in time. Which observation does this illustrate?","options":["The Peter principle","Gresham's law of planning","Escalation of commitment","Parkinson's law"],"answer":3,"explanation":"Parkinson's law says work expands to fill the time available for its completion. The Peter principle is about promotion to incompetence, and Gresham's law of planning says routine work drives out planning.","difficulty":"moderate","source":"Principles of management · MBA placement"},
  {"id":"mgmt-hr-ob-631","question":"A manager is told, wrongly, that three new trainees were weak in the selection tests. She gives them fewer challenging tasks and less feedback, and by year-end they do perform below their peers. What is this effect?","options":["The Golem effect","The Pygmalion effect","The Galatea effect","The halo effect"],"answer":0,"explanation":"The Golem effect is the negative self-fulfilling prophecy: low expectations from a leader lead to treatment that lowers performance. Pygmalion is the positive version, and Galatea is about a person's own self-expectations.","difficulty":"hard","source":"HR · OB · MBA placement"},
  {"id":"mgmt-hr-ob-632","question":"Chris Argyris argued that healthy adults move from passivity, dependence and short time horizons towards activity, independence and long time horizons. What was his main criticism of formal organisations?","options":["They give employees too much freedom, which causes confusion","Rigid structure, narrow tasks and close control keep adults in an immature, dependent state, creating frustration and conflict","They ignore the physiological needs of workers","They rely too much on informal groups"],"answer":1,"explanation":"Argyris's immaturity–maturity theory says classical design (specialisation, unity of command, tight control) treats adults like children, clashing with their need to grow. He recommended job enlargement and participative leadership.","difficulty":"hard","source":"Principles of management · OB · MBA placement"},
  {"id":"mgmt-hr-ob-633","question":"In a talent review using a nine-box grid, an employee is rated low on current performance but high on potential. What should the HR business partner do first?","options":["Put her on an exit plan, since performance is what counts","Promote her at once, since potential matters more than performance","Diagnose why a high-potential person is underperforming (wrong role, new joiner, manager fit, personal issues) and act on that","Rate her potential down so that the two axes agree"],"answer":2,"explanation":"Performance and potential are separate axes; low performance with high potential flags a puzzle to diagnose, often a fit or onboarding issue. Exiting or promoting without diagnosis, or forcing the ratings to agree, defeats the purpose of the grid.","difficulty":"hard","source":"HR · talent management · MBA placement"},
  {"id":"mgmt-hr-ob-634","question":"Inflation is 0%. Firm X cuts wages by 3%. In another year with 6% inflation, Firm Y freezes wages. Surveys show most people call X's action unfair but Y's acceptable, though Y's workers lose more purchasing power. What best explains this?","options":["Workers correctly judge real wages, and Y's loss is smaller","Equity theory, since both firms compare workers with outsiders","Herzberg's theory, since pay is a hygiene factor","People judge pay against a nominal reference point, so a visible nominal cut feels like a loss while an inflation-driven real cut does not"],"answer":3,"explanation":"Kahneman, Knetsch and Thaler found fairness judgements anchor on nominal wages (money illusion and loss aversion). Y's real cut (about 6%) is bigger than X's 3%, so the 'smaller loss' reading is wrong.","difficulty":"very-hard","source":"HR · behavioural economics · MBA placement"},
  {"id":"mgmt-hr-ob-635","question":"New analysts must learn a complex modelling task they have never done before. Which goal is most likely to produce the best performance in the first months, according to later goal-setting research?","options":["A specific learning goal, such as mastering five valuation methods","A specific, very hard output goal, such as finishing 20 models a week","A 'do your best' goal","No goal, to avoid pressure"],"answer":0,"explanation":"Seijts and Latham found that when people lack the knowledge for a complex task, hard performance goals push them to rush and use poor strategies, while specific learning goals help them find good strategies first. Hard output goals work best once skills are in place.","difficulty":"very-hard","source":"HR · OB · MBA placement"},
  {"id":"mgmt-hr-ob-636","question":"According to Bandura, which source builds self-efficacy most strongly for a hesitant new sales trainee?","options":["Hearing her manager say 'You can do it'","Successfully closing several small deals herself","Watching a colleague close a deal","Feeling calm before a meeting"],"answer":1,"explanation":"Mastery (enactive) experience, actually succeeding, is the strongest source. Vicarious experience, verbal persuasion and physiological states also help, but less reliably.","difficulty":"hard","source":"HR · OB · MBA placement"},
  {"id":"mgmt-hr-ob-637","question":"A product team has four young women from marketing and four older men from engineering. In meetings it splits along exactly this line, with each half sticking together. A second team, equally diverse, mixes ages, genders and functions across people and splits much less. What explains the difference?","options":["The first team is simply more diverse","The second team has more social loafing","The first team has strong faultlines: several attributes line up to form clear subgroups","The first team is in the norming stage"],"answer":2,"explanation":"Faultlines (Lau and Murnighan) form when several demographic attributes align on the same people, creating sharp subgroups. Equal diversity spread across cross-cutting attributes weakens such divides.","difficulty":"very-hard","source":"HR · OB · consulting · MBA placement"},
  {"id":"mgmt-hr-ob-638","question":"A company tracks how many of the 500 people employed a year ago are still employed today: 420 are. Headcount today is 560. What is its labour stability index?","options":["75%","92%","80%","84%"],"answer":3,"explanation":"Stability index = employees with a year or more of service now ÷ total employed a year ago = 420/500 = 84%. Dividing by today's headcount (420/560 = 75%) mixes in new hires who could not have stayed a year.","difficulty":"hard","source":"HR analyst · MBA placement"},
  {"id":"mgmt-hr-ob-639","question":"An in-house sales course costs ₹6 lakh to develop and run plus ₹5,000 per trainee for materials. An external provider charges ₹20,000 per trainee. Above how many trainees does the in-house option become cheaper?","options":["40","30","24","120"],"answer":0,"explanation":"In-house cost equals external cost when 6,00,000 + 5,000n = 20,000n, giving n = 40. Dividing ₹6 lakh by ₹20,000 (30) ignores the in-house variable cost.","difficulty":"hard","source":"HR · L&D · MBA placement"},
  {"id":"mgmt-hr-ob-640","question":"An employee earns ₹1,14,000 a month; her grade's maximum is ₹1,20,000. She earns a 7% merit increase. Policy raises base pay only up to the range maximum and pays the rest of the increase each month as a lump sum, totalled annually. What is her annual lump-sum payment?","options":["₹95,760","₹23,760","₹72,000","Nil, since she is close to the maximum"],"answer":1,"explanation":"The 7% raise is ₹7,980 a month; base rises by only ₹6,000 to reach ₹1,20,000, so ₹1,980 a month (₹23,760 a year) is paid as a lump sum. ₹95,760 pays the whole raise as a lump sum and ₹72,000 is the base increase.","difficulty":"very-hard","source":"HR · compensation · MBA placement"},
  {"id":"mgmt-hr-ob-641","question":"A selection test's standard error of measurement is 3. HR uses a band of 1.96 × the standard error of the difference (SED = SEM × √2) below the top score of 92, treating everyone inside the band as equal. Other candidates scored 90, 87, 86, 84 and 83. How many of them fall in the band?","options":["2","1","4","5"],"answer":2,"explanation":"SED = 3 × √2 ≈ 4.24; band width = 1.96 × 4.24 ≈ 8.3, so the band runs down to about 83.7. Scores 90, 87, 86 and 84 are inside; 83 is not. Using 1.96 × SEM (≈ 5.9) keeps only two, and SED alone keeps only one.","difficulty":"very-hard","source":"HR analyst · MBA placement"},
  {"id":"mgmt-hr-ob-642","question":"A manager tells a junior that inflating a client's invoice is 'just creative billing', adds that 'everyone in the industry does it', and that 'the decision came from above anyway'. Which concept from Bandura best describes this reasoning?","options":["Cognitive dissonance","Self-serving bias","Groupthink","Moral disengagement through euphemistic labelling, advantageous comparison and displacement of responsibility"],"answer":3,"explanation":"Bandura's moral disengagement mechanisms let people do wrong without guilt: renaming the act ('creative billing'), comparing it with others' worse conduct, and shifting responsibility to authority.","difficulty":"very-hard","source":"HR · ethics · MBA placement"},
  {"id":"mgmt-hr-ob-643","question":"A large FMCG firm wants to keep running its mature detergent business efficiently while also building a risky direct-to-consumer startup. It sets up the startup as a separate unit with its own structure, culture and incentives, linked to the core only through a senior leader who allocates resources. What is this approach called?","options":["Structural ambidexterity","Contextual ambidexterity","Functional structure","Mechanistic design"],"answer":0,"explanation":"Structural ambidexterity (O'Reilly and Tushman) separates exploration and exploitation into different units, integrated at the top. Contextual ambidexterity asks the same people to switch between both within one unit.","difficulty":"hard","source":"Strategy · OB · consulting · MBA placement"},
];

export default questions;
